export default " worse than a leak in a different direction: it propagates into the\\n            # caller's broad except and drops the whole record.\\n            #\\n            # `code` is whatever was in the response JSON, so it can equally be a dict or a list.\\n            # The type check covers that too.\\n            canonical = _KNOWN_PROVIDER_ERROR_CODES.get(code) if type(code) is str else None\\n            if canonical is not None:\\n                attributes[\\\"error.code\\\"] = canonical\\n    return attributes\\n\\n\\ndef _first_int(source: Any, names: tuple[str, ...]) -> int | None:\\n    \\\"\\\"\\\"Read the first of *names* off *source* that is a plain int.\\n\\n    ``getattr`` on a third-party exception can run a property, so it is guarded: telemetry must\\n    never be the thing that turns a handled provider error into an unhandled one. Suppressed\\n    rather than logged, because this runs inside the log processor chain and reporting it would\\n    re-enter here. ``bool`` is excluded because it is an ``int`` and a status of ``True`` is\\n    nonsense.\\n    \\\"\\\"\\\"\\n    for name in names:\\n        value = None\\n        with contextlib.suppress(Exception):\\n            value = getattr(source, name, None)\\n        if isinstance(value, int) and not isinstance(value, bool):\\n            return value\\n    return None\\n\\n\\ndef emit_to_otel_logs(_logger: Any, _method_name: str, event_dict: dict[str, Any]) -> dict[str, Any]:\\n    \\\"\\\"\\\"Ship the record to the configured OTel log pipeline, then hand it back unchanged.\\n\\n    A pass-through: this sits in the processor chain purely for the side effect, so console\\n    and file output are unaffected. When no SDK logger provider is installed -- bare lfx, or\\n    Langflow with no OTLP endpoint configured -- ``get_logger`` returns a no-op and this costs\\n    one attribute lookup.\\n\\n    Placed after the redaction processor so anything scrubbed there is scrubbed here too.\\n    Trace correlation is left to the SDK, which reads the active span from the context, so a\\n    log line emitted inside a flow execution lands on that flow's trace in the APM.\\n\\n    The body only leaves the process when its scope is allowlisted. Severity decides whether a\\n    record is exported at all; this decides whether its text is, and the two are separate because\\n    an operator wants to know a request failed at ERROR whether or not they are allowed to see\\n    the sentence describing it. A withheld record is not a dropped one -- it keeps its severity,\\n    scope, callsite, root-cause class and trace correlation, which is what a pivot from a failed\\n    trace actually needs.\\n    \\\"\\\"\\\"\\n    if _otel_logs is None:\\n        return event_dict\\n\\n    severity = _OTEL_LOG_SEVERITY.get(str(event_dict.get(\\\"level\\\", \\\"\\\")).lower())\\n    if severity is None or severity < _otel_min_severity():\\n        return event_dict\\n\\n    # Popped, not read: the marker is an instruction to this processor and must not reach the\\n    # console renderer, the JSON file or the log buffer.\\n    declared = event_dict.pop(_OTEL_EXPORT_BODY_KEY, False) is True\\n    export_body = declared or _otel_body_policy() == \\\"all\\\"\\n    # Anonymous callers have no logger name; group them under the package rather than \\\"\\\".\\n    scope = event_dict.get(\\\"logger\\\") or \\\"lfx\\\"\\n\\n    try:\\n        if export_body:\\n            body = str(event_dict.get(\\\"event\\\", \\\"\\\"))\\n            keep = event_dict.items()\\n        else:\\n            body = _OTEL_WITHHELD_BODY\\n            keep = ((k, v) for k, v in event_dict.items() if k in _OTEL_SKELETON_KEYS)\\n\\n        attributes = {\\n            k: v if isinstance(v, str | bool | int | float) else str(v)\\n            for k, v in keep\\n            if k not in _OTEL_LOG_SKIP_KEYS and v is not None\\n        }\\n\\n        # Derived last so it wins: these are the trustworthy names, and an event dict carrying\\n        # its own \\\"error.type\\\" key would otherwise shadow the one read off the live exception.\\n        exception = _exception_from(event_dict.get(\\\"exc_info\\\"))\\n        if exception is not None:\\n            root, chain = _error_identity(exception)\\n            attributes[\\\"error.type\\\"] = root\\n            if chain != root:\\n                attributes[\\\"error.chain\\\"] = chain\\n            attributes.update(_error_transport_identity(exception))\\n\\n        otel_logger = _otel_logs.get_logger(scope)\\n        otel_logger.emit(\\n            body=body,\\n            severity_number=_OtelSeverity(severity),\\n            severity_text=str(event_dict.get(\\\"level\\\", \\\"\\\")).upper(),\\n            attributes=attributes,\\n        )\\n    except Exception:  # noqa: BLE001 - logging must never break on a flaky exporter\\n        return event_dict\\n    return event_dict\\n\\n\\ndef otel_log_bodies_exported() -> bool:\\n    \\\"\\\"\\\"Whether message bodies leave the process for scopes that are not allowlisted.\\n\\n    Public because the bootstrap states the boundary in its startup line and must describe the\\n    policy actually in force, not the default.\\n    \\\"\\\"\\\"\\n    return _otel_body_policy() == \\\"all\\\"\\n\\n\\ndef operator_logger() -> Any:\\n    \\\"\\\"\\\"A logger whose message bodies are allowed to cross the OTLP boundary.\\n\\n    For operator statements about the runtime itself -- what got configured, what is exporting\\n    where -- which are assembled from constants and identifiers and carry no flow data. Anything\\n    that formats a component's output, a provider response or an exception message belongs on\\n    the ordinary module-level ``logger`` instead, where the body is withheld.\\n\\n    The scope name is for grouping in the APM; the bound marker is what actually opts the body\\n    in, so this cannot be obtained by naming a module after the scope.\\n    \\\"\\\"\\\"\\n    return structlog.get_logger(OPERATOR_LOG_SCOPE).bind(**{_OTEL_EXPORT_BODY_KEY: True})\\n\\n\\ndef _apply_logger_level_overrides() -> None:\\n    \\\"\\\"\\\"Apply ``LANGFLOW_LOG_LEVELS`` env var: ``name=LEVEL,name=LEVEL,...``.\\n\\n    Used to quiet noisy third-party loggers (``sqlalchemy.engine``, ``httpx``,\\n    ``httpcore``, ``urllib3``) in production without changing global defaults.\\n\\n    Malformed entries (missing ``=``, unknown level, empty name) raise a\\n    warning instead of being silently dropped so operators see typos like\\n    ``WARN`` instead of ``WARNING``.\\n    \\\"\\\"\\\"\\n    raw = os.getenv(\\\"LANGFLOW_LOG_LEVELS\\\", \\\"\\\").strip()\\n    if not raw:\\n        return\\n    for pair in raw.split(\\\",\\\"):\\n        entry = pair.strip()\\n        if not entry:\\n            continue\\n        if \\\"=\\\" not in entry:\\n            warnings.warn(\\n                f\\\"LANGFLOW_LOG_LEVELS: ignoring {entry!r} (expected 'name=LEVEL')\\\",\\n                stacklevel=2,\\n            )\\n            continue\\n        name, _, level = entry.partition(\\\"=\\\")\\n        name = name.strip()\\n        level_str = level.strip().upper()\\n        if not name:\\n            warnings.warn(\\n                f\\\"LANGFLOW_LOG_LEVELS: ignoring {entry!r} (empty logger name)\\\",\\n                stacklevel=2,\\n            )\\n            continue\\n        numeric = LOG_LEVEL_MAP.get(level_str)\\n        if numeric is None:\\n            warnings.warn(\\n                f\\\"LANGFLOW_LOG_LEVELS: ignoring {entry!r} (unknown level {level_str!r}, \\\"\\n                f\\\"expected one of {sorted(LOG_LEVEL_MAP)})\\\",\\n                stacklevel=2,\\n            )\\n            continue\\n        logging.getLogger(name).setLevel(numeric)\\n\\n\\ndef buffer_writer(_logger: Any, _method_name: str, event_dict: dict[str, Any]) -> dict[str, Any]:\\n    \\\"\\\"\\\"Write to log buffer if enabled.\\\"\\\"\\\"\\n    if log_buffer.enabled() and \\\"serialized\\\" in event_dict:\\n        # Use the already-serialized version prepared by add_serialized()\\n        # This avoids duplicate serialization and ensures consistency\\n        serialized_bytes = event_dict[\\\"serialized\\\"]\\n        log_buffer.write(serialized_bytes.decode(\\\"utf-8\\\"))\\n    return event_dict\\n\\n\\ndef _forward_loguru_message(message) -> None:\\n    \\\"\\\"\\\"Forward Loguru messages through Langflow's configured structlog pipeline.\\\"\\\"\\\"\\n    record = message.record\\n    structlog_logger = structlog.get_logger(record[\\\"name\\\"])\\n    level_name = record[\\\"level\\\"].name.lower()\\n    log_method = getattr(structlog_logger, level_name, structlog_logger.info)\\n    if record[\\\"exception\\\"]:\\n        log_method(record[\\\"message\\\"], exc_info=record[\\\"exception\\\"])\\n    else:\\n        log_method(record[\\\"message\\\"])\\n\\n\\ndef setup_loguru_logger(log_level: str, *, enqueue: bool = False) -> None:\\n    \\\"\\\"\\\"Route Loguru's default logger through Langflow logging.\\\"\\\"\\\"\\n    global _loguru_handler_id  # noqa: PLW0603\\n\\n    if _loguru_handler_id is not None:\\n        with contextlib.suppress(ValueError):\\n            loguru_logger.remove(_loguru_handler_id)\\n    else:\\n        with contextlib.suppress(ValueError):\\n            loguru_logger.remove(0)\\n\\n    _loguru_handler_id = loguru_logger.add(\\n        _forward_loguru_message,\\n        level=log_level.upper(),\\n        enqueue=enqueue,\\n        format=\\\"{message}\\\",\\n    )\\n\\n\\ndef setup_log_file(log_file: Path, *, max_bytes: int, formatter: logging.Formatter | None = None) -> None:\\n    \\\"\\\"\\\"Set up Langflow's rotating file handler.\\n\\n    ``formatter`` lets JSON modes attach a ``structlog.stdlib.ProcessorFormatter``\\n    so third-party stdlib records (uvicorn, sqlalchemy, httpx, ...) are rendered\\n    as JSON through the same processor chain as application logs. When omitted,\\n    the handler writes the message verbatim (structlog has already rendered it).\\n    \\\"\\\"\\\"\\n    global _file_handler  # noqa: PLW0603\\n\\n    if _file_handler is not None:\\n        logging.root.removeHandler(_file_handler)\\n        _file_handler.close()\\n\\n    _file_handler = logging.handlers.RotatingFileHandler(\\n        log_file,\\n        maxBytes=max_bytes,\\n        backupCount=5,\\n    )\\n    _file_handler.setFormatter(formatter if formatter is not None else logging.Formatter(\\\"%(message)s\\\"))\\n    logging.root.addHandler(_file_handler)\\n\\n\\ndef get_file_handler() -> logging.handlers.RotatingFileHandler | None:\\n    \\\"\\\"\\\"Return the rotating file handler ``setup_log_file`` installed, if any.\\n\\n    Callers that need to hand a stdlib logger a terminating handler -- rather than\\n    relying on propagation to the root logger -- reach for this. See\\n    ``langflow.server.Logger``, which has to do exactly that because\\n    ``uvicorn.workers.UvicornWorker`` copies the gunicorn handler list onto the\\n    uvicorn loggers and sets ``propagate = False``.\\n    \\\"\\\"\\\"\\n    return _file_handler\\n\\n\\ndef structlog_routes_to_stdlib() -> bool:\\n    \\\"\\\"\\\"Report whether structlog writes back out through the stdlib logging tree.\\n\\n    ``configure()`` selects ``structlog.stdlib.LoggerFactory`` whenever a log file\\n    is configured, which makes ``structlog.get_logger(name)`` resolve to *the stdlib\\n    logger of that same name*. Installing an ``InterceptHandler`` on a stdlib logger\\n    in that mode builds a cycle: the handler feeds structlog, which writes straight\\n    back out to the logger the handler is attached to. Anything that installs an\\n    intercept must check this first.\\n    \\\"\\\"\\\"\\n    if not structlog.is_configured():\\n        return False\\n    return isinstance(structlog.get_config().get(\\\"logger_factory\\\"), structlog.stdlib.LoggerFactory)\\n\\n\\nclass LogConfig(TypedDict):\\n    \\\"\\\"\\\"Configuration for logging.\\\"\\\"\\\"\\n\\n    log_level: NotRequired[str]\\n    log_file: NotRequired[Path]\\n    disable: NotRequired[bool]\\n    log_env: NotRequired[str]\\n    log_format: NotRequired[str]\\n\\n\\ndef configure(\\n    *,\\n    log_level: str | None = None,\\n    log_file: Path | None = None,\\n    disable: bool | None = False,\\n    log_env: str | None = None,\\n    log_format: str | None = None,\\n    log_rotation: str | None = None,\\n    cache: bool | None = None,\\n    output_file=None,\\n) -> None:\\n    \\\"\\\"\\\"Configure the logger.\\\"\\\"\\\"\\n    # Resolve every effective input (env-var fallbacks + level validation) up\\n    # front so the early-return below can compare a fingerprint of the *entire*\\n    # resulting configuration, not just the log level. The old check compared\\n    # only the resolved level, so a second call that changed\\n    # log_env / log_file / log_format / output_file / disable at the same level\\n    # silently no-opped -- skipping the file handler and renderer switch. That\\n    # was both a real footgun and a source of test-isolation flakiness (a prior\\n    # same-level configure() made a later file-mode configure() do nothing,\\n    # surfacing as FileNotFoundError when a test read the log file).\\n    if log_level is None and os.getenv(\\\"LANGFLOW_LOG_LEVEL\\\", \\\"\\\").upper() in VALID_LOG_LEVELS:\\n        log_level = os.getenv(\\\"LANGFLOW_LOG_LEVEL\\\")\\n    if log_level is None or log_level.upper() not in LOG_LEVEL_MAP:\\n        log_level = \\\"ERROR\\\"\\n\\n    if log_file is None:\\n        env_log_file = os.getenv(\\\"LANGFLOW_LOG_FILE\\\", \\\"\\\")\\n        log_file = Path(env_log_file) if env_log_file else None\\n\\n    if log_env is None:\\n        log_env = os.getenv(\\\"LANGFLOW_LOG_ENV\\\", \\\"\\\")\\n\\n    # Get log format from env if not provided\\n    if log_format is None:\\n        log_format = os.getenv(\\\"LANGFLOW_LOG_FORMAT\\\")\\n\\n    numeric_level = LOG_LEVEL_MAP.get(log_level.upper(), logging.ERROR)\\n\\n    # Fingerprint of every caller-supplied input that changes the resulting\\n    # setup. Stored on the wrapper_class (below) so structlog.reset_defaults()\\n    # -- used between tests -- invalidates it automatically and the next call\\n    # rebuilds from scratch. Env-only toggles (e.g. LANGFLOW_PRETTY_LOGS) are not\\n    # part of the fingerprint: the four env-backed args above are already folded\\n    # into their resolved values, and the remainder are process-stable.\\n    config_fingerprint = (\\n        numeric_level,\\n        log_env,\\n        str(log_file) if log_file is not None else None,\\n        log_format,\\n        bool(disable),\\n        log_rotation,\\n        cache if cache is not None else True,\\n        output_file,\\n    )\\n    cfg = structlog.get_config() if structlog.is_configured() else {}\\n    if getattr(cfg.get(\\\"wrapper_class\\\"), \\\"config_fingerprint\\\", None) == config_fingerprint:\\n        return\\n\\n    # Configure processors based on environment\\n    service_info = _get_service_info()\\n\\n    def _add_service_info(_logger: Any, _method_name: str, event_dict: dict[str, Any]) -> dict[str, Any]:\\n        for key, value in service_info.items():\\n            event_dict.setdefault(key, value)\\n        return event_dict\\n\\n    extra_redact = frozenset(\\n        k.strip().lower() for k in os.getenv(\\\"LANGFLOW_LOG_REDACT_KEYS\\\", \\\"\\\").split(\\\",\\\") if k.strip()\\n    )\\n    redact_processor = _build_redact_processor(extra_redact)\\n\\n    processors: list[Any] = [\\n        structlog.contextvars.merge_contextvars,\\n        structlog.processors.add_log_level,\\n        add_logger_name,\\n        add_otel_trace_context,\\n        structlog.processors.TimeStamper(fmt=\\\"iso\\\", utc=True),\\n        _add_service_info,\\n    ]\\n\\n    # Add callsite information when LANGFLOW_DEV is set, and when logs are being exported over\\n    # OTLP. In the second case it is what makes a withheld record actionable: severity and scope\\n    # alone do not tell an operator which line produced the failure, and the body that used to\\n    # tell them is no longer leaving the process. Costs a frame walk per record, which is why it\\n    # stays off for a deployment that is not exporting logs anywhere.\\n    if DEV or _otlp_logs_configured():\\n        processors.append(_callsite_adder())\\n\\n    processors.extend(\\n        [\\n            redact_processor,\\n            # After redaction, before rendering: the APM must not see anything the console\\n            # would have scrubbed, and the renderers below replace `event` with a formatted\\n            # string, which would lose the structure.\\n            emit_to_otel_logs,\\n            add_serialized,\\n            buffer_writer,\\n        ]\\n    )\\n\\n    # Configure output based on environment.\\n    # For machine-parseable renderers, serialize exc_info as structured tracebacks\\n    # so Grafana/Loki see a complete stack trace (type, value, frames) instead of\\n    # dropping the exception or rendering its repr. ConsoleRenderer formats\\n    # exc_info itself, so we don't add a tracebacks processor on that path.\\n    #\\n    # `show_locals` is OFF by default in JSON output because frame locals can\\n    # leak secrets (API keys, env, request bodies). Opt in with\\n    # LANGFLOW_LOG_TRACE_LOCALS=true when you need it for local debugging.\\n    show_locals = os.getenv(\\\"LANGFLOW_LOG_TRACE_LOCALS\\\", \\\"false\\\").lower() == \\\"true\\\"\\n    json_traceback = structlog.processors.ExceptionRenderer(\\n        structlog.tracebacks.ExceptionDictTransformer(show_locals=show_locals, max_frames=50)\\n    )\\n\\n    # When JSON output is written to a file, render through a stdlib\\n    # ProcessorFormatter on the rotating handler instead of an inline\\n    # JSONRenderer. That routes foreign stdlib records (uvicorn, sqlalchemy,\\n    # httpx, asyncio) through the same renderer and the same redaction, so the\\n    # file is a single JSON stream and PII redaction is not bypassed -- while the\\n    # stdlib RotatingFileHandler keeps log rotation. Foreign records are enriched\\n    # by ``foreign_pre_chain``; structlog records carry the context built above\\n    # and are handed off via ``wrap_for_formatter``.\\n    file_json_formatter: logging.Formatter | None = None\\n\\n    def _append_json_tail() -> None:\\n        nonlocal file_json_formatter\\n        if log_file:\\n            processors.append(structlog.stdlib.ProcessorFormatter.wrap_for_formatter)\\n            foreign_pre_chain = [\\n                structlog.contextvars.merge_contextvars,\\n                structlog.stdlib.ExtraAdder(),\\n                # NB: not ``structlog.stdlib.add_log_level`` -- that trusts\\n                # ``record.levelname``, which a third-party ``addLevelName`` call\\n                # can corrupt. Derive from the numeric level instead.\\n                add_stdlib_log_level_from_record,\\n                structlog.stdlib.add_logger_name,\\n                add_otel_trace_context,\\n                structlog.processors.TimeStamper(fmt=\\\"iso\\\", utc=True),\\n                _add_service_info,\\n                redact_processor,\\n                # Foreign records reach OTLP through this chain, not the one above, so without\\n                # the adder here they would export with no callsite at all -- and the callsite\\n                # is what a withheld body leaves an operator to work with.\\n                *([_callsite_adder()] if DEV or _otlp_logs_configured() else []),\\n                emit_to_otel_logs,\\n            ]\\n            file_json_formatter = structlog.stdlib.ProcessorFormatter(\\n                foreign_pre_chain=foreign_pre_chain,\\n                processors=[\\n                    structlog.stdlib.ProcessorFormatter.remove_processors_meta,\\n                    json_traceback,\\n                    structlog.processors.JSONRenderer(),\\n                ],\\n            )\\n        else:\\n            processors.append(json_traceback)\\n            processors.append(structlog.processors.JSONRenderer())\\n\\n    if log_env.lower() in (\\\"container\\\", \\\"container_json\\\"):\\n        _append_json_tail()\\n    elif log_env.lower() == \\\"container_csv\\\":\\n        processors.append(structlog.processors.format_exc_info)\\n        # Include callsite fields in key order when DEV is enabled\\n        key_order = [\\\"timestamp\\\", \\\"level\\\", \\\"event\\\"]\\n        if DEV:\\n            key_order += [\\\"filename\\\", \\\"func_name\\\", \\\"lineno\\\"]\\n\\n        processors.append(structlog.processors.KeyValueRenderer(key_order=key_order, drop_missing=True))\\n    else:\\n        # Use rich console for pretty printing based on environment variable\\n        log_stdout_pretty = os.getenv(\\\"LANGFLOW_PRETTY_LOGS\\\", \\\"true\\\").lower() == \\\"true\\\"\\n        if log_stdout_pretty:\\n            # If custom format is provided, use KeyValueRenderer with custom format\\n            if log_format:\\n                processors.append(structlog.processors.format_exc_info)\\n                processors.append(structlog.processors.KeyValueRenderer())\\n            else:\\n                processors.append(structlog.dev.ConsoleRenderer(colors=True))\\n        else:\\n            _append_json_tail()\\n\\n    # Create the filtering wrapper. ``numeric_level`` was resolved above for the\\n    # fingerprint. Attach min_level (kept for back-compat) and the full config\\n    # fingerprint so the next configure() call early-returns only when every\\n    # effective input is unchanged.\\n    wrapper_class = structlog.make_filtering_bound_logger(numeric_level)\\n    wrapper_class.min_level = numeric_level\\n    wrapper_class.config_fingerprint = config_fingerprint\\n\\n    # Configure structlog\\n    # Default to stdout for backward compatibility, unless output_file is specified\\n    log_output_file = output_file if output_file is not None else sys.stdout\\n\\n    # Wipe cached loggers before reconfiguring so any module that captured a\\n    # logger before the real configure() call picks up the new processor chain\\n    # (otherwise cache_logger_on_first_use=True binds the bootstrap chain\\n    # permanently to that reference).\\n    structlog.reset_defaults()\\n\\n    structlog.configure(\\n        processors=processors,\\n        wrapper_class=wrapper_class,\\n        context_class=dict,\\n        logger_factory=_NamedPrintLoggerFactory(file=log_output_file)\\n        if not log_file\\n        else structlog.stdlib.LoggerFactory(),\\n        cache_logger_on_first_use=cache if cache is not None else True,\\n    )\\n\\n    # Set up file logging if needed\\n    if log_file:\\n        if not log_file.parent.exists():\\n            cache_dir = Path(user_cache_dir(\\\"langflow\\\"))\\n            log_file = cache_dir / \\\"langflow.log\\\"\\n\\n        # Parse rotation settings\\n        if log_rotation:\\n            # Handle rotation like \\\"1 day\\\", \\\"100 MB\\\", etc.\\n            max_bytes = 10 * 1024 * 1024  # Default 10MB\\n            if \\\"MB\\\" in log_rotation.upper():\\n                try:\\n                    # Look for pattern like \\\"100 MB\\\" (with space)\\n                    parts = log_rotation.split()\\n                    expected_parts = 2\\n                    if len(parts) >= expected_parts and parts[1].upper() == \\\"MB\\\":\\n                        mb = int(parts[0])\\n                        if mb > 0:  # Only use valid positive values\\n                            max_bytes = mb * 1024 * 1024\\n                except (ValueError, IndexError):\\n                    pass\\n        else:\\n            max_bytes = 10 * 1024 * 1024  # Default 10MB\\n\\n        # Since structlog doesn't have built-in rotation, we'll use stdlib logging for file output.\\n        # In JSON file mode the formatter renders both structlog and foreign stdlib records as JSON.\\n        setup_log_file(log_file, max_bytes=max_bytes, formatter=file_json_formatter)\\n        logging.root.setLevel(numeric_level)\\n\\n    # Set up interceptors for uvicorn and gunicorn\\n    setup_uvicorn_logger()\\n    setup_gunicorn_logger()\\n\\n    # In JSON modes we want a single unified stdout stream: every stdlib log\\n    # record (uvicorn access logs, sqlalchemy, httpx, langchain, asyncio)\\n    # routed into structlog so it comes out as JSON instead of unstructured\\n    # text. In non-JSON modes leave stdlib alone so dev console output stays\\n    # readable.\\n    json_mode = log_env.lower() in (\\\"container\\\", \\\"container_json\\\") or (\\n        not log_env and os.getenv(\\\"LANGFLOW_PRETTY_LOGS\\\", \\\"true\\\").lower() != \\\"true\\\"\\n    )\\n    if json_mode and not log_file:\\n        _install_stdlib_intercept(numeric_level)\\n    elif log_file:\\n        # From here structlog resolves back into the stdlib tree, so a root\\n        # intercept left over from an earlier stdout-mode configure() would feed\\n        # every record back into the logger it just came from. The guard in\\n        # ``InterceptHandler.emit`` keeps that from looping, but the record would\\n        # still be written twice -- once by the intercept's structlog call and\\n        # once by the original record reaching the file handler.\\n        _remove_stdlib_intercept()\\n\\n    # Apply per-logger level overrides last so user env beats library defaults.\\n    _apply_logger_level_overrides()\\n\\n    # Create the global logger instance\\n    global logger  # noqa: PLW0603\\n    logger = structlog.get_logger()\\n    setup_loguru_logger(log_level)\\n\\n    if disable:\\n        # In structlog, we can set a very high filter level to effectively disable logging\\n        structlog.configure(\\n            wrapper_class=structlog.make_filtering_bound_logger(logging.CRITICAL),\\n        )\\n\\n    logger.debug(\\\"Logger set up with log level: %s\\\", log_level)\\n\\n\\ndef setup_uvicorn_logger() -> None:\\n    \\\"\\\"\\\"Redirect uvicorn logs through structlog.\\\"\\\"\\\"\\n    loggers = (logging.getLogger(name) for name in logging.root.manager.loggerDict if name.startswith(\\\"uvicorn.\\\"))\\n    for uvicorn_logger in loggers:\\n        uvicorn_logger.handlers = []\\n        uvicorn_logger.propagate = True\\n\\n\\ndef setup_gunicorn_logger() -> None:\\n    \\\"\\\"\\\"Redirect gunicorn logs through structlog.\\\"\\\"\\\"\\n    logging.getLogger(\\\"gunicorn.error\\\").handlers = []\\n    logging.getLogger(\\\"gunicorn.error\\\").propagate = True\\n    logging.getLogger(\\\"gunicorn.access\\\").handlers = []\\n    logging.getLogger(\\\"gunicorn.access\\\").propagate = True\\n\\n\\n_STDLIB_LEVEL_TO_STRUCTLOG = (\\n    (logging.CRITICAL, \\\"critical\\\"),\\n    (logging.ERROR, \\\"error\\\"),\\n    (logging.WARNING, \\\"warning\\\"),\\n    (logging.INFO, \\\"info\\\"),\\n)\\n\\n\\ndef _levelno_to_structlog_name(levelno: int) -> str:\\n    \\\"\\\"\\\"Map a stdlib numeric level to a lowercase structlog level name.\\n\\n    Derives the name from the immutable ``levelno`` instead of ``levelname``\\n    because third-party libraries can rewrite stdlib level names via\\n    ``logging.addLevelName`` (e.g. ``ibm_watsonx_orchestrate`` wraps them in ANSI\\n    color codes). ``levelno`` is never mutated, so the rendered ``level`` field\\n    stays clean and filterable.\\n    \\\"\\\"\\\"\\n    for threshold, name in _STDLIB_LEVEL_TO_STRUCTLOG:\\n        if levelno >= threshold:\\n            return name\\n    return \\\"debug\\\"\\n\\n\\ndef add_stdlib_log_level_from_record(_logger: Any, method_name: str, event_dict: dict[str, Any]) -> dict[str, Any]:\\n    \\\"\\\"\\\"Set ``level`` from a foreign ``LogRecord``'s numeric level.\\n\\n    Drop-in replacement for ``structlog.stdlib.add_log_level`` on the\\n    ProcessorFormatter ``foreign_pre_chain``. structlog derives a foreign\\n    record's level from ``record.levelname.lower()``; when a third-party library\\n    has rewritten that name via ``logging.addLevelName`` (e.g. wrapping it in\\n    ANSI color codes), the mangled string would otherwise land verbatim in the\\n    JSON ``level`` field and break level-based filtering in Grafana/Loki.\\n    Deriving from the immutable ``levelno`` keeps the field stable. Mirrors the\\n    numeric-level logic the stdout-mode ``InterceptHandler`` already uses.\\n    \\\"\\\"\\\"\\n    record = event_dict.get(\\\"_record\\\")\\n    levelno = getattr(record, \\\"levelno\\\", None)\\n    if levelno is None:\\n        # No stdlib record on the chain (not expected on the foreign path):\\n        # fall back to the method name structlog computed.\\n        event_dict.setdefault(\\\"level\\\", method_name)\\n    else:\\n        event_dict[\\\"level\\\"] = _levelno_to_structlog_name(levelno)\\n    return event_dict\\n\\n\\n# Attributes present on a vanilla LogRecord. Anything else in record.__dict__ was\\n# attached via ``logging.*(..., extra={...})`` and is forwarded to structlog so it\\n# lands as a structured field (and is therefore subject to PII redaction), mirroring\\n# the ExtraAdder used on the file-mode ProcessorFormatter path.\\n_RESERVED_LOGRECORD_ATTRS = frozenset(logging.makeLogRecord({}).__dict__) | {\\\"message\\\", \\\"asctime\\\"}\\n\\n\\n# Set while a thread is inside ``InterceptHandler.emit``. Guards against the\\n# handler being re-entered by the very structlog call it just made -- see\\n# ``InterceptHandler.emit``. Thread-local because the cycle is synchronous and\\n# within one thread; a global flag would make concurrent threads drop each\\n# other's records.\\n_emit_state = local()\\n\\n\\nclass InterceptHandler(logging.Handler):\\n    \\\"\\\"\\\"Route stdlib logging records into structlog.\\n\\n    Forwards ``exc_info`` and ``stack_info`` so library tracebacks (httpx,\\n    sqlalchemy, langchain, uvicorn) survive into the JSON output. Without\\n    this, errors raised inside third-party libraries log a one-line message\\n    with no stack trace.\\n    \\\"\\\"\\\"\\n\\n    def emit(self, record: logging.LogRecord) -> None:\\n        # Re-entrancy guard. When structlog is backed by the stdlib factory\\n        # (see ``structlog_routes_to_stdlib``), the structlog call below resolves\\n        # to the same stdlib logger this handler is attached to, so the record\\n        # comes straight back here -- carrying the previous lap's rendered payload\\n        # as its message. Left alone that cycles until the process dies. Dropping\\n        # the re-entrant record is the only safe answer: a logging handler must\\n        # never take down the process it instruments, and the record is already\\n        # being handled by the lap that caused the re-entry.\\n        if getattr(_emit_state, \\\"active\\\", False):\\n            return\\n        _emit_state.active = True\\n        # Mirrors the stdlib Handler.emit safety net: a malformed third-party\\n        # log call (e.g. mismatched %-format args) must not propagate up and\\n        # crash the request path. Anything that raises here is routed to\\n        # handleError, which is the documented contract callers expect.\\n        try:\\n            structlog_logger = structlog.get_logger(record.name)\\n            kwargs: dict[str, Any] = {}\\n            if record.exc_info:\\n                kwargs[\\\"exc_info\\\"] = record.exc_info\\n            if record.stack_info:\\n                # stdlib already formats stack_info as a string. Pass it as\\n                # the rendered ``stack`` field directly so it survives without\\n                # needing StackInfoRenderer to recompute from a different frame.\\n                kwargs[\\\"stack\\\"] = record.stack_info\\n            for key, value in record.__dict__.items():\\n                if key not in _RESERVED_LOGRECORD_ATTRS and not key.startswith(\\\"_\\\") and key not in kwargs:\\n                    kwargs[key] = value\\n            method_name = _levelno_to_structlog_name(record.levelno)\\n            getattr(structlog_logger, method_name)(record.getMessage(), **kwargs)\\n        except Exception:  # noqa: BLE001 - logging must never break the caller\\n            self.handleError(record)\\n        finally:\\n            # Released even when handleError ran, otherwise one malformed record\\n            # would wedge the guard on and silence the thread's logging for good.\\n            _emit_state.active = False\\n\\n\\ndef _install_stdlib_intercept(numeric_level: int) -> None:\\n    \\\"\\\"\\\"Install (or refresh) the InterceptHandler on the stdlib root logger.\\n\\n    Routes every stdlib log record (uvicorn, sqlalchemy, httpx, langchain,\\n    asyncio, ...) into structlog so the entire process emits a single JSON\\n    stream. Re-runnable: a second call updates the level rather than stacking\\n    handlers.\\n    \\\"\\\"\\\"\\n    root = logging.root\\n    handler = next((h for h in root.handlers if isinstance(h, InterceptHandler)), None)\\n    if handler is None:\\n        handler = InterceptHandler()\\n        root.addHandler(handler)\\n    handler.setLevel(numeric_level)\\n    root.setLevel(numeric_level)\\n\\n\\ndef _remove_stdlib_intercept() -> None:\\n    \\\"\\\"\\\"Drop any ``InterceptHandler`` from the stdlib root logger.\\n\\n    The counterpart to ``_install_stdlib_intercept``, for the switch into log-file\\n    mode. Leaving one installed once structlog routes back through stdlib is the\\n    root-logger form of the cycle ``structlog_routes_to_stdlib`` exists to warn\\n    about.\\n    \\\"\\\"\\\"\\n    root = logging.root\\n    for handler in [h for h in root.handlers if isinstance(h, InterceptHandler)]:\\n        root.removeHandler(handler)\\n\\n\\n# Initialize logger - will be reconfigured when configure() is called\\n# Set it to critical level\\nlogger: structlog.BoundLogger = structlog.get_logger()\\nconfigure(log_level=\\\"CRITICAL\\\", cache=False)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/logging/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"5f9b571797b585ceb669da6b44f2ed29e6aa9bcfada65ea5a17b316e1f483be4\",\"content\":\"\\\"\\\"\\\"Backwards compatibility module for lfx.logging.\\n\\nThis module provides backwards compatibility for code that imports from lfx.logging.\\nAll functionality has been moved to lfx.log.\\n\\\"\\\"\\\"\\n\\n# Re-export everything from lfx.log for backwards compatibility\\nfrom lfx.log.logger import configure, logger\\n\\n# Maintain the same __all__ exports\\n__all__ = [\\\"configure\\\", \\\"logger\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/logging/logger.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"cbba29872597e7eafc442c4725e02618ac86784851fbb8a647e0fc6015d4ec21\",\"content\":\"\\\"\\\"\\\"Backwards compatibility module for lfx.logging.logger.\\n\\nThis module provides backwards compatibility for code that imports from lfx.logging.logger.\\nAll functionality has been moved to lfx.log.logger.\\n\\\"\\\"\\\"\\n\\n# Ensure we maintain all the original exports\\nfrom lfx.log.logger import (\\n    InterceptHandler,\\n    LogConfig,\\n    configure,\\n    logger,\\n    setup_gunicorn_logger,\\n    setup_uvicorn_logger,\\n)\\n\\n__all__ = [\\n    \\\"InterceptHandler\\\",\\n    \\\"LogConfig\\\",\\n    \\\"configure\\\",\\n    \\\"logger\\\",\\n    \\\"setup_gunicorn_logger\\\",\\n    \\\"setup_uvicorn_logger\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/mcp/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"12f2cde03c98d5fdbaa53467da10e74a2fa58fb6e4adc0fdf36bb5056ce1ec78\",\"content\":\"\\\"\\\"\\\"Langflow MCP Client \u2014 REST API-based MCP server for operating Langflow.\\n\\nStandalone MCP server that connects to a running Langflow instance via REST API.\\nRequires no internal Langflow services \u2014 just a URL and credentials.\\n\\nUsage:\\n    python -m lfx.mcp\\n    # or via console script:\\n    lfx-mcp\\n\\\"\\\"\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/mcp/__main__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f197702da0deb8a864619d3c401755dd235a5de2221ac3883bf71222538c23b2\",\"content\":\"\\\"\\\"\\\"Entry point for the Langflow MCP server.\\n\\nUsage:\\n    python -m lfx.mcp\\n    # or via console script:\\n    lfx-mcp\\n\\nEnvironment variables:\\n    LANGFLOW_SERVER_URL: Langflow server URL (default: http://localhost:7860)\\n    LANGFLOW_API_KEY: API key for authentication (skips login)\\n\\\"\\\"\\\"\\n\\nfrom lfx.mcp.server import mcp\\n\\n\\ndef main():\\n    mcp.run()\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    main()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/mcp/client.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"2d1b71c736d0be17ed07f48478e6b6b6d5814841faafdc307490cce9cb596685\",\"content\":\"\\\"\\\"\\\"Async HTTP client for Langflow REST API.\\n\\nAdapted from the CLI's sync Backend class, using httpx.AsyncClient\\nfor non-blocking operations inside the MCP server.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport asyncio\\nimport json\\nimport os\\nfrom typing import TYPE_CHECKING, Any\\n\\nimport httpx\\nfrom starlette.status import HTTP_204_NO_CONTENT\\n\\nfrom lfx.log.logger import logger\\n\\nif TYPE_CHECKING:\\n    from collections.abc import AsyncIterator\\n\\n\\nclass LangflowClient:\\n    \\\"\\\"\\\"Async HTTP client for Langflow's REST API.\\n\\n    Auth sends both headers on every request:\\n    - Authorization: Bearer <access_token or api_key>\\n    - x-api-key: <api_key> (when available)\\n\\n    Uses a persistent httpx.AsyncClient for connection pooling.\\n    \\\"\\\"\\\"\\n\\n    def __init__(\\n        self,\\n        server_url: str | None = None,\\n        api_key: str | None = None,\\n        access_token: str | None = None,\\n    ):\\n        self.server_url = (server_url or os.environ.get(\\\"LANGFLOW_SERVER_URL\\\", \\\"http://localhost:7860\\\")).rstrip(\\\"/\\\")\\n        self.api_key = api_key or os.environ.get(\\\"LANGFLOW_API_KEY\\\")\\n        self.access_token = access_token\\n        self._http: httpx.AsyncClient | None = None\\n        self._lock = asyncio.Lock()\\n\\n    async def _client(self) -> httpx.AsyncClient:\\n        async with self._lock:\\n            if self._http is None or self._http.is_closed:\\n                self._http = httpx.AsyncClient(follow_redirects=True)\\n            return self._http\\n\\n    async def close(self) -> None:\\n        \\\"\\\"\\\"Close the underlying HTTP client.\\\"\\\"\\\"\\n        if self._http is not None and not self._http.is_closed:\\n            await self._http.aclose()\\n            self._http = None\\n\\n    def _headers(self) -> dict[str, str]:\\n        headers = {\\\"Content-Type\\\": \\\"application/json\\\"}\\n        if self.access_token:\\n            headers[\\\"Authorization\\\"] = f\\\"Bearer {self.access_token}\\\"\\n        if self.api_key:\\n            headers[\\\"x-api-key\\\"] = self.api_key\\n        return headers\\n\\n    def _url(self, path: str) -> str:\\n        return f\\\"{self.server_url}/api/v1{path}\\\"\\n\\n    async def get(self, path: str, **kwargs: Any) -> Any:\\n        url = self._url(path)\\n        try:\\n            client = await self._client()\\n            resp = await client.get(url, headers=self._headers(), timeout=30.0, **kwargs)\\n            resp.raise_for_status()\\n            return resp.json()\\n        except httpx.HTTPStatusError as exc:\\n            msg = f\\\"GET {path} failed ({exc.response.status_code})\\\"\\n            raise RuntimeError(msg) from exc\\n        except (httpx.ConnectError, httpx.TimeoutException) as exc:\\n            msg = f\\\"GET {path} failed: {exc}\\\"\\n            raise RuntimeError(msg) from exc\\n\\n    async def post(self, path: str, json_data: Any = None, timeout: float = 30.0, **kwargs: Any) -> Any:\\n        url = self._url(path)\\n        try:\\n            client = await self._client()\\n            resp = await client.post(url, headers=self._headers(), json=json_data, timeout=timeout, **kwargs)\\n            resp.raise_for_status()\\n            return resp.json()\\n        except httpx.HTTPStatusError as exc:\\n            msg = f\\\"POST {path} failed ({exc.response.status_code})\\\"\\n            raise RuntimeError(msg) from exc\\n        except (httpx.ConnectError, httpx.TimeoutException) as exc:\\n            msg = f\\\"POST {path} failed: {exc}\\\"\\n            raise RuntimeError(msg) from exc\\n\\n    async def stream_post(\\n        self, path: str, json_data: Any = None, timeout: float = 300.0\\n    ) -> AsyncIterator[dict[str, Any]]:\\n        \\\"\\\"\\\"POST with streaming SSE response. Yields parsed event dicts.\\\"\\\"\\\"\\n        url = self._url(path)\\n        client = await self._client()\\n        async with client.stream(\\\"POST\\\", url, headers=self._headers(), json=json_data, timeout=timeout) as resp:\\n            resp.raise_for_status()\\n            async for raw_line in resp.aiter_lines():\\n                line = raw_line.strip()\\n                if not line:\\n                    continue\\n                # Some endpoints frame lines as SSE (``data: {...}``) rather than\\n                # bare NDJSON; strip the prefix so both wire shapes parse.\\n                line = line.removeprefix(\\\"data:\\\").strip()\\n                if not line:\\n                    continue\\n                try:\\n                    yield json.loads(line)\\n                except json.JSONDecodeError:\\n                    logger.debug(\\\"stream_post: skipping non-JSON SSE line: %s\\\", line[:200])\\n                    continue\\n\\n    async def patch(self, path: str, json_data: Any = None, **kwargs: Any) -> Any:\\n        url = self._url(path)\\n        try:\\n            client = await self._client()\\n            resp = await client.patch(url, headers=self._headers(), json=json_data, timeout=30.0, **kwargs)\\n            resp.raise_for_status()\\n            return resp.json()\\n        except httpx.HTTPStatusError as exc:\\n            msg = f\\\"PATCH {path} failed ({exc.response.status_code})\\\"\\n            raise RuntimeError(msg) from exc\\n        except (httpx.ConnectError, httpx.TimeoutException) as exc:\\n            msg = f\\\"PATCH {path} failed: {exc}\\\"\\n            raise RuntimeError(msg) from exc\\n\\n    async def delete(self, path: str, **kwargs: Any) -> Any:\\n        url = self._url(path)\\n        try:\\n            client = await self._client()\\n            resp = await client.delete(url, headers=self._headers(), timeout=30.0, **kwargs)\\n            resp.raise_for_status()\\n            if resp.status_code == HTTP_204_NO_CONTENT or not resp.content:\\n                return {}\\n            return resp.json()\\n        except httpx.HTTPStatusError as exc:\\n            msg = f\\\"DELETE {path} failed ({exc.response.status_code})\\\"\\n            raise RuntimeError(msg) from exc\\n        except (httpx.ConnectError, httpx.TimeoutException) as exc:\\n            msg = f\\\"DELETE {path} failed: {exc}\\\"\\n            raise RuntimeError(msg) from exc\\n\\n    async def login(self, username: str, password: str) -> str:\\n        \\\"\\\"\\\"Authenticate and create an API key.\\n\\n        Each call creates a new API key on the server.\\n        Returns the API key string.\\n        \\\"\\\"\\\"\\n        try:\\n            client = await self._client()\\n            # Login to get JWT\\n            resp = await client.post(\\n                self._url(\\\"/login\\\"),\\n                data={\\\"username\\\": username, \\\"password\\\": password},\\n                headers={\\\"Content-Type\\\": \\\"application/x-www-form-urlencoded\\\"},\\n                timeout=30.0,\\n            )\\n            resp.raise_for_status()\\n            token_data = resp.json()\\n            if \\\"access_token\\\" not in token_data:\\n                msg = f\\\"Login response missing 'access_token': {list(token_data.keys())}\\\"\\n                raise RuntimeError(msg)\\n            self.access_token = token_data[\\\"access_token\\\"]\\n\\n            # Create API key\\n            resp = await client.post(\\n                self._url(\\\"/api_key/\\\"),\\n                headers=self._headers(),\\n                json={\\\"name\\\": \\\"mcp-client\\\"},\\n                timeout=30.0,\\n            )\\n            resp.raise_for_status()\\n            key_data = resp.json()\\n            if \\\"api_key\\\" not in key_data:\\n                msg = f\\\"API key response missing 'api_key': {list(key_data.keys())}\\\"\\n                raise RuntimeError(msg)\\n            self.api_key = key_data[\\\"api_key\\\"]\\n        except httpx.HTTPStatusError as exc:\\n            msg = f\\\"Login failed ({exc.response.status_code})\\\"\\n            raise RuntimeError(msg) from exc\\n        except (httpx.ConnectError, httpx.TimeoutException) as exc:\\n            msg = f\\\"Login failed: {exc}\\\"\\n            raise RuntimeError(msg) from exc\\n        return self.api_key\\n\\n    async def post_event(self, flow_id: str, event_type: str, summary: str = \\\"\\\") -> None:\\n        \\\"\\\"\\\"Post an event to the flow events queue. Best-effort -- does not raise on failure.\\\"\\\"\\\"\\n        try:\\n            await self.post(f\\\"/flows/{flow_id}/events\\\", json_data={\\\"type\\\": event_type, \\\"summary\\\": summary})\\n        except Exception:  # noqa: BLE001\\n            logger.warning(\\\"Failed to post flow event (flow_id=%s, type=%s)\\\", flow_id, event_type, exc_info=True)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/mcp/redact.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"177f35be9d4c67aa776c8043bb33feec4e4c7112deb5d9b449fc74dbd6c42702\",\"content\":\"\\\"\\\"\\\"Sensitive field redaction for component templates.\\n\\nProvides `is_sensitive_field` for checking field names, and\\n`redact_template`/`redact_node` utilities for bulk redaction.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport re\\n\\n_SENSITIVE_PATTERN = re.compile(\\n    r\\\"(?:^|[_\\\\-])(?:api[_\\\\-]?key|password|secret|access[_\\\\-]?key|private[_\\\\-]?key|api[_\\\\-]?token|access[_\\\\-]?token)(?:[_\\\\-]|$)\\\",\\n    re.IGNORECASE,\\n)\\n\\n\\ndef is_sensitive_field(field_name: str) -> bool:\\n    \\\"\\\"\\\"Check if a field name looks like it holds sensitive data.\\n\\n    Uses word-boundary matching so 'api_key' matches but 'token_count' does not.\\n    \\\"\\\"\\\"\\n    return _SENSITIVE_PATTERN.search(field_name) is not None\\n\\n\\ndef redact_template(template: dict) -> dict:\\n    \\\"\\\"\\\"Return a copy of the template with sensitive field values masked.\\\"\\\"\\\"\\n    redacted = {}\\n    for key, value in template.items():\\n        if isinstance(value, dict):\\n            if is_sensitive_field(key) and \\\"value\\\" in value and value[\\\"value\\\"]:\\n                redacted[key] = {**value, \\\"value\\\": \\\"***REDACTED***\\\"}\\n            else:\\n                redacted[key] = {**value}\\n        else:\\n            redacted[key] = value\\n    return redacted\\n\\n\\ndef redact_node(node_data: dict) -> dict:\\n    \\\"\\\"\\\"Redact sensitive fields in a node's template.\\\"\\\"\\\"\\n    result = {**node_data}\\n    if \\\"node\\\" in result and \\\"template\\\" in result[\\\"node\\\"]:\\n        result = {**result, \\\"node\\\": {**result[\\\"node\\\"]}}\\n        result[\\\"node\\\"][\\\"template\\\"] = redact_template(result[\\\"node\\\"][\\\"template\\\"])\\n    return result\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/mcp/registry.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"0ec121ef48c324b595d305b083fe634d59f2111d685aed93088e9a5d33af2f03\",\"content\":\"\\\"\\\"\\\"Component registry cache \u2014 fetches and searches component types.\\n\\nLoads the full component catalog from /api/v1/all and provides\\npure search/describe functions.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING, Any\\n\\nfrom lfx.mcp.redact import is_sensitive_field\\n\\nif TYPE_CHECKING:\\n    from lfx.mcp.client import LangflowClient\\n\\n\\nasync def load_registry(client: LangflowClient) -> dict[str, dict]:\\n    \\\"\\\"\\\"Fetch all component templates from the server.\\n\\n    Returns a flat dict: {component_type: template_dict}.\\n    Raises RuntimeError if the server returns no components.\\n    \\\"\\\"\\\"\\n    data = await client.get(\\\"/all\\\")\\n    registry: dict[str, dict] = {\\n        name: {**comp_data, \\\"category\\\": category}\\n        for category, items in data.items()\\n        if isinstance(items, dict)\\n        for name, comp_data in items.items()\\n        if isinstance(comp_data, dict) and \\\"template\\\" in comp_data\\n    }\\n    if not registry:\\n        msg = \\\"Server returned no components \u2014 check the server URL and authentication\\\"\\n        raise RuntimeError(msg)\\n    return registry\\n\\n\\ndef search_registry(\\n    registry: dict[str, dict],\\n    query: str | None = None,\\n    category: str | None = None,\\n    output_type: str | None = None,\\n    *,\\n    include_legacy: bool = False,\\n) -> list[dict[str, Any]]:\\n    \\\"\\\"\\\"Search the registry by name/category/output_type. Pure function.\\n\\n    LEGACY components are excluded by default: the agent's discovery path\\n    must not surface deprecated nodes (screenshot 5: a Legacy Calculator).\\n    They stay reachable via ``describe_component`` by exact name, and an\\n    explicit ``include_legacy=True`` opt-in still lists them.\\n\\n    BETA components ARE included (user decision 2026-05-18): they are\\n    usable, just newer \u2014 only legacy is hidden.\\n    \\\"\\\"\\\"\\n    results = []\\n    for name, tmpl in sorted(registry.items()):\\n        if not include_legacy and tmpl.get(\\\"legacy\\\"):\\n            continue\\n        cat = tmpl.get(\\\"category\\\", \\\"\\\")\\n        if category and cat.lower() != category.lower():\\n            continue\\n        if query:\\n            query_lower = query.lower()\\n            display_name = tmpl.get(\\\"display_name\\\", \\\"\\\")\\n            description = tmpl.get(\\\"description\\\", \\\"\\\")\\n            if (\\n                query_lower not in name.lower()\\n                and query_lower not in cat.lower()\\n                and query_lower not in display_name.lower()\\n                and query_lower not in description.lower()\\n            ):\\n                continue\\n        if output_type:\\n            all_types = [t for o in tmpl.get(\\\"outputs\\\", []) for t in o.get(\\\"types\\\", [])]\\n            if output_type not in all_types:\\n                continue\\n        results.append(\\n            {\\n                \\\"type\\\": name,\\n                \\\"category\\\": cat,\\n                \\\"display_name\\\": tmpl.get(\\\"display_name\\\", name),\\n                \\\"description\\\": tmpl.get(\\\"description\\\", \\\"\\\"),\\n            }\\n        )\\n    return results\\n\\n\\ndef _field_description(field_name: str, field_data: dict[str, Any]) -> dict[str, Any]:\\n    \\\"\\\"\\\"Return the safe, useful configuration metadata for one field.\\\"\\\"\\\"\\n    field_info: dict[str, Any] = {\\n        \\\"name\\\": field_name,\\n        \\\"type\\\": field_data.get(\\\"type\\\", \\\"\\\"),\\n    }\\n    if field_data.get(\\\"required\\\"):\\n        field_info[\\\"required\\\"] = True\\n\\n    options = field_data.get(\\\"options\\\")\\n    if isinstance(options, list) and options:\\n        field_info[\\\"options\\\"] = options\\n    if field_data.get(\\\"conditional_options\\\"):\\n        field_info[\\\"conditional_options\\\"] = field_data[\\\"conditional_options\\\"]\\n    for flag in (\\\"combobox\\\", \\\"list\\\"):\\n        if field_data.get(flag):\\n            field_info[flag] = True\\n\\n    # Defaults help the Assistant omit optional fields safely, but never expose\\n    # a credential through discovery metadata. A load_from_db value is a global\\n    # variable *name*, not a default: advertising it invites the Assistant to\\n    # send it back as a literal, which would sever the variable binding.\\n    is_secret = (\\n        is_sensitive_field(field_name)\\n        or field_data.get(\\\"password\\\") is True\\n        or \\\"secret\\\" in str(field_data.get(\\\"type\\\", \\\"\\\")).lower()\\n    )\\n    if \\\"value\\\" in field_data and not is_secret and not field_data.get(\\\"load_from_db\\\"):\\n        field_info[\\\"default\\\"] = field_data[\\\"value\\\"]\\n\\n    range_spec = field_data.get(\\\"range_spec\\\")\\n    if isinstance(range_spec, dict):\\n        field_info[\\\"range_spec\\\"] = {\\n            key: range_spec[key] for key in (\\\"min\\\", \\\"max\\\", \\\"step\\\", \\\"step_type\\\") if key in range_spec\\n        }\\n\\n    return field_info\\n\\n\\ndef describe_component(registry: dict[str, dict], component_type: str) -> dict[str, Any]:\\n    \\\"\\\"\\\"Describe a component type's inputs, outputs, and fields. Pure function.\\\"\\\"\\\"\\n    if component_type not in registry:\\n        available = \\\", \\\".join(sorted(registry.keys())[:20])\\n        msg = f\\\"Unknown component: {component_type}. Available: {available}...\\\"\\n        raise ValueError(msg)\\n\\n    tmpl = registry[component_type]\\n    outputs = []\\n    loop_inputs = []\\n    for o in tmpl.get(\\\"outputs\\\", []):\\n        entry: dict[str, Any] = {\\\"name\\\": o[\\\"name\\\"], \\\"types\\\": o.get(\\\"types\\\", [])}\\n        if o.get(\\\"allows_loop\\\"):\\n            # An allows_loop output doubles as the loop-feedback target (Loop.item):\\n            # surface it as an input too, or the agent cannot discover loop wiring.\\n            entry[\\\"allows_loop\\\"] = True\\n            types = o.get(\\\"types\\\") or []\\n            selected = o.get(\\\"selected\\\") or (types[0] if types else \\\"Message\\\")\\n            loop_inputs.append(\\n                {\\n                    \\\"name\\\": o[\\\"name\\\"],\\n                    \\\"input_types\\\": [selected, *(o.get(\\\"loop_types\\\") or [])],\\n                    \\\"type\\\": \\\"loop\\\",\\n                    \\\"required\\\": False,\\n                    \\\"description\\\": \\\"Loop feedback input: connect the loop body's final output back here.\\\",\\n                }\\n            )\\n        outputs.append(entry)\\n\\n    # Tool mode = any INPUT field with tool_mode=True, or the class opting in via\\n    # add_tool_output \u2014 both halves of Component._handle_tool_mode, the runtime\\n    # authority. Output-side tool_mode marks which outputs a toolset exposes, not\\n    # whether the component has one (89 of the 127 bundled components set it,\\n    # ChatInput included), so advertising on it promised a toolset that the\\n    # runtime never creates.\\n    template_fields = tmpl.get(\\\"template\\\", {})\\n    tool_mode_inputs = [\\n        name for name, fdata in template_fields.items() if isinstance(fdata, dict) and fdata.get(\\\"tool_mode\\\")\\n    ]\\n    if tool_mode_inputs or tmpl.get(\\\"add_tool_output\\\"):\\n        description = \\\"Wraps this component as a Tool\\\"\\n        if tool_mode_inputs:\\n            description += f\\\" (tool inputs: {', '.join(tool_mode_inputs)})\\\"\\n        description += \\\". Connect to an Agent's 'tools' input.\\\"\\n        outputs.append(\\n            {\\n                \\\"name\\\": \\\"component_as_tool\\\",\\n                \\\"types\\\": [\\\"Tool\\\"],\\n                \\\"description\\\": description,\\n            }\\n        )\\n    fields = []\\n    advanced_fields: list[str] = []\\n    constrained_advanced_fields = []\\n    inputs = []\\n    for fname, fdata in tmpl.get(\\\"template\\\", {}).items():\\n        if not isinstance(fdata, dict):\\n            continue\\n        is_advanced = fdata.get(\\\"advanced\\\", False)\\n        if fdata.get(\\\"input_types\\\"):\\n            if is_advanced:\\n                advanced_fields.append(fname)\\n            else:\\n                inputs.append(\\n                    {\\n                        \\\"name\\\": fname,\\n                        \\\"input_types\\\": fdata[\\\"input_types\\\"],\\n                        \\\"type\\\": fdata.get(\\\"type\\\", \\\"\\\"),\\n                        \\\"required\\\": fdata.get(\\\"required\\\", False),\\n                    }\\n                )\\n        elif fdata.get(\\\"show\\\", True) and fdata.get(\\\"type\\\") and fname != \\\"code\\\":\\n            if is_advanced:\\n                advanced_fields.append(fname)\\n                # configure_component enforces options/range_spec on advanced\\n                # fields too, so the Assistant must be able to discover them.\\n                # Kept out of `fields`, which lists non-advanced fields only.\\n                if fdata.get(\\\"options\\\") or fdata.get(\\\"conditional_options\\\") or fdata.get(\\\"range_spec\\\"):\\n                    constrained_advanced_fields.append(_field_description(fname, fdata))\\n            else:\\n                fields.append(_field_description(fname, fdata))\\n\\n    # Template wins on a name collision (mirrors connect.py's priority):\\n    # never describe the same port twice.\\n    template_input_names = {name for name, fdata in template_fields.items() if isinstance(fdata, dict) and fdata}\\n    loop_inputs = [li for li in loop_inputs if li[\\\"name\\\"] not in template_input_names]\\n\\n    result: dict[str, Any] = {\\n        \\\"type\\\": component_type,\\n        \\\"category\\\": tmpl.get(\\\"category\\\", \\\"\\\"),\\n        \\\"display_name\\\": tmpl.get(\\\"display_name\\\", component_type),\\n        \\\"description\\\": tmpl.get(\\\"description\\\", \\\"\\\"),\\n        \\\"outputs\\\": outputs,\\n        \\\"inputs\\\": [*inputs, *loop_inputs],\\n    }\\n    if fields:\\n        result[\\\"fields\\\"] = fields\\n    if advanced_fields:\\n        result[\\\"advanced_fields\\\"] = sorted(advanced_fields)\\n    if constrained_advanced_fields:\\n        result[\\\"constrained_advanced_fields\\\"] = constrained_advanced_fields\\n    # search_registry hides legacy/beta, but describe-by-exact-name still\\n    # reaches them \u2014 flag so the agent knows what it picked.\\n    if tmpl.get(\\\"legacy\\\"):\\n        result[\\\"legacy\\\"] = True\\n    if tmpl.get(\\\"beta\\\"):\\n        result[\\\"beta\\\"] = True\\n    return result\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/mcp/server.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"9c810068413713e8614063b77e502c89cb2c1c70a0d4ce0ecbdf7f3904523bdc\",\"content\":\"\\\"\\\"\\\"FastMCP server exposing Langflow operations as MCP tools.\\n\\nConnects to a running Langflow server via REST API. Flow data is never\\ncached \u2014 every mutating tool does GET -> modify -> PATCH. The component\\nregistry is cached on first access.\\n\\nTools are organized into groups: auth, flow, component, connection, execution, batch.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport contextlib\\nimport contextvars\\nimport copy\\nimport re\\nfrom contextlib import asynccontextmanager\\nfrom typing import TYPE_CHECKING, Any\\n\\nif TYPE_CHECKING:\\n    from collections.abc import AsyncIterator\\n\\nfrom mcp.server.fastmcp import Context, FastMCP\\n\\nfrom lfx.base.mcp.pydantic_compat import ensure_fastmcp_settings_ready\\nfrom lfx.graph.flow_builder import (\\n    add_component as fb_add_component,\\n)\\nfrom lfx.graph.flow_builder import (\\n    add_connection as fb_add_connection,\\n)\\nfrom lfx.graph.flow_builder import (\\n    configure_component as fb_configure,\\n)\\nfrom lfx.graph.flow_builder import (\\n    empty_flow,\\n    ensure_tool_mode_supported,\\n    layout_flow,\\n    needs_server_update,\\n    parse_flow_spec,\\n)\\nfrom lfx.graph.flow_builder import (\\n    flow_graph_repr as fb_graph_repr,\\n)\\nfrom lfx.graph.flow_builder import (\\n    flow_info as fb_flow_info,\\n)\\nfrom lfx.graph.flow_builder import (\\n    flow_to_spec_summary as fb_spec_summary,\\n)\\nfrom lfx.graph.flow_builder import (\\n    get_component as fb_get_component,\\n)\\nfrom lfx.graph.flow_builder import (\\n    list_components as fb_list_components,\\n)\\nfrom lfx.graph.flow_builder import (\\n    remove_component as fb_remove_component,\\n)\\nfrom lfx.graph.flow_builder import (\\n    remove_connection as fb_remove_connection,\\n)\\nfrom lfx.graph.flow_builder.spec import validate_spec_references\\nfrom lfx.log.logger import logger\\nfrom lfx.mcp.client import LangflowClient\\nfrom lfx.mcp.registry import (\\n    describe_component as reg_describe,\\n)\\nfrom lfx.mcp.registry import (\\n    load_registry,\\n    search_registry,\\n)\\nfrom lfx.services.telemetry import MCPToolPayload, TelemetryService\\n\\n# Session state. Module-level singletons for stdio (single agent), with\\n# contextvars overlay for SSE (multiple concurrent agents).\\n_client_var: contextvars.ContextVar[LangflowClient | None] = contextvars.ContextVar(\\\"_client\\\", default=None)\\n_registry_var: contextvars.ContextVar[dict[str, dict] | None] = contextvars.ContextVar(\\\"_registry\\\", default=None)\\n_shared_client: LangflowClient | None = None\\n_shared_registry: dict[str, dict] | None = None\\n_telemetry: TelemetryService | None = None\\n\\n\\n@asynccontextmanager\\nasync def _telemetry_lifespan(_server: FastMCP) -> AsyncIterator[dict]:\\n    \\\"\\\"\\\"Start/stop the telemetry service with the MCP server lifecycle.\\\"\\\"\\\"\\n    global _telemetry  # noqa: PLW0603\\n    svc = TelemetryService()\\n    svc.start()\\n    _telemetry = svc\\n    try:\\n        yield {}\\n    finally:\\n        await svc.stop()\\n        _telemetry = None\\n\\n\\nensure_fastmcp_settings_ready()\\nmcp = FastMCP(\\n    \\\"langflow-mcp\\\",\\n    instructions=(\\n        \\\"Langflow MCP server -- build and run AI flows on a Langflow instance.\\\\n\\\"\\n        \\\"\\\\n\\\"\\n        \\\"Typical workflow:\\\\n\\\"\\n        \\\"  1. login (or set LANGFLOW_API_KEY env var)\\\\n\\\"\\n        \\\"  2. search_component_types / describe_component_type to discover components\\\\n\\\"\\n        \\\"  3. create_flow_from_spec to define nodes, edges, and config in one text spec\\\\n\\\"\\n        \\\"     (or step-by-step: create_flow, add_component, configure_component, connect_components)\\\\n\\\"\\n        \\\"  4. run_flow to execute\\\\n\\\"\\n        \\\"\\\\n\\\"\\n        \\\"Key concepts:\\\\n\\\"\\n        \\\"- describe_component_type shows a type's inputs, outputs, fields, and advanced_fields\\\\n\\\"\\n        \\\"- Connections are type-safe: an output's types must overlap with the input's input_types\\\\n\\\"\\n        \\\"- Outputs named 'component_as_tool' turn any component into a Tool for an Agent\\\\n\\\"\\n        \\\"- search_component_types with no args returns all available types\\\\n\\\"\\n        \\\"- Use batch to send multiple actions in one call with $N.field references\\\"\\n    ),\\n    lifespan=_telemetry_lifespan,\\n)\\n\\n\\ndef _get_client() -> LangflowClient:\\n    # Try contextvar first (SSE sessions), fall back to shared (stdio)\\n    client = _client_var.get()\\n    if client is not None:\\n        return client\\n    global _shared_client  # noqa: PLW0603\\n    if _shared_client is None:\\n        _shared_client = LangflowClient()\\n    return _shared_client\\n\\n\\ndef _set_client(client: LangflowClient) -> None:\\n    global _shared_client, _shared_registry  # noqa: PLW0603\\n    _client_var.set(client)\\n    # Invalidate the shared registry when the client changes, since the\\n    # registry was loaded against the old client's server.\\n    if _shared_client is not client:\\n        _shared_registry = None\\n    _shared_client = client\\n\\n\\n@contextlib.contextmanager\\ndef client_scope(client: LangflowClient):\\n    \\\"\\\"\\\"Bind ``client`` for the current async context only (host mounts).\\n\\n    Unlike ``_set_client`` this never touches the shared stdio client, so an\\n    HTTP mount can serve concurrent callers with per-request credentials\\n    without cross-contaminating sessions.\\n    \\\"\\\"\\\"\\n    token = _client_var.set(client)\\n    try:\\n        yield client\\n    finally:\\n        _client_var.reset(token)\\n\\n\\nasync def _get_registry() -> dict[str, dict]:\\n    registry = _registry_var.get()\\n    if registry is not None:\\n        return registry\\n    global _shared_registry  # noqa: PLW0603\\n    if _shared_registry is not None:\\n        return _shared_registry\\n    _shared_registry = await load_registry(_get_client())\\n    _registry_var.set(_shared_registry)\\n    return _shared_registry\\n\\n\\ndef _get_telemetry() -> TelemetryService | None:\\n    return _telemetry\\n\\n\\ndef _tracked(fn):\\n    \\\"\\\"\\\"Decorator that sends an MCPToolPayload after each tool call.\\\"\\\"\\\"\\n    import functools\\n    import time\\n\\n    @functools.wraps(fn)\\n    async def wrapper(*args, **kwargs):\\n        t0 = time.monotonic()\\n        try:\\n            result = await fn(*args, **kwargs)\\n        except Exception as exc:\\n            with contextlib.suppress(BaseException):\\n                svc = _get_telemetry()\\n                if svc is not None:\\n                    await svc.log_mcp_tool(\\n                        MCPToolPayload(\\n                            tool=fn.__name__,\\n                            success=False,\\n                            ms=int((time.monotonic() - t0) * 1000),\\n                            error=type(exc).__name__,\\n                        )\\n                    )\\n            raise\\n        with contextlib.suppress(BaseException):\\n            svc = _get_telemetry()\\n            if svc is not None:\\n                await svc.log_mcp_tool(\\n                    MCPToolPayload(tool=fn.__name__, success=True, ms=int((time.monotonic() - t0) * 1000))\\n                )\\n        return result\\n\\n    return wrapper\\n\\n\\nasync def _get_flow(flow_id: str) -> dict:\\n    \\\"\\\"\\\"Fetch a flow from the server.\\\"\\\"\\\"\\n    return await _get_client().get(f\\\"/flows/{flow_id}\\\")\\n\\n\\nasync def _patch_flow(flow_id: str, flow: dict) -> dict:\\n    \\\"\\\"\\\"Patch a flow on the server.\\\"\\\"\\\"\\n    return await _get_client().patch(f\\\"/flows/{flow_id}\\\", json_data={\\\"data\\\": flow[\\\"data\\\"]})\\n\\n\\ndef _extract_vertex_error(build_data: dict[str, Any]) -> str:\\n    \\\"\\\"\\\"Best-effort error message from a failed end_vertex event payload.\\n\\n    On failure, the build pipeline puts the exception in `params` and stuffs\\n    a structured error into the first output's `message`. Prefer the structured\\n    message; fall back to params; fall back to a generic string.\\n    \\\"\\\"\\\"\\n    outputs = (build_data.get(\\\"data\\\") or {}).get(\\\"outputs\\\") or {}\\n    for output in outputs.values():\\n        if not isinstance(output, dict):\\n            continue\\n        message = output.get(\\\"message\\\")\\n        if isinstance(message, dict) and message.get(\\\"errorMessage\\\"):\\n            return str(message[\\\"errorMessage\\\"])\\n    params = build_data.get(\\\"params\\\")\\n    if params:\\n        return str(params)\\n    return \\\"Unknown error\\\"\\n\\n\\n# ---------------------------------------------------------------------------\\n# Auth\\n# ---------------------------------------------------------------------------\\n\\n\\n@mcp.tool()\\n@_tracked\\nasync def login(username: str, password: str, server_url: str | None = None) -> dict[str, str]:\\n    \\\"\\\"\\\"Authenticate with a Langflow server. Call this first.\\n\\n    Credentials are stored and reused for all subsequent calls.\\n\\n    Args:\\n        username: Langflow username.\\n        password: Langflow password.\\n        server_url: Server URL (defaults to LANGFLOW_SERVER_URL env var or http://localhost:7860).\\n    \\\"\\\"\\\"\\n    # Only close the client owned by this session (contextvar). The shared\\n    # fallback is still overwritten by _set_client below, but we avoid\\n    # closing it here since another session may be using it.\\n    old_client = _client_var.get()\\n    if old_client is not None:\\n        await old_client.close()\\n    client = LangflowClient(server_url=server_url)\\n    _set_client(client)\\n    # Clear only this session's cached registry; leave _shared_registry\\n    # intact so other sessions are not disrupted.\\n    _registry_var.set(None)\\n    await client.login(username, password)\\n    return {\\\"status\\\": \\\"authenticated\\\", \\\"server_url\\\": client.server_url}\\n\\n\\n# ---------------------------------------------------------------------------\\n# Flow\\n# ---------------------------------------------------------------------------\\n\\n\\n@mcp.tool()\\n@_tracked\\nasync def create_flow(name: str = \\\"Untitled Flow\\\", description: str = \\\"\\\") -> dict[str, Any]:\\n    \\\"\\\"\\\"Create a new empty flow. Returns the flow's id, name, and description.\\n\\n    Args:\\n        name: Flow name.\\n        description: Flow description.\\n    \\\"\\\"\\\"\\n    flow = empty_flow(name=name, description=description)\\n    result = await _get_client().post(\\\"/flows/\\\", json_data=flow)\\n    return {\\\"id\\\": result[\\\"id\\\"], \\\"name\\\": result[\\\"name\\\"], \\\"description\\\": result.get(\\\"description\\\", \\\"\\\")}\\n\\n\\n_TEMPLATE_VAR_RE = re.compile(r\\\"\\\\{(\\\\w+)\\\\}\\\")\\n\\nPROMPT_TYPES = {\\\"Prompt Template\\\", \\\"Prompt\\\"}\\n\\n\\nasync def _create_prompt_template_vars(flow_id: str, parsed: dict, id_map: dict[str, str]) -> None:\\n    \\\"\\\"\\\"Create dynamic input fields for Prompt template variables.\\n\\n    When a Prompt Template's template contains {variable_name} placeholders,\\n    the UI creates input fields for them. This function does the same so that\\n    edges can connect to those fields.\\n    \\\"\\\"\\\"\\n    # Find Prompt nodes that have template config\\n    node_types = {n[\\\"id\\\"]: n[\\\"type\\\"] for n in parsed[\\\"nodes\\\"]}\\n    prompt_nodes = {sid for sid, ntype in node_types.items() if ntype in PROMPT_TYPES}\\n    if not prompt_nodes:\\n        return\\n\\n    flow = await _get_flow(flow_id)\\n    changed = False\\n\\n    for spec_id in prompt_nodes:\\n        real_id = id_map.get(spec_id)\\n        if real_id is None:\\n            continue\\n\\n        # Find the node in the flow\\n        node = None\\n        for n in flow.get(\\\"data\\\", {}).get(\\\"nodes\\\", []):\\n            if n.get(\\\"data\\\", {}).get(\\\"id\\\") == real_id:\\n                node = n\\n                break\\n        if node is None:\\n            continue\\n\\n        template = node[\\\"data\\\"].get(\\\"node\\\", {}).get(\\\"template\\\", {})\\n        template_value = \\\"\\\"\\n        if isinstance(template.get(\\\"template\\\"), dict):\\n            template_value = template[\\\"template\\\"].get(\\\"value\\\", \\\"\\\")\\n\\n        if not template_value:\\n            continue\\n\\n        # Parse {variable_name} placeholders\\n        variables = _TEMPLATE_VAR_RE.findall(template_value)\\n        for var_name in variables:\\n            if var_name in template:\\n                continue  # already exists\\n            template[var_name] = {\\n                \\\"_input_type\\\": \\\"MessageInput\\\",\\n                \\\"advanced\\\": False,\\n                \\\"display_name\\\": var_name,\\n                \\\"dynamic\\\": False,\\n                \\\"info\\\": \\\"\\\",\\n                \\\"input_types\\\": [\\\"Message\\\"],\\n                \\\"list\\\": False,\\n                \\\"load_from_db\\\": False,\\n                \\\"name\\\": var_name,\\n                \\\"placeholder\\\": \\\"\\\",\\n                \\\"required\\\": False,\\n                \\\"show\\\": True,\\n                \\\"title_case\\\": False,\\n                \\\"tool_mode\\\": False,\\n                \\\"trace_as_metadata\\\": True,\\n                \\\"type\\\": \\\"str\\\",\\n                \\\"value\\\": \\\"\\\",\\n            }\\n            changed = True\\n\\n        # Update custom_fields to track template variables\\n        custom_fields = node[\\\"data\\\"][\\\"node\\\"].setdefault(\\\"custom_fields\\\", {})\\n        custom_fields[\\\"template\\\"] = variables\\n\\n    if changed:\\n        await _patch_flow(flow_id, flow)\\n\\n\\n@mcp.tool()\\n@_tracked\\nasync def create_flow_from_spec(spec: str, *, validate: bool = True) -> dict[str, Any]:\\n    \\\"\\\"\\\"Create a complete flow from a compact text spec. Best for building full flows.\\n\\n    Format:\\n        name: My Chatbot\\n        description: A simple chatbot\\n\\n        nodes:\\n          A: ChatInput\\n          B: OpenAIModel\\n          C: ChatOutput\\n\\n        edges:\\n          A.message -> B.input_value\\n          B.text_output -> C.input_value\\n\\n        config:\\n          B.model_name: gpt-4o\\n          B.temperature: 0.5\\n\\n    Use describe_component_type to find output/input names for edges.\\n    Connecting via component_as_tool auto-enables tool mode.\\n    Multi-line config values use YAML-style \\\"|\\\" continuation.\\n\\n    Args:\\n        spec: The flow spec as a text string.\\n        validate: Build the flow's graph to validate components and connections (default: True).\\n    \\\"\\\"\\\"\\n    parsed = parse_flow_spec(spec)\\n\\n    # Validate references before creating anything\\n    validate_spec_references(parsed)\\n\\n    # Create flow\\n    created = await create_flow(\\n        name=parsed.get(\\\"name\\\", \\\"Untitled Flow\\\"),\\n        description=parsed.get(\\\"description\\\", \\\"\\\"),\\n    )\\n    flow_id = created[\\\"id\\\"]\\n\\n    try:\\n        # Add all components\\n        id_map: dict[str, str] = {}\\n        for node in parsed[\\\"nodes\\\"]:\\n            result = await add_component(flow_id, node[\\\"type\\\"])\\n            id_map[node[\\\"id\\\"]] = result[\\\"id\\\"]\\n\\n        # Apply config via configure_component (handles dynamic fields automatically)\\n        for spec_id, params in parsed.get(\\\"config\\\", {}).items():\\n            await configure_component(flow_id, id_map[spec_id], params)\\n\\n        # Create dynamic template variable fields on Prompt components.\\n        # When a Prompt template contains {var_name}, the UI creates an input\\n        # field for it. We do the same here so edges can connect to them.\\n        await _create_prompt_template_vars(flow_id, parsed, id_map)\\n\\n        # Connect edges via connect_components (handles tool_mode automatically)\\n        for edge in parsed[\\\"edges\\\"]:\\n            await connect_components(\\n                flow_id,\\n                id_map[edge[\\\"source_id\\\"]],\\n                edge[\\\"source_output\\\"],\\n                id_map[edge[\\\"target_id\\\"]],\\n                edge[\\\"target_input\\\"],\\n            )\\n        # Validate by building the graph server-side and waiting for results\\n        if validate:\\n            validation = await validate_flow(flow_id)\\n            if not validation.get(\\\"valid\\\", False):\\n                errors = validation.get(\\\"errors\\\", [])\\n                detail = \\\"; \\\".join(e.get(\\\"error\\\", \\\"Unknown\\\") for e in errors)\\n                msg = f\\\"Flow validation failed: {detail}\\\"\\n                raise RuntimeError(msg)\\n    except Exception:\\n        # Signal settle so the UI banner doesn't hang\\n        with contextlib.suppress(Exception):\\n            await _get_client().post_event(flow_id, \\\"flow_settled\\\", \\\"Failed, rolling back\\\")\\n        # Clean up the partially-built flow (best-effort)\\n        with contextlib.suppress(Exception):\\n            await delete_flow(flow_id)\\n        raise\\n\\n    # Signal that the batch creation is complete\\n    await _get_client().post_event(flow_id, \\\"flow_settled\\\", \\\"Created flow from spec\\\")\\n\\n    # Return flow info\\n    info = await get_flow_info(flow_id)\\n    info[\\\"node_id_map\\\"] = id_map\\n    return info\\n\\n\\n@mcp.tool()\\n@_tracked\\nasync def list_flows(query: str | None = None) -> list[dict[str, Any]]:\\n    \\\"\\\"\\\"List flows on the server. Each result includes an ASCII graph diagram.\\n\\n    Args:\\n        query: Optional filter by name (case-insensitive).\\n    \\\"\\\"\\\"\\n    flows = await _get_client().get(\\\"/flows/\\\")\\n    results = []\\n    for f in flows:\\n        name = f.get(\\\"name\\\", \\\"\\\")\\n        if query and query.lower() not in name.lower():\\n            continue\\n        data = f.get(\\\"data\\\", {})\\n        results.append(\\n            {\\n                \\\"id\\\": f[\\\"id\\\"],\\n                \\\"name\\\": name,\\n                \\\"description\\\": f.get(\\\"description\\\", \\\"\\\"),\\n                \\\"graph\\\": fb_graph_repr(f),\\n                \\\"spec_summary\\\": fb_spec_summary(f),\\n                \\\"node_count\\\": len(data.get(\\\"nodes\\\", [])),\\n                \\\"edge_count\\\": len(data.get(\\\"edges\\\", [])),\\n            }\\n        )\\n    return results\\n\\n\\n@mcp.tool()\\n@_tracked\\nasync def get_flow_info(flow_id: str) -> dict[str, Any]:\\n    \\\"\\\"\\\"Get detailed info about a flow: components, connections, ASCII graph diagram.\\n\\n    Args:\\n        flow_id: The flow UUID.\\n    \\\"\\\"\\\"\\n    flow = await _get_flow(flow_id)\\n    info = fb_flow_info(flow)\\n    info[\\\"id\\\"] = flow_id\\n    info[\\\"graph\\\"] = fb_graph_repr(flow)\\n    info[\\\"spec_summary\\\"] = fb_spec_summary(flow)\\n    return info\\n\\n\\n@mcp.tool()\\n@_tracked\\nasync def delete_flow(flow_id: str) -> dict[str, str]:\\n    \\\"\\\"\\\"Delete a flow from the server.\\n\\n    Args:\\n        flow_id: The flow UUID to delete.\\n    \\\"\\\"\\\"\\n    await _get_client().delete(f\\\"/flows/{flow_id}\\\")\\n    return {\\\"deleted\\\": flow_id}\\n\\n\\n@mcp.tool()\\n@_tracked\\nasync def duplicate_flow(flow_id: str, new_name: str | None = None) -> dict[str, Any]:\\n    \\\"\\\"\\\"Create a copy of an existing flow.\\n\\n    Args:\\n        flow_id: The UUID of the flow to duplicate.\\n        new_name: Name for the copy (defaults to original name + \\\" (copy)\\\").\\n    \\\"\\\"\\\"\\n    flow = await _get_flow(flow_id)\\n    name = new_name or f\\\"{flow.get('name', 'Untitled')} (copy)\\\"\\n    copy_data = {\\n        \\\"name\\\": name,\\n        \\\"description\\\": flow.get(\\\"description\\\", \\\"\\\"),\\n        \\\"data\\\": flow.get(\\\"data\\\", {}),\\n    }\\n    result = await _get_client().post(\\\"/flows/\\\", json_data=copy_data)\\n    return {\\\"id\\\": result[\\\"id\\\"], \\\"name\\\": result[\\\"name\\\"], \\\"description\\\": result.get(\\\"description\\\", \\\"\\\")}\\n\\n\\n@mcp.tool()\\n@_tracked\\nasync def list_starter_projects() -> list[dict[str, Any]]:\\n    \\\"\\\"\\\"List pre-built example flows. Use use_starter_project to create one.\\\"\\\"\\\"\\n    flows = await _get_client().get(\\\"/flows/basic_examples/\\\")\\n    return [\\n        {\\n            \\\"name\\\": f.get(\\\"name\\\", \\\"\\\"),\\n            \\\"description\\\": f.get(\\\"description\\\", \\\"\\\"),\\n            \\\"graph\\\": fb_graph_repr(f),\\n        }\\n        for f in flows\\n    ]\\n\\n\\n@mcp.tool()\\n@_tracked\\nasync def use_starter_project(starter_name: str, new_name: str | None = None) -> dict[str, Any]:\\n    \\\"\\\"\\\"Create a new flow from a starter project template.\\n\\n    Args:\\n        starter_name: Exact name from list_starter_projects (case-insensitive).\\n        new_name: Name for the new flow (defaults to starter name).\\n    \\\"\\\"\\\"\\n    flows = await _get_client().get(\\\"/flows/basic_examples/\\\")\\n    starter = None\\n    for f in flows:\\n        if f.get(\\\"name\\\", \\\"\\\").lower() == starter_name.lower():\\n            starter = f\\n            break\\n    if starter is None:\\n        available = [f.get(\\\"name\\\", \\\"\\\") for f in flows]\\n        msg = f\\\"Starter project '{starter_name}' not found. Available: {available}\\\"\\n        raise ValueError(msg)\\n\\n    name = new_name or starter.get(\\\"name\\\", \\\"Untitled\\\")\\n    copy_data = {\\n        \\\"name\\\": name,\\n        \\\"description\\\": starter.get(\\\"description\\\", \\\"\\\"),\\n        \\\"data\\\": starter.get(\\\"data\\\", {}),\\n    }\\n    result = await _get_client().post(\\\"/flows/\\\", json_data=copy_data)\\n    return {\\\"id\\\": result[\\\"id\\\"], \\\"name\\\": result[\\\"name\\\"], \\\"description\\\": result.get(\\\"description\\\", \\\"\\\")}\\n\\n\\n# ---------------------------------------------------------------------------\\n# Component\\n# ---------------------------------------------------------------------------\\n\\n\\n@mcp.tool()\\n@_tracked\\nasync def add_component(flow_id: str, component_type: str) -> dict[str, Any]:\\n    \\\"\\\"\\\"Add a component to a flow. Returns the component's id and display_name.\\n\\n    Use search_component_types or describe_component_type to discover types.\\n\\n    Args:\\n        flow_id: The flow UUID.\\n        component_type: Component type name (e.g. \\\"ChatInput\\\", \\\"OpenAIModel\\\").\\n    \\\"\\\"\\\"\\n    flow = await _get_flow(flow_id)\\n    registry = await _get_registry()\\n    result = fb_add_component(flow, component_type, registry)\\n    layout_flow(flow)\\n    await _patch_flow(flow_id, flow)\\n    await _get_client().post_event(flow_id, \\\"component_added\\\", f\\\"Added {component_type}\\\")\\n    return result\\n\\n\\n@mcp.tool()\\n@_tracked\\nasync def remove_component(flow_id: str, component_id: str) -> dict[str, str]:\\n    \\\"\\\"\\\"Remove a component and all its connections from a flow.\\n\\n    Args:\\n        flow_id: The flow UUID.\\n        component_id: The component ID (e.g. \\\"ChatInput-a1B2c\\\").\\n    \\\"\\\"\\\"\\n    flow = await _get_flow(flow_id)\\n    fb_remove_component(flow, component_id)\\n    layout_flow(flow)\\n    await _patch_flow(flow_id, flow)\\n    await _get_client().post_event(flow_id, \\\"component_removed\\\", f\\\"Removed {component_id}\\\")\\n    return {\\\"removed\\\": component_id}\\n\\n\\n_TRUTHY_STRINGS = {\\\"true\\\", \\\"yes\\\", \\\"1\\\", \\\"on\\\"}\\n_FALSY_STRINGS = {\\\"false\\\", \\\"no\\\", \\\"0\\\", \\\"off\\\", \\\"\\\"}\\n\\n\\ndef _coerce_param_value(value: Any, field_type: str | None) -> Any:\\n    \\\"\\\"\\\"Coerce a spec-supplied value to the field's declared type.\\n\\n    YAML config blocks in create_flow_from_spec naturally produce ints, floats,\\n    and bools where the underlying component field expects a different type\\n    (e.g. `temperature: 0.5` for a float, `model_name: gpt-4o` for a string,\\n    `should_store_message: true` for a bool). Without this coercion, the value\\n    lands in the template as-is and the downstream build chokes (string-typed\\n    fields like ChatInput.input_value cannot construct a Message from an int).\\n\\n    Only the four primitive shapes that YAML / JSON produce are handled:\\n    ``str``, ``int``, ``float``, ``bool``. ``list``-typed fields, code, dicts,\\n    and anything else pass through unchanged. None passes through unchanged\\n    (clearing a field is a valid intent).\\n    \\\"\\\"\\\"\\n    if value is None or field_type is None:\\n        return value\\n    if field_type == \\\"str\\\":\\n        if isinstance(value, str):\\n            return value\\n        if isinstance(value, bool):\\n            # Important: bool is a subclass of int in Python, so the str cast\\n            # would give \\\"True\\\"/\\\"False\\\" (capitalized) when most templates\\n            # expect lowercase. Match the YAML-spec convention.\\n            return \\\"true\\\" if value else \\\"false\\\"\\n        if isinstance(value, (int, float)):\\n            return str(value)\\n        return value\\n    if field_type == \\\"int\\\":\\n        if isinstance(value, bool):\\n            return int(value)\\n        if isinstance(value, int):\\n            return value\\n        if isinstance(value, float) and value.is_integer():\\n            return int(value)\\n        if isinstance(value, str):\\n            try:\\n                return int(value)\\n            except ValueError:\\n                return value\\n        return value\\n    if field_type == \\\"float\\\":\\n        if isinstance(value, bool):\\n            return float(value)\\n        if isinstance(value, (int, float)):\\n            return float(value)\\n        if isinstance(value, str):\\n            try:\\n                return float(value)\\n            except ValueError:\\n                return value\\n        return value\\n    if field_type == \\\"bool\\\":\\n        if isinstance(value, bool):\\n            return value\\n        if isinstance(value, (int, float)):\\n            return bool(value)\\n        if isinstance(value, str):\\n            lowered = value.strip().lower()\\n            if lowered in _TRUTHY_STRINGS:\\n                return True\\n            if lowered in _FALSY_STRINGS:\\n                return False\\n        return value\\n    return value\\n\\n\\n@mcp.tool()\\n@_tracked\\nasync def configure_component(\\n    flow_id: str,\\n    component_id: str,\\n    params: dict[str, Any],\\n) -> dict[str, Any]:\\n    \\\"\\\"\\\"Set parameter values on a component.\\n\\n    Use get_component_info to check current values, or describe_component_type\\n    to see available fields. Some fields trigger server-side template updates\\n    (e.g. changing model_name may update available options) -- the response\\n    reflects the final state, no need to re-fetch.\\n\\n    Args:\\n        flow_id: The flow UUID.\\n        component_id: The component ID.\\n        params: Dict of parameter names to values (e.g. {\\\"model_name\\\": \\\"gpt-4o\\\", \\\"temperature\\\": 0.5}).\\n    \\\"\\\"\\\"\\n    client = _get_client()\\n    flow = await _get_flow(flow_id)\\n\\n    # Find the node to check for dynamic fields\\n    node = None\\n    for n in flow.get(\\\"data\\\", {}).get(\\\"nodes\\\", []):\\n        nid = n.get(\\\"data\\\", {}).get(\\\"id\\\", n.get(\\\"id\\\", \\\"\\\"))\\n        if nid == component_id:\\n            node = n\\n            break\\n\\n    if node is None:\\n        msg = f\\\"Component not found: {component_id}\\\"\\n        raise ValueError(msg)\\n\\n    template = node[\\\"data\\\"].get(\\\"node\\\", {}).get(\\\"template\\\", {})\\n\\n    # Separate dynamic fields from static ones\\n    static_params = {}\\n    warnings = []\\n    for key, raw_value in params.items():\\n        # Coerce primitive values (int / float / bool / str) to the field's\\n        # declared type before doing anything else, so YAML-parsed config from\\n        # create_flow_from_spec (where `temperature: 0.5` is a float and\\n        # `should_store_message: true` is a bool) doesn't reach a string-typed\\n        # field as the wrong primitive. Unknown / dict / list values pass\\n        # through unchanged.\\n        field_def = template.get(key) if isinstance(template.get(key), dict) else None\\n        field_type = field_def.get(\\\"type\\\") if field_def else None\\n        value = _coerce_param_value(raw_value, field_type)\\n        # Values supplied through this tool are literals. Do not leave a field\\n        # in global-variable mode, where the runtime would interpret a literal\\n        # secret (for example ``sk-...``) as the name of a stored variable.\\n        if field_def is not None and \\\"load_from_db\\\" in field_def:\\n            field_def[\\\"load_from_db\\\"] = False\\n        if needs_server_update(template, key):\\n            # Handle tool_mode specially\\n            if key == \\\"tool_mode\\\":\\n                enabled = value in (True, \\\"true\\\", \\\"True\\\", \\\"1\\\", 1)\\n                code = template.get(\\\"code\\\", {}).get(\\\"value\\\", \\\"\\\")\\n                updated = await client.post(\\n                    \\\"/custom_component/update\\\",\\n                    json_data={\\n                        \\\"code\\\": code,\\n                        \\\"template\\\": template,\\n                        \\\"field\\\": \\\"tool_mode\\\",\\n                        \\\"field_value\\\": enabled,\\n                        \\\"tool_mode\\\": enabled,\\n                    },\\n                )\\n                if not isinstance(updated, dict) or \\\"template\\\" not in updated:\\n                    msg = f\\\"Server returned invalid response for tool_mode update on '{component_id}'\\\"\\n                    raise RuntimeError(msg)\\n                node[\\\"data\\\"][\\\"node\\\"] = updated\\n                template = updated[\\\"template\\\"]\\n            else:\\n                # Set value in template before sending\\n                if key in template and isinstance(template[key], dict):\\n                    template[key][\\\"value\\\"] = value\\n                    # A value explicitly supplied to this tool is a literal.\\n                    # Preserve component defaults, but do not let the refresh\\n                    # endpoint resolve this value as a global-variable name.\\n                    if \\\"load_from_db\\\" in template[key]:\\n                        template[key][\\\"load_from_db\\\"] = False\\n                else:\\n                    template[key] = {\\\"value\\\": value}\\n                code = template.get(\\\"code\\\", {}).get(\\\"value\\\", \\\"\\\")\\n                tool_mode = node[\\\"data\\\"][\\\"node\\\"].get(\\\"tool_mode\\\", False)\\n                try:\\n                    updated = await client.post(\\n                        \\\"/custom_component/update\\\",\\n                        json_data={\\n                            \\\"code\\\": code,\\n                            \\\"template\\\": template,\\n                            \\\"field\\\": key,\\n                            \\\"field_value\\\": value,\\n                            \\\"tool_mode\\\": tool_mode,\\n                        },\\n                    )\\n                except RuntimeError:\\n                    # Server refresh failed (e.g. missing API key for model list).\\n                    # The value is already set in the template above, so save it\\n                    # locally and warn the agent.\\n                    warnings.append(\\n                        f\\\"Field '{key}' was set to '{value}' but the server-side \\\"\\n                        f\\\"refresh failed. This usually means a required credential \\\"\\n                        f\\\"(like an API key) is not configured on the component yet. \\\"\\n                        f\\\"Set the credential first, then reconfigure '{key}'.\\\"\\n                    )\\n                    continue\\n                if not isinstance(updated, dict) or \\\"template\\\" not in updated:\\n                    msg = f\\\"Server returned invalid response for '{key}' update on '{component_id}'\\\"\\n                    raise RuntimeError(msg)\\n                node[\\\"data\\\"][\\\"node\\\"] = updated\\n                template = updated[\\\"template\\\"]\\n        else:\\n            static_params[key] = value\\n\\n    # Apply static params\\n    if static_params:\\n        fb_configure(flow, component_id, static_params)\\n\\n    await _patch_flow(flow_id, flow)\\n    await _get_client().post_event(flow_id, \\\"component_configured\\\", f\\\"Configured {component_id}\\\")\\n    result: dict[str, Any] = {\\\"component_id\\\": component_id, \\\"configured\\\": list(params.keys())}\\n    if warnings:\\n        result[\\\"warnings\\\"] = warnings\\n    return result\\n\\n\\n@mcp.tool()\\n@_tracked\\nasync def list_components(flow_id: str) -> list[dict[str, Any]]:\\n    \\\"\\\"\\\"List all components in a flow with their IDs, names, and types.\\n\\n    Args:\\n        flow_id: The flow UUID.\\n    \\\"\\\"\\\"\\n    flow = await _get_flow(flow_id)\\n    return fb_list_components(flow)\\n\\n\\n@mcp.tool()\\n@_tracked\\nasync def get_component_info(\\n    flow_id: str,\\n    component_id: str,\\n    field_name: str | None = None,\\n) -> dict[str, Any]:\\n    \\\"\\\"\\\"Get a specific component instance's current parameter values and outputs.\\n\\n    Unlike describe_component_type (which shows the type definition),\\n    this returns the actual values set on a component in a flow.\\n    Sensitive fields (API keys, passwords) are redacted.\\n\\n    Args:\\n        flow_id: The flow UUID.\\n        component_id: The component ID.\\n        field_name: Optional -- narrow the response to a single field.\\n    \\\"\\\"\\\"\\n    flow = await _get_flow(flow_id)\\n    info = fb_get_component(flow, component_id)\\n\\n    # Redact sensitive params (checks field name against SENSITIVE_KEYWORDS)\\n    from lfx.mcp.redact import is_sensitive_field\\n\\n    for key in list(info.get(\\\"params\\\", {}).keys()):\\n        if is_sensitive_field(key) and info[\\\"params\\\"][key]:\\n            info[\\\"params\\\"][key] = \\\"***REDACTED***\\\"\\n\\n    if field_name is None:\\n        return info\\n\\n    # Return just the requested field\\n    if field_name not in info.get(\\\"params\\\", {}):\\n        available = list(info.get(\\\"params\\\", {}).keys())\\n        msg = f\\\"Field '{field_name}' not found on component '{component_id}'. Available: {available}\\\"\\n        raise ValueError(msg)\\n\\n    # Get the raw field metadata from the node template\\n    node = None\\n    for n in flow.get(\\\"data\\\", {}).get(\\\"nodes\\\", []):\\n        nid = n.get(\\\"data\\\", {}).get(\\\"id\\\", n.get(\\\"id\\\", \\\"\\\"))\\n        if nid == component_id:\\n            node = n\\n            break\\n\\n    field_meta = {}\\n    if node is not None:\\n        template = node[\\\"data\\\"].get(\\\"node\\\", {}).get(\\\"template\\\", {})\\n        raw_field = template.get(field_name, {})\\n        if isinstance(raw_field, dict):\\n            field_meta = {\\n                \\\"type\\\": raw_field.get(\\\"type\\\", \\\"\\\"),\\n                \\\"display_name\\\": raw_field.get(\\\"display_name\\\", field_name),\\n                \\\"required\\\": raw_field.get(\\\"required\\\", False),\\n                \\\"real_time_refresh\\\": raw_field.get(\\\"real_time_refresh\\\", False),\\n            }\\n\\n    return {\\n        \\\"component_id\\\": component_id,\\n        \\\"field_name\\\": field_name,\\n        \\\"value\\\": info[\\\"params\\\"][field_name],\\n        **field_meta,\\n    }\\n\\n\\n@mcp.tool()\\n@_tracked\\nasync def search_component_types(\\n    query: str | None = None,\\n    category: str | None = None,\\n    output_type: str | None = None,\\n) -> list[dict[str, Any]]:\\n    \\\"\\\"\\\"Find component types by name, category, or output type. Call with no args to list all.\\n\\n    Args:\\n        query: Search term to filter by name or category (case-insensitive).\\n        category: Filter by category name, case-insensitive (e.g. \\\"models\\\", \\\"inputs\\\", \\\"outputs\\\").\\n        output_type: Filter by what the component produces (e.g. \\\"LanguageModel\\\", \\\"Message\\\", \\\"Tool\\\").\\n    \\\"\\\"\\\"\\n    registry = await _get_registry()\\n    return search_registry(registry, query=query, category=category, output_type=output_type)\\n\\n\\n@mcp.tool()\\n@_tracked\\nasync def describe_component_type(component_type: str) -> dict[str, Any]:\\n    \\\"\\\"\\\"Get a component type's definition: inputs (connectable), outputs, fields, and advanced_fields.\\n\\n    Use this to learn what a component accepts before adding it to a flow.\\n    Inputs show input_types -- connect outputs whose types overlap.\\n    Outputs named 'component_as_tool' turn any component into a Tool for Agents.\\n\\n    Args:\\n        component_type: The component type name (e.g. \\\"ChatInput\\\", \\\"OpenAIModel\\\").\\n    \\\"\\\"\\\"\\n    registry = await _get_registry()\\n    return reg_describe(registry, component_type)\\n\\n\\n@mcp.tool()\\n@_tracked\\nasync def components(\\n    query: str | None = None,\\n    component_type: str | None = None,\\n    category: str | None = None,\\n    output_type: str | None = None,\\n) -> list[dict[str, Any]] | dict[str, Any]:\\n    \\\"\\\"\\\"Search or describe component types in one call.\\n\\n    With component_type: returns full description (inputs, outputs, fields).\\n    Without component_type: searches/lists component types.\\n    No args: lists all available types.\\n\\n    Args:\\n        query: Search term to filter by name or category.\\n        component_type: If given, describe this specific type instead of searching.\\n        category: Filter by category (e.g. \\\"models\\\", \\\"inputs\\\").\\n        output_type: Filter by output type (e.g. \\\"LanguageModel\\\", \\\"Message\\\").\\n    \\\"\\\"\\\"\\n    registry = await _get_registry()\\n    if component_type:\\n        return reg_describe(registry, component_type)\\n    return search_registry(registry, query=query, category=category, output_type=output_type)\\n\\n\\n# ---------------------------------------------------------------------------\\n# Connection\\n# ---------------------------------------------------------------------------\\n\\n\\n@mcp.tool()\\n@_tracked\\nasync def connect_components(\\n    flow_id: str,\\n    source_id: str,\\n    source_output: str,\\n    target_id: str,\\n    target_input: str,\\n) -> dict[str, Any]:\\n    \\\"\\\"\\\"Connect an output of one component to an input of another.\\n\\n    Use describe_component_type to see available outputs and inputs.\\n    Connecting via 'component_as_tool' automatically enables tool mode.\\n\\n    Args:\\n        flow_id: The flow UUID.\\n        source_id: Source component ID.\\n        source_output: Output name on the source (e.g. \\\"message\\\", \\\"text_output\\\", \\\"component_as_tool\\\").\\n        target_id: Target component ID.\\n        target_input: Input name on the target (e.g. \\\"input_value\\\", \\\"tools\\\").\\n    \\\"\\\"\\\"\\n    flow = await _get_flow(flow_id)\\n\\n    # Auto-enable tool_mode when connecting via component_as_tool.\\n    registry: dict[str, dict] | None = None\\n    if source_output == \\\"component_as_tool\\\":\\n        registry = await _get_registry()\\n        # Validate FIRST, against the local copy: this used to PATCH tool_mode=True\\n        # onto the source before validating, so a component that cannot produce a\\n        # toolset output was left in a dead tool mode after the edge was rejected.\\n        ensure_tool_mode_supported(flow, source_id, registry)\\n        # The flip itself stays server-side. /custom_component/update rebuilds the\\n        # node via Component.run_and_validate_update_outputs, which is what inserts\\n        # the toolset metadata field (tools_metadata) into the template \u2014 a local\\n        # flip sets tool_mode and the output but cannot synthesize that field.\\n        await configure_component(flow_id, source_id, {\\\"tool_mode\\\": True})\\n        flow = await _get_flow(flow_id)\\n\\n    fb_add_connection(flow, source_id, source_output, target_id, target_input, registry=registry)\\n    layout_flow(flow)\\n    await _patch_flow(flow_id, flow)\\n    await _get_client().post_event(flow_id, \\\"connection_added\\\", f\\\"Connected {source_id} to {target_id}\\\")\\n    return {\\n        \\\"source_id\\\": source_id,\\n        \\\"source_output\\\": source_output,\\n        \\\"target_id\\\": target_id,\\n        \\\"target_input\\\": target_input,\\n    }\\n\\n\\n@mcp.tool()\\n@_tracked\\nasync def disconnect_components(\\n    flow_id: str,\\n    source_id: str,\\n    target_id: str,\\n    source_output: str | None = None,\\n    target_input: str | None = None,\\n) -> dict[str, Any]:\\n    \\\"\\\"\\\"Remove connections between two components.\\n\\n    Omit source_output and target_input to remove all connections between them.\\n\\n    Args:\\n        flow_id: The flow UUID.\\n        source_id: Source component ID.\\n        target_id: Target component ID.\\n        source_output: Only remove connections from this specific output.\\n        target_input: Only remove connections to this specific input.\\n    \\\"\\\"\\\"\\n    flow = await _get_flow(flow_id)\\n    removed = fb_remove_connection(flow, source_id, target_id, source_output, target_input)\\n    if removed == 0:\\n        msg = f\\\"No connections found between '{source_id}' and '{target_id}'\\\"\\n        raise ValueError(msg)\\n    layout_flow(flow)\\n    await _patch_flow(flow_id, flow)\\n    await _get_client().post_event(flow_id, \\\"connection_removed\\\", f\\\"Disconnected {source_id} from {target_id}\\\")\\n    return {\\\"removed_count\\\": removed}\\n\\n\\n# ---------------------------------------------------------------------------\\n# Execution\\n# ---------------------------------------------------------------------------\\n\\n\\n@mcp.tool()\\n@_tracked\\nasync def run_flow(\\n    flow_id: str,\\n    input_value: str = \\\"\\\",\\n    input_type: str = \\\"chat\\\",\\n    output_type: str = \\\"chat\\\",\\n    tweaks: dict[str, Any] | None = None,\\n    ctx: Context | None = None,\\n) -> dict[str, Any]:\\n    \\\"\\\"\\\"Run a flow and return the output.\\n\\n    Streams progress events (tokens, messages) when the client supports it.\\n\\n    Args:\\n        flow_id: The flow UUID.\\n        input_value: Text to send to the flow's input component.\\n        input_type: Input type (default: \\\"chat\\\").\\n        output_type: Output type (default: \\\"chat\\\").\\n        tweaks: Override component params at runtime: {component_id: {param: value}}.\\n        ctx: MCP context for progress reporting (injected automatically).\\n    \\\"\\\"\\\"\\n    request = {\\n        \\\"input_value\\\": input_value,\\n        \\\"input_type\\\": input_type,\\n        \\\"output_type\\\": output_type,\\n        \\\"tweaks\\\": tweaks or {},\\n    }\\n    client = _get_client()\\n\\n    result: dict[str, Any] = {}\\n    token_count = 0\\n    async for event in client.stream_post(f\\\"/run/{flow_id}?stream=true\\\", json_data=request):\\n        event_type = event.get(\\\"event\\\", \\\"\\\")\\n        data = event.get(\\\"data\\\", {})\\n\\n        if event_type == \\\"token\\\" and ctx is not None:\\n            token_count += 1\\n            chunk = data.get(\\\"chunk\\\", \\\"\\\")\\n            await ctx.report_progress(token_count, message=chunk)\\n\\n        elif event_type == \\\"end\\\":\\n            result = data.get(\\\"result\\\", data)\\n            break\\n\\n        elif event_type == \\\"error\\\":\\n            msg = data.get(\\\"error\\\", \\\"Flow execution failed\\\")\\n            raise RuntimeError(msg)\\n\\n    if not result:\\n        logger.warning(\\\"Streaming produced no result for flow %s, falling back to synchronous execution\\\", flow_id)\\n        return await client.post(f\\\"/run/{flow_id}\\\", json_data=request, timeout=300.0)\\n    return result\\n\\n\\n@mcp.tool()\\n@_tracked\\nasync def build_flow(flow_id: str) -> dict[str, Any]:\\n    \\\"\\\"\\\"Trigger a server-side build that validates components and connections.\\n\\n    Returns a job_id for the build. Use after creating or modifying a flow\\n    to catch errors early.\\n\\n    Args:\\n        flow_id: The flow UUID.\\n    \\\"\\\"\\\"\\n    result = await _get_client().post(f\\\"/build/{flow_id}/flow\\\")\\n    return {\\\"flow_id\\\": flow_id, \\\"job_id\\\": result.get(\\\"job_id\\\", \\\"\\\")}\\n\\n\\n@mcp.tool()\\n@_tracked\\nasync def get_build_results(flow_id: str) -> dict[str, Any]:\\n    \\\"\\\"\\\"Get per-component build results from the last run of a flow.\\n\\n    Returns each component's output data, validity status, and any errors.\\n    Use this to debug which component failed or inspect intermediate outputs.\\n\\n    Args:\\n        flow_id: The flow UUID.\\n    \\\"\\\"\\\"\\n    data = await _get_client().get(f\\\"/monitor/builds?flow_id={flow_id}\\\")\\n    builds = data.get(\\\"vertex_builds\\\", {})\\n\\n    # Flatten to a more agent-friendly format\\n    summary: dict[str, Any] = {}\\n    for comp_id, build_list in builds.items():\\n        if not build_list:\\n            continue\\n        latest = build_list[-1]  # most recent build\\n        entry: dict[str, Any] = {\\n            \\\"valid\\\": latest.get(\\\"valid\\\", False),\\n            \\\"timestamp\\\": latest.get(\\\"timestamp\\\", \\\"\\\"),\\n        }\\n        # Include output data if present\\n        build_data = latest.get(\\\"data\\\", {})\\n        if build_data:\\n            # Extract the result outputs\\n            results = build_data.get(\\\"results\\\", {})\\n            for output_name, output_val in results.items():\\n                if isinstance(output_val, dict) and \\\"text\\\" in output_val:\\n                    entry[f\\\"output_{output_name}\\\"] = output_val[\\\"text\\\"]\\n                elif isinstance(output_val, str):\\n                    entry[f\\\"output_{output_name}\\\"] = output_val\\n        # Include error info from artifacts if build failed\\n        artifacts = latest.get(\\\"artifacts\\\", {})\\n        if not latest.get(\\\"valid\\\") and artifacts:\\n            entry[\\\"error\\\"] = str(artifacts)\\n        summary[comp_id] = entry\\n\\n    return {\\\"flow_id\\\": flow_id, \\\"builds\\\": summary}\\n\\n\\n@mcp.tool()\\n@_tracked\\nasync def get_component_output(\\n    flow_id: str,\\n    component_id: str,\\n) -> dict[str, Any]:\\n    \\\"\\\"\\\"Get a specific component's output from the last run.\\n\\n    Use this to inspect what a component produced -- useful for debugging\\n    when the final output is wrong and you need to find which step broke.\\n\\n    Args:\\n        flow_id: The flow UUID.\\n        component_id: The component ID to inspect.\\n    \\\"\\\"\\\"\\n    data = await _get_client().get(f\\\"/monitor/builds?flow_id={flow_id}\\\")\\n    builds = data.get(\\\"vertex_builds\\\", {})\\n\\n    if component_id not in builds or not builds[component_id]:\\n        available = list(builds.keys())\\n        return {\\n            \\\"error\\\": f\\\"No build data for '{component_id}'\\\",\\n            \\\"available_components\\\": available,\\n        }\\n\\n    latest = builds[component_id][-1]\\n    result: dict[str, Any] = {\\n        \\\"component_id\\\": component_id,\\n        \\\"valid\\\": latest.get(\\\"valid\\\", False),\\n        \\\"timestamp\\\": latest.get(\\\"timestamp\\\", \\\"\\\"),\\n    }\\n\\n    build_data = latest.get(\\\"data\\\", {})\\n    if build_data:\\n        result[\\\"outputs\\\"] = build_data.get(\\\"results\\\", {})\\n\\n    artifacts = latest.get(\\\"artifacts\\\", {})\\n    if artifacts:\\n        result[\\\"artifacts\\\"] = artifacts\\n\\n    if not latest.get(\\\"valid\\\"):\\n        result[\\\"error\\\"] = \\\"Component build failed\\\"\\n\\n    return result\\n\\n\\n# ---------------------------------------------------------------------------\\n# Flow management\\n# ---------------------------------------------------------------------------\\n\\n\\n@mcp.tool()\\n@_tracked\\nasync def validate_flow(flow_id: str) -> dict[str, Any]:\\n    \\\"\\\"\\\"Validate a flow and return structured per-component results.\\n\\n    Streams the build inline (`event_delivery=direct`) and aggregates per-vertex\\n    results from `end_vertex` events. Fast-fails on the first failing component\\n    or top-level build error -- downstream vertices depend on upstream success\\n    and would not produce useful additional information.\\n\\n    Args:\\n        flow_id: The flow UUID.\\n    \\\"\\\"\\\"\\n    flow = await _get_flow(flow_id)\\n    expected = len(flow.get(\\\"data\\\", {}).get(\\\"nodes\\\", []))\\n    if expected == 0:\\n        return {\\\"valid\\\": True, \\\"component_count\\\": 0, \\\"errors\\\": [], \\\"warnings\\\": []}\\n\\n    completed: set[str] = set()\\n    errors: list[dict[str, str]] = []\\n\\n    try:\\n        async for event in _get_client().stream_post(f\\\"/build/{flow_id}/flow?event_delivery=direct\\\"):\\n            event_type = event.get(\\\"event\\\", \\\"\\\")\\n            data = event.get(\\\"data\\\") or {}\\n\\n            if event_type == \\\"end_vertex\\\":\\n                build_data = data.get(\\\"build_data\\\") or {}\\n                vertex_id = build_data.get(\\\"id\\\") or \\\"\\\"\\n                if vertex_id:\\n                    completed.add(vertex_id)\\n                if not build_data.get(\\\"valid\\\", False):\\n                    errors.append(\\n                        {\\n                            \\\"component_id\\\": vertex_id or \\\"unknown\\\",\\n                            \\\"error\\\": _extract_vertex_error(build_data),\\n                        }\\n                    )\\n                    # Fast-fail: downstream vertices won't run, no point waiting.\\n                    return {\\n                        \\\"valid\\\": False,\\n                        \\\"component_count\\\": len(completed),\\n                        \\\"errors\\\": errors,\\n                    }\\n\\n            elif event_type == \\\"error\\\":\\n                # Top-level build failure (e.g. graph could not be constructed).\\n                message = data.get(\\\"exception\\\") or data.get(\\\"reason\\\") or data.get(\\\"error\\\") or \\\"Build error\\\"\\n                return {\\n                    \\\"valid\\\": False,\\n                    \\\"component_count\\\": len(completed),\\n                    \\\"errors\\\": [{\\\"component_id\\\": \\\"flow\\\", \\\"error\\\": str(message)}],\\n                }\\n\\n            elif event_type == \\\"end\\\":\\n                break\\n    except RuntimeError as exc:\\n        return {\\n            \\\"valid\\\": False,\\n            \\\"error\\\": f\\\"Build request failed: {exc}\\\",\\n            \\\"component_count\\\": len(completed),\\n            \\\"errors\\\": errors,\\n        }\\n\\n    return {\\n        \\\"valid\\\": True,\\n        \\\"component_count\\\": len(completed),\\n        \\\"errors\\\": [],\\n    }\\n\\n\\n@mcp.tool()\\n@_tracked\\nasync def rename_flow(\\n    flow_id: str,\\n    name: str | None = None,\\n    description: str | None = None,\\n) -> dict[str, Any]:\\n    \\\"\\\"\\\"Update a flow's name and/or description.\\n\\n    Args:\\n        flow_id: The flow UUID.\\n        name: New name (omit to keep current).\\n        description: New description (omit to keep current).\\n    \\\"\\\"\\\"\\n    update: dict[str, Any] = {}\\n    if name is not None:\\n        update[\\\"name\\\"] = name\\n    if description is not None:\\n        update[\\\"description\\\"] = description\\n    if not update:\\n        msg = \\\"Provide at least name or description\\\"\\n        raise ValueError(msg)\\n\\n    result = await _get_client().patch(f\\\"/flows/{flow_id}\\\", json_data=update)\\n    return {\\\"id\\\": flow_id, \\\"name\\\": result.get(\\\"name\\\", \\\"\\\"), \\\"description\\\": result.get(\\\"description\\\", \\\"\\\")}\\n\\n\\n@mcp.tool()\\n@_tracked\\nasync def export_flow(flow_id: str) -> dict[str, Any]:\\n    \\\"\\\"\\\"Export a flow as a complete JSON object for backup or sharing.\\n\\n    Returns the full flow data with sensitive fields (API keys, passwords) redacted.\\n\\n    Args:\\n        flow_id: The flow UUID.\\n    \\\"\\\"\\\"\\n    from lfx.mcp.redact import redact_node\\n\\n    flow = await _get_flow(flow_id)\\n    data = flow.get(\\\"data\\\", {})\\n    # Redact sensitive fields before exposing to LLM context\\n    if \\\"nodes\\\" in data:\\n        data = {\\n            **data,\\n            \\\"nodes\\\": [{**n, \\\"data\\\": redact_node(n.get(\\\"data\\\", {}))} for n in data[\\\"nodes\\\"]],\\n        }\\n    return {\\n        \\\"id\\\": flow_id,\\n        \\\"name\\\": flow.get(\\\"name\\\", \\\"\\\"),\\n        \\\"description\\\": flow.get(\\\"description\\\", \\\"\\\"),\\n        \\\"data\\\": data,\\n    }\\n\\n\\n@mcp.tool()\\n@_tracked\\nasync def update_flow_from_spec(flow_id: str, spec: str) -> dict[str, Any]:\\n    \\\"\\\"\\\"Update an existing flow to match a spec, preserving the flow ID.\\n\\n    Replaces all nodes, edges, and config with what the spec defines.\\n    Useful for iterating on a flow without creating a new one each time.\\n\\n    Args:\\n        flow_id: The flow UUID to update.\\n        spec: Text spec in the same format as create_flow_from_spec.\\n    \\\"\\\"\\\"\\n    parsed = parse_flow_spec(spec)\\n\\n    validate_spec_references(parsed)\\n\\n    # Clear the existing flow's nodes and edges, then rebuild using the same\\n    # server-side tools as create_flow_from_spec so dynamic template refresh,\\n    # prompt variable creation, and component_as_tool auto-enable all work.\\n    # Validation is not performed here; callers can use validate_flow explicitly.\\n    flow = await _get_flow(flow_id)\\n    original_data = copy.deepcopy(flow[\\\"data\\\"])\\n    flow[\\\"data\\\"][\\\"nodes\\\"] = []\\n    flow[\\\"data\\\"][\\\"edges\\\"] = []\\n    patch_data: dict[str, Any] = {\\\"data\\\": flow[\\\"data\\\"]}\\n    if parsed.get(\\\"name\\\"):\\n        patch_data[\\\"name\\\"] = parsed[\\\"name\\\"]\\n    if parsed.get(\\\"description\\\"):\\n        patch_data[\\\"description\\\"] = parsed[\\\"description\\\"]\\n    await _get_client().patch(f\\\"/flows/{flow_id}\\\", json_data=patch_data)\\n\\n    try:\\n        # Add components via server (gets live templates)\\n        id_map: dict[str, str] = {}\\n        for node in parsed[\\\"nodes\\\"]:\\n            result = await add_component(flow_id, node[\\\"type\\\"])\\n            id_map[node[\\\"id\\\"]] = result[\\\"id\\\"]\\n\\n        # Configure via server (handles real_time_refresh and tool_mode)\\n        for spec_id, params in parsed.get(\\\"config\\\", {}).items():\\n            await configure_component(flow_id, id_map[spec_id], params)\\n\\n        # Create dynamic template variable fields on Prompt components\\n        await _create_prompt_template_vars(flow_id, parsed, id_map)\\n\\n        # Connect via server (handles component_as_tool auto-enable)\\n        for edge in parsed[\\\"edges\\\"]:\\n            await connect_components(\\n                flow_id,\\n                id_map[edge[\\\"source_id\\\"]],\\n                edge[\\\"source_output\\\"],\\n                id_map[edge[\\\"target_id\\\"]],\\n                edge[\\\"target_input\\\"],\\n            )\\n    except Exception:\\n        # Restore the original flow data so the user's flow is not destroyed\\n        with contextlib.suppress(Exception):\\n            await _get_client().post_event(flow_id, \\\"flow_settled\\\", \\\"Update failed, restoring\\\")\\n        with contextlib.suppress(Exception):\\n            await _get_client().patch(f\\\"/flows/{flow_id}\\\", json_data={\\\"data\\\": original_data})\\n        raise\\n\\n    await _get_client().post_event(flow_id, \\\"flow_settled\\\", \\\"Updated flow from spec\\\")\\n\\n    info = await get_flow_info(flow_id)\\n    info[\\\"node_id_map\\\"] = id_map\\n    return info\\n\\n\\nasync def _set_frozen(flow_id: str, component_id: str, *, frozen: bool) -> dict[str, str]:\\n    \\\"\\\"\\\"Set the frozen state of a component.\\\"\\\"\\\"\\n    flow = await _get_flow(flow_id)\\n    for node in flow.get(\\\"data\\\", {}).get(\\\"nodes\\\", []):\\n        nid = node.get(\\\"data\\\", {}).get(\\\"id\\\", node.get(\\\"id\\\", \\\"\\\"))\\n        if nid == component_id:\\n            node_config = node.get(\\\"data\\\", {}).get(\\\"node\\\")\\n            if node_config is None:\\n                msg = f\\\"Component '{component_id}' has malformed data (missing 'node' key)\\\"\\n                raise ValueError(msg)\\n            node_config[\\\"frozen\\\"] = frozen\\n            await _patch_flow(flow_id, flow)\\n            key = \\\"frozen\\\" if frozen else \\\"unfrozen\\\"\\n            return {key: component_id}\\n\\n    msg = f\\\"Component not found: {component_id}\\\"\\n    raise ValueError(msg)\\n\\n\\n@mcp.tool()\\n@_tracked\\nasync def freeze_component(flow_id: str, component_id: str) -> dict[str, str]:\\n    \\\"\\\"\\\"Freeze a component so it uses cached output and skips re-execution.\\n\\n    Useful when iterating on downstream components without paying the\\n    cost of re-running expensive upstream LLM calls.\\n\\n    Args:\\n        flow_id: The flow UUID.\\n        component_id: The component ID to freeze.\\n    \\\"\\\"\\\"\\n    result = await _set_frozen(flow_id, component_id, frozen=True)\\n    await _get_client().post_event(flow_id, \\\"component_configured\\\", f\\\"Froze {component_id}\\\")\\n    return result\\n\\n\\n@mcp.tool()\\n@_tracked\\nasync def unfreeze_component(flow_id: str, component_id: str) -> dict[str, str]:\\n    \\\"\\\"\\\"Unfreeze a component so it re-executes on the next run.\\n\\n    Args:\\n        flow_id: The flow UUID.\\n        component_id: The component ID to unfreeze.\\n    \\\"\\\"\\\"\\n    result = await _set_frozen(flow_id, component_id, frozen=False)\\n    await _get_client().post_event(flow_id, \\\"component_configured\\\", f\\\"Unfroze {component_id}\\\")\\n    return result\\n\\n\\n@mcp.tool(name=\\\"layout_flow\\\")\\n@_tracked\\nasync def layout_flow_tool(flow_id: str) -> dict[str, str]:\\n    \\\"\\\"\\\"Re-layout a flow's components using the Sugiyama algorithm.\\n\\n    Useful after adding or removing components to clean up positioning.\\n\\n    Args:\\n        flow_id: The flow UUID.\\n    \\\"\\\"\\\"\\n    flow = await _get_flow(flow_id)\\n    layout_flow(flow)\\n    await _patch_flow(flow_id, flow)\\n    await _get_client().post_event(flow_id, \\\"flow_updated\\\", \\\"Re-laid out flow\\\")\\n    return {\\\"laid_out\\\": flow_id}\\n\\n\\n@mcp.tool()\\n@_tracked\\nasync def notify_done(flow_id: str, summary: str | None = None) -> dict[str, str]:\\n    \\\"\\\"\\\"Signal that you are done modifying a flow.\\n\\n    Call this after completing a series of modifications so the UI updates immediately.\\n    If you don't call this, the UI will still update after a short timeout.\\n\\n    Args:\\n        flow_id: The flow UUID you were modifying.\\n        summary: Optional human-readable summary of what you did (e.g. \\\"Built a RAG pipeline with OpenAI and Pinecone\\\").\\n    \\\"\\\"\\\"\\n    try:\\n        await _get_client().post(\\n            f\\\"/flows/{flow_id}/events\\\",\\n            json_data={\\\"type\\\": \\\"flow_settled\\\", \\\"summary\\\": summary or \\\"\\\"},\\n        )\\n    except Exception:  # noqa: BLE001\\n        logger.warning(\\\"Failed to post flow_settled event\\\", exc_info=True)\\n        return {\\n            \\\"status\\\": \\\"warning\\\",\\n            \\\"flow_id\\\": flow_id,\\n            \\\"detail\\\": \\\"Event could not be delivered; UI will update after timeout\\\",\\n        }\\n    return {\\\"status\\\": \\\"ok\\\", \\\"flow_id\\\": flow_id}\\n\\n\\n# ---------------------------------------------------------------------------\\n# Batch\\n# ---------------------------------------------------------------------------\\n\\n# Tool name -> callable mapping (built lazily)\\n_TOOL_MAP: dict[str, Any] | None = None\\n\\n\\ndef _get_tool_map() -> dict[str, Any]:\\n    global _TOOL_MAP  # noqa: PLW0603\\n    if _TOOL_MAP is None:\\n        _TOOL_MAP = {\\n            \\\"login\\\": login,\\n            \\\"create_flow\\\": create_flow,\\n            \\\"create_flow_from_spec\\\": create_flow_from_spec,\\n            \\\"list_flows\\\": list_flows,\\n            \\\"get_flow_info\\\": get_flow_info,\\n            \\\"delete_flow\\\": delete_flow,\\n            \\\"duplicate_flow\\\": duplicate_flow,\\n            \\\"list_starter_projects\\\": list_starter_projects,\\n            \\\"use_starter_project\\\": use_starter_project,\\n            \\\"add_component\\\": add_component,\\n            \\\"remove_component\\\": remove_component,\\n            \\\"configure_component\\\": configure_component,\\n            \\\"list_components\\\": list_components,\\n            \\\"get_component_info\\\": get_component_info,\\n            \\\"search_component_types\\\": search_component_types,\\n            \\\"describe_component_type\\\": describe_component_type,\\n            \\\"connect_components\\\": connect_components,\\n            \\\"disconnect_components\\\": disconnect_components,\\n            \\\"run_flow\\\": run_flow,\\n            \\\"build_flow\\\": build_flow,\\n            \\\"validate_flow\\\": validate_flow,\\n            \\\"rename_flow\\\": rename_flow,\\n            \\\"export_flow\\\": export_flow,\\n            \\\"update_flow_from_spec\\\": update_flow_from_spec,\\n            \\\"get_build_results\\\": get_build_results,\\n            \\\"get_component_output\\\": get_component_output,\\n            \\\"components\\\": components,\\n            \\\"freeze_component\\\": freeze_component,\\n            \\\"unfreeze_component\\\": unfreeze_component,\\n            \\\"layout_flow\\\": layout_flow_tool,\\n            \\\"notify_done\\\": notify_done,\\n        }\\n    return _TOOL_MAP\\n\\n\\n_REF_PATTERN = re.compile(r\\\"^\\\\$(\\\\d+)\\\\.(\\\\w+)$\\\")\\n\\n\\ndef _resolve_refs(value: Any, results: list[Any]) -> Any:\\n    \\\"\\\"\\\"Replace $N.field references with actual values from previous results.\\\"\\\"\\\"\\n    if isinstance(value, str):\\n        match = _REF_PATTERN.match(value)\\n        if match:\\n            idx, field = int(match.group(1)), match.group(2)\\n            if idx >= len(results):\\n                msg = f\\\"Reference ${idx} is out of range (only {len(results)} results so far)\\\"\\n                raise ValueError(msg)\\n            result = results[idx]\\n            if isinstance(result, dict) and field in result:\\n                return result[field]\\n            msg = f\\\"${idx}.{field}: field '{field}' not found in result {idx}\\\"\\n            raise ValueError(msg)\\n        return value\\n    if isinstance(value, dict):\\n        return {k: _resolve_refs(v, results) for k, v in value.items()}\\n    if isinstance(value, list):\\n        return [_resolve_refs(v, results) for v in value]\\n    return value\\n\\n\\ndef _assistant_progress_forwarder(ctx: Context | None):\\n    \\\"\\\"\\\"Bridge assistant ``progress`` SSE events to MCP progress/log notifications.\\n\\n    Best-effort on purpose: clients without progress support just ignore the\\n    notifications, and a failed send must never break the tool call.\\n    \\\"\\\"\\\"\\n    if ctx is None:\\n        return None\\n    step_count = 0\\n\\n    async def forward(event: dict[str, Any]) -> None:\\n        nonlocal step_count\\n        step_count += 1\\n        message = str(event.get(\\\"message\\\") or event.get(\\\"step\\\") or \\\"working\\\")\\n        try:\\n            request_context = ctx.request_context\\n            progress_token = request_context.meta.progressToken if request_context.meta else None\\n            if progress_token is not None:\\n                # Not ctx.report_progress: it omits related_request_id, which the\\n                # stateless streamable-http transport needs to route onto the request stream.\\n                await request_context.session.send_progress_notification(\\n                    progress_token=progress_token,\\n                    progress=float(step_count),\\n                    message=message,\\n                    related_request_id=ctx.request_id,\\n                )\\n            await ctx.info(message)\\n        except Exception as exc:  # noqa: BLE001\\n            logger.debug(\\\"Could not forward assistant progress to the MCP client: %s\\\", exc)\\n\\n    return forward\\n\\n\\n@mcp.tool()\\n@_tracked\\nasync def run_assistant(\\n    instruction: str,\\n    flow_id: str | None = None,\\n    provider: str | None = None,\\n    model_name: str | None = None,\\n    session_id: str | None = None,\\n    ctx: Context | None = None,\\n) -> dict[str, Any]:\\n    \\\"\\\"\\\"Ask the Langflow Assistant to build, edit, or explain a flow.\\n\\n    The assistant runs server-side with its full agent loop (component search,\\n    flow build, canvas edits); this tool consumes it through the REST API with\\n    the caller's own credentials, so identity needs no extra argument. Any\\n    resulting canvas change is persisted to the flow and immediately visible\\n    in the Langflow UI.\\n\\n    Args:\\n        instruction: Natural-language request, e.g. \\\"Build a flow with a Chat\\n            Input connected to a Chat Output\\\". Max 2000 characters.\\n        flow_id: Optional id of an existing flow to edit. When omitted, a new\\n            flow is created first and the assistant works on it.\\n        provider: Optional model provider (e.g. \\\"OpenAI\\\", \\\"Ollama\\\"). Defaults\\n            to the first configured provider on the server.\\n        model_name: Optional model on that provider.\\n        session_id: Optional conversation id to keep multi-turn context.\\n        ctx: Injected MCP context; each assistant progress step is forwarded\\n            to the caller as an MCP progress notification and info log.\\n\\n    Returns:\\n        Dictionary with ``result`` (the assistant's reply), ``flow_id``,\\n        ``link`` (relative UI link), and any fields the assistant reports\\n        (``flow_changed``, ``session_id``, ``provider``, ``model_name``).\\n    \\\"\\\"\\\"\\n    client = _get_client()\\n    forward = _assistant_progress_forwarder(ctx)\\n    optional = {\\\"flow_id\\\": flow_id, \\\"provider\\\": provider, \\\"model_name\\\": model_name, \\\"session_id\\\": session_id}\\n    payload: dict[str, Any] = {\\\"instruction\\\": instruction, **{k: v for k, v in optional.items() if v}}\\n\\n    complete: dict[str, Any] | None = None\\n    # ``/assist/run`` (not ``/assist/stream``): the headless route APPLIES the canvas\\n    # changes. The stream route leaves them as a proposal for a UI card to approve,\\n    # which a non-interactive MCP caller has no way to accept \u2014 the edit would be lost.\\n    async for event in client.stream_post(\\\"/agentic/assist/run\\\", json_data=payload, timeout=600.0):\\n        kind = event.get(\\\"event\\\")\\n        if kind == \\\"progress\\\" and forward is not None:\\n            await forward(event)\\n        elif kind == \\\"error\\\":\\n            detail = event.get(\\\"message\\\") or \\\"Assistant run failed\\\"\\n            raise RuntimeError(str(detail))\\n        elif kind == \\\"complete\\\":\\n            complete = event.get(\\\"data\\\") or {}\\n\\n    if complete is None:\\n        # A truncated stream would otherwise return a success-shaped empty result.\\n        msg = \\\"Assistant stream ended without a complete event\\\"\\n        raise RuntimeError(msg)\\n\\n    result: dict[str, Any] = dict(complete)\\n    result.setdefault(\\\"result\\\", \\\"\\\")\\n    result.setdefault(\\\"link\\\", f\\\"/flow/{result.get('flow_id')}\\\")\\n    return result\\n\\n\\n@mcp.tool()\\n@_tracked\\nasync def batch(actions: list[dict[str, Any]]) -> list[dict[str, Any]]:\\n    \\\"\\\"\\\"Execute multiple actions in sequence, returning all results.\\n\\n    Use $N.field to reference results from previous actions (zero-indexed).\\n\\n    Example -- build a complete chatbot in one call:\\n        [\\n            {\\\"tool\\\": \\\"create_flow\\\", \\\"args\\\": {\\\"name\\\": \\\"My Chatbot\\\"}},\\n            {\\\"tool\\\": \\\"add_component\\\", \\\"args\\\": {\\\"flow_id\\\": \\\"$0.id\\\", \\\"component_type\\\": \\\"ChatInput\\\"}},\\n            {\\\"tool\\\": \\\"add_component\\\", \\\"args\\\": {\\\"flow_id\\\": \\\"$0.id\\\", \\\"component_type\\\": \\\"OpenAIModel\\\"}},\\n            {\\\"tool\\\": \\\"add_component\\\", \\\"args\\\": {\\\"flow_id\\\": \\\"$0.id\\\", \\\"component_type\\\": \\\"ChatOutput\\\"}},\\n            {\\\"tool\\\": \\\"connect_components\\\", \\\"args\\\": {\\n                \\\"flow_id\\\": \\\"$0.id\\\", \\\"source_id\\\": \\\"$1.id\\\", \\\"source_output\\\": \\\"message\\\",\\n                \\\"target_id\\\": \\\"$2.id\\\", \\\"target_input\\\": \\\"input_value\\\"\\n            }},\\n            {\\\"tool\\\": \\\"connect_components\\\", \\\"args\\\": {\\n                \\\"flow_id\\\": \\\"$0.id\\\", \\\"source_id\\\": \\\"$2.id\\\", \\\"source_output\\\": \\\"text_output\\\",\\n                \\\"target_id\\\": \\\"$3.id\\\", \\\"target_input\\\": \\\"input_value\\\"\\n            }}\\n        ]\\n\\n    Args:\\n        actions: List of {\\\"tool\\\": \\\"tool_name\\\", \\\"args\\\": {...}} dicts.\\n    \\\"\\\"\\\"\\n    tool_map = _get_tool_map()\\n    results: list[dict[str, Any]] = []\\n\\n    for i, action in enumerate(actions):\\n        tool_name = action.get(\\\"tool\\\", \\\"\\\")\\n        if tool_name not in tool_map:\\n            available = sorted(tool_map.keys())\\n            msg = f\\\"Action {i}: unknown tool '{tool_name}'. Available: {available}\\\"\\n            raise ValueError(msg)\\n\\n        raw_args = action.get(\\\"args\\\", {})\\n        resolved_args = _resolve_refs(raw_args, results)\\n\\n        try:\\n            result = await tool_map[tool_name](**resolved_args)\\n        except Exception as exc:\\n            msg = f\\\"Action {i} ('{tool_name}') failed: {exc}\\\"\\n            raise type(exc)(msg) from exc\\n        results.append(result if isinstance(result, dict) else {\\\"result\\\": result})\\n\\n    return results\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/mcp/tool_cache.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"79659ddab065d13480f54f2f3ed5de2df0bfcf55c4e22adecd6426775118cd8c\",\"content\":\"\\\"\\\"\\\"Per-request result cache for pure-read MCP tools.\\n\\nThe Langflow Assistant's flow-builder agent often re-invokes the same\\nread-only tool with identical args inside a single build session \u2014 e.g.\\n``describe_component(\\\"ChatInput\\\")`` called multiple times while wiring a\\ngraph, or ``search_components(\\\"LLM\\\")`` issued from successive planning\\nturns. Caching these calls within the request shaves real cost (fewer\\ncomponent-registry walks, fewer token-laden tool results in the LLM\\ncontext window) without changing observable behavior.\\n\\nScope is **per request**:\\n    - The cache lives in a ``contextvars.ContextVar`` so concurrent\\n      assistant requests (different SSE sessions, different users) never\\n      see each other's entries.\\n    - ``reset_tool_cache()`` is called by ``assistant_service`` at the\\n      start of every request, alongside ``reset_working_flow()``.\\n    - Child contexts spawned via ``copy_context()`` (e.g. ``asyncio.gather``\\n      tasks) get their own fresh cache. The lazy-allocate-on-first-write\\n      pattern is the same one used by ``_flow_events_var`` for events.\\n\\nEviction:\\n    - Bounded at ``MAX_CACHE_ENTRIES`` per request to cap memory growth in\\n      pathological agent runs that issue thousands of tool calls.\\n    - LRU order via ``collections.OrderedDict``: a cache hit moves the\\n      entry to the most-recent end, and a write past the cap drops the\\n      least-recently-used entry.\\n\\nErrors are NOT cached:\\n    - If the producer raises, the cache stays untouched. The next call\\n      with the same key re-runs the producer. This matches the semantic\\n      a flaky network/registry call has \u2014 caching an exception would\\n      pin the failure for the whole request.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport contextvars\\nimport json\\nfrom collections import OrderedDict\\nfrom typing import TYPE_CHECKING, Any, TypeVar\\n\\nif TYPE_CHECKING:\\n    from collections.abc import Callable\\n\\nMAX_CACHE_ENTRIES = 100\\n\\n# Per-request cache. Default None lazily allocates the OrderedDict on\\n# first access in the current context so child contexts get their own\\n# instance instead of inheriting a shared one.\\n_cache_var: contextvars.ContextVar[OrderedDict[str, Any] | None] = contextvars.ContextVar(\\n    \\\"lfx_tool_cache\\\", default=None\\n)\\n\\n\\nT = TypeVar(\\\"T\\\")\\n\\n\\ndef _get_cache() -> OrderedDict[str, Any]:\\n    cache = _cache_var.get()\\n    if cache is None:\\n        cache = OrderedDict()\\n        _cache_var.set(cache)\\n    return cache\\n\\n\\ndef _make_key(tool_name: str, args: dict[str, Any]) -> str:\\n    \\\"\\\"\\\"Build a deterministic cache key from a tool name + its args.\\n\\n    ``sort_keys=True`` makes the encoding insensitive to dict insertion\\n    order, so the same logical call hits the cache regardless of how the\\n    LLM happens to serialize its tool-call JSON. ``default=str`` keeps\\n    the encoding lossy-but-stable for any non-JSON arg (e.g. ``UUID``).\\n    \\\"\\\"\\\"\\n    try:\\n        encoded_args = json.dumps(args, sort_keys=True, default=str)\\n    except (TypeError, ValueError):\\n        # If args can't be serialized at all, skip the cache entirely by\\n        # returning a unique key (caller will treat as miss every time).\\n        encoded_args = repr(args)\\n    return f\\\"{tool_name}::{encoded_args}\\\"\\n\\n\\ndef cached_tool_call(\\n    tool_name: str,\\n    args: dict[str, Any],\\n    producer: Callable[[], T],\\n) -> T:\\n    \\\"\\\"\\\"Run ``producer`` once per ``(tool_name, args)`` within the current request.\\n\\n    On cache hit, returns the stored value WITHOUT invoking ``producer``.\\n    On cache miss, invokes ``producer``, stores its return value, and\\n    returns it. If ``producer`` raises, the exception propagates and\\n    nothing is cached.\\n\\n    The ``args`` dict serializes order-insensitively (``sort_keys``), so\\n    callers don't need to normalize keys before lookup.\\n    \\\"\\\"\\\"\\n    key = _make_key(tool_name, args)\\n    cache = _get_cache()\\n    if key in cache:\\n        # Mark as most-recently used.\\n        cache.move_to_end(key)\\n        return cache[key]\\n\\n    # Cache miss: produce, store on success, propagate on failure.\\n    value = producer()\\n    cache[key] = value\\n    cache.move_to_end(key)\\n    # LRU eviction: drop the oldest entry if we exceed the cap.\\n    while len(cache) > MAX_CACHE_ENTRIES:\\n        cache.popitem(last=False)\\n    return value\\n\\n\\ndef reset_tool_cache() -> None:\\n    \\\"\\\"\\\"Drop the cache for the current request.\\n\\n    Setting the ContextVar back to ``None`` (rather than an empty\\n    OrderedDict) ensures any child context spawned after this reset\\n    lazily allocates its OWN fresh cache instead of inheriting and\\n    mutating one shared object. This is the same isolation primitive\\n    ``reset_flow_events`` uses for the SSE event queue.\\n    \\\"\\\"\\\"\\n    _cache_var.set(None)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/memory/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"815a50a8def4d38344c184c1f949075f20217ba57b0c73ef33a1ea0efb576906\",\"content\":\"\\\"\\\"\\\"Memory management for lfx with dynamic dispatch.\\n\\nRoutes memory operations to either the full langflow implementation (when\\nlangflow is installed AND a real database service is registered) or the lfx\\nstub implementation (standalone / noop DB).\\n\\nDispatch is evaluated at call time, not import time, because the database\\nservice is typically registered *after* this module is first imported (e.g.,\\nfrom Component class definitions loaded before graph setup). An import-time\\ndecision can't distinguish \\\"langflow is importable\\\" from \\\"a real DB is wired\\\",\\nand picking the langflow backend with a NoopDatabaseService yields silent\\nno-op inserts followed by spurious \\\"Message with id X not found\\\" errors on\\nupdate.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import Any\\n\\nfrom lfx.utils.langflow_utils import has_langflow_db_backend\\n\\n\\ndef _impl():\\n    if has_langflow_db_backend():\\n        from langflow import memory as impl\\n    else:\\n        from lfx.memory import stubs as impl\\n    return impl\\n\\n\\ndef aadd_messages(*args: Any, **kwargs: Any):\\n    return _impl().aadd_messages(*args, **kwargs)\\n\\n\\ndef aadd_messagetables(*args: Any, **kwargs: Any):\\n    return _impl().aadd_messagetables(*args, **kwargs)\\n\\n\\ndef add_messages(*args: Any, **kwargs: Any):\\n    return _impl().add_messages(*args, **kwargs)\\n\\n\\ndef adelete_messages(*args: Any, **kwargs: Any):\\n    return _impl().adelete_messages(*args, **kwargs)\\n\\n\\ndef aget_messages(*args: Any, **kwargs: Any):\\n    return _impl().aget_messages(*args, **kwargs)\\n\\n\\ndef astore_message(*args: Any, **kwargs: Any):\\n    return _impl().astore_message(*args, **kwargs)\\n\\n\\ndef aupdate_messages(*args: Any, **kwargs: Any):\\n    return _impl().aupdate_messages(*args, **kwargs)\\n\\n\\ndef delete_message(*args: Any, **kwargs: Any):\\n    return _impl().delete_message(*args, **kwargs)\\n\\n\\ndef delete_messages(*args: Any, **kwargs: Any):\\n    return _impl().delete_messages(*args, **kwargs)\\n\\n\\ndef get_messages(*args: Any, **kwargs: Any):\\n    return _impl().get_messages(*args, **kwargs)\\n\\n\\ndef store_message(*args: Any, **kwargs: Any):\\n    return _impl().store_message(*args, **kwargs)\\n\\n\\n__all__ = [\\n    \\\"aadd_messages\\\",\\n    \\\"aadd_messagetables\\\",\\n    \\\"add_messages\\\",\\n    \\\"adelete_messages\\\",\\n    \\\"aget_messages\\\",\\n    \\\"astore_message\\\",\\n    \\\"aupdate_messages\\\",\\n    \\\"delete_message\\\",\\n    \\\"delete_messages\\\",\\n    \\\"get_messages\\\",\\n    \\\"store_message\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/memory/stubs.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"ceb7b81bd75bafe1043cdadc812c746004a5e09b039e4a3bc08113317103e085\",\"content\":\"\\\"\\\"\\\"Memory management functions for lfx package.\\n\\nThis module provides message storage and retrieval functionality adapted for lfx's\\nservice-based architecture. It mirrors the langflow.memory API but works with\\nlfx's Message model and service interfaces.\\n\\\"\\\"\\\"\\n\\nfrom uuid import UUID\\n\\nfrom lfx.log.logger import logger\\nfrom lfx.schema.message import Message\\nfrom lfx.services.deps import session_scope\\nfrom lfx.utils.async_helpers import run_until_complete\\n\\n\\nasync def astore_message(\\n    message: Message,\\n    flow_id: str | UUID | None = None,\\n    run_id: str | UUID | None = None,\\n    user_id: str | UUID | None = None,  # noqa: ARG001\\n) -> list[Message]:\\n    \\\"\\\"\\\"Store a message in the memory.\\n\\n    Args:\\n        message (Message): The message to store.\\n        flow_id (Optional[str | UUID]): The flow ID associated with the message.\\n            When running from the CustomComponent you can access this using `self.graph.flow_id`.\\n        run_id (Optional[str | UUID]): The graph/native run ID associated with the message.\\n        user_id (Optional[str | UUID]): The executing user's ID, stamped on the stored message.\\n\\n    Returns:\\n        List[Message]: A list containing the stored message.\\n\\n    Raises:\\n        ValueError: If any of the required parameters (session_id, sender, sender_name) is not provided.\\n    \\\"\\\"\\\"\\n    if not message:\\n        logger.warning(\\\"No message provided.\\\")\\n        return []\\n\\n    # Serving-plane ephemeral runs (anonymous end-user) must not persist chat\\n    # memory. Mirrors the identical gate in langflow.memory.astore_message so the\\n    # contract holds regardless of which memory implementation dispatch selects.\\n    from lfx.memory.flow_context import should_persist_messages\\n\\n    if not should_persist_messages():\\n        return [message]\\n\\n    if not message.session_id or not message.sender or not message.sender_name:\\n        msg = (\\n            f\\\"All of session_id, sender, and sender_name must be provided. Session ID: {message.session_id},\\\"\\n            f\\\" Sender: {message.sender}, Sender Name: {message.sender_name}\\\"\\n        )\\n        raise ValueError(msg)\\n\\n    # Set flow_id if provided. The stub is the fallback when no real database is\\n    # registered, so be tolerant of non-UUID flow_ids (e.g. synthetic IDs from tests\\n    # or callers that pass a string identifier). UUID parsing here only normalizes\\n    # format; an invalid string is preserved verbatim, but logged so downstream\\n    # UUID-expecting code paths have a breadcrumb if they later fail.\\n    if flow_id:\\n        if isinstance(flow_id, str):\\n            try:\\n                flow_id = UUID(flow_id)\\n            except ValueError:\\n                logger.warning(\\n                    f\\\"flow_id {flow_id!r} is not a valid UUID; preserving verbatim. \\\"\\n                    \\\"Downstream code that expects a UUID may surface a confusing error.\\\"\\n                )\\n        message.flow_id = str(flow_id)\\n    if run_id:\\n        if isinstance(run_id, UUID):\\n            run_id = str(run_id)\\n        message.run_id = str(run_id)\\n\\n    # In lfx, we use the service architecture - this is a simplified implementation\\n    # that doesn't persist to database but maintains the message in memory\\n    # Real implementation would require a database service\\n    async with session_scope() as session:\\n        # Since we're using NoopSession by default, this doesn't actually persist\\n        # but maintains the same interface as langflow.memory\\n        try:\\n            # Generate an ID if not present\\n            if not hasattr(message, \\\"id\\\") or not message.id:\\n                try:\\n                    import nanoid\\n\\n                    message.id = nanoid.generate()\\n                except ImportError:\\n                    # Fallback to uuid if nanoid is not available\\n                    import uuid\\n\\n                    message.id = str(uuid.uuid4())\\n\\n            await session.add(message)\\n            await session.commit()\\n            logger.debug(f\\\"Message stored with ID: {message.id}\\\")\\n        except Exception as e:\\n            logger.exception(f\\\"Error storing message: {e}\\\")\\n            await session.rollback()\\n            raise\\n        return [message]\\n\\n\\ndef store_message(\\n    message: Message,\\n    flow_id: str | UUID | None = None,\\n    run_id: str | UUID | None = None,\\n    user_id: str | UUID | None = None,  # noqa: ARG001\\n) -> list[Message]:\\n    \\\"\\\"\\\"DEPRECATED: Stores a message in the memory.\\n\\n    DEPRECATED: Use `astore_message` instead.\\n\\n    Args:\\n        message (Message): The message to store.\\n        flow_id (Optional[str | UUID]): The flow ID associated with the message.\\n            When running from the CustomComponent you can access this using `self.graph.flow_id`.\\n        run_id (Optional[str | UUID]): The graph/native run ID associated with the message.\\n        user_id (Optional[str | UUID]): The executing user's ID, stamped on the stored message.\\n\\n    Returns:\\n        List[Message]: A list containing the stored message.\\n\\n    Raises:\\n        ValueError: If any of the required parameters (session_id, sender, sender_name) is not provided.\\n    \\\"\\\"\\\"\\n    return run_until_complete(astore_message(message, flow_id=flow_id, run_id=run_id))\\n\\n\\nasync def aupdate_messages(messages: Message | list[Message]) -> list[Message]:\\n    \\\"\\\"\\\"Update stored messages.\\n\\n    Args:\\n        messages: Message or list of messages to update.\\n\\n    Returns:\\n        List[Message]: Updated messages.\\n\\n    Raises:\\n        ValueError: If message is not found for update.\\n    \\\"\\\"\\\"\\n    if not isinstance(messages, list):\\n        messages = [messages]\\n\\n    async with session_scope() as session:\\n        updated_messages: list[Message] = []\\n        for message in messages:\\n            try:\\n                # In a real implementation, this would update the database record\\n                # For now, we just validate the message has an ID and return it\\n                if not hasattr(message, \\\"id\\\") or not message.id:\\n                    error_message = f\\\"Message without ID cannot be updated: {message}\\\"\\n                    logger.warning(error_message)\\n                    raise ValueError(error_message)\\n\\n                # Convert flow_id to string if it's a UUID\\n                if message.flow_id and isinstance(message.flow_id, UUID):\\n                    message.flow_id = str(message.flow_id)\\n\\n                await session.add(message)\\n                await session.commit()\\n                await session.refresh(message)\\n                updated_messages.append(message)\\n                logger.debug(f\\\"Message updated: {message.id}\\\")\\n            except Exception as e:\\n                logger.exception(f\\\"Error updating message: {e}\\\")\\n                await session.rollback()\\n                msg = f\\\"Failed to update message: {e}\\\"\\n                logger.error(msg)\\n                raise ValueError(msg) from e\\n\\n        return updated_messages\\n\\n\\nasync def delete_message(id_: str) -> None:\\n    \\\"\\\"\\\"Delete a message from the memory.\\n\\n    Args:\\n        id_ (str): The ID of the message to delete.\\n    \\\"\\\"\\\"\\n    async with session_scope() as session:\\n        try:\\n            # In a real implementation, this would delete from database\\n            # For now, this is a no-op since we're using NoopSession\\n            await session.delete(id_)\\n            await session.commit()\\n            logger.debug(f\\\"Message deleted: {id_}\\\")\\n        except Exception as e:\\n            logger.exception(f\\\"Error deleting message: {e}\\\")\\n            raise\\n\\n\\nasync def aget_messages(\\n    sender: str | None = None,  # noqa: ARG001\\n    sender_name: str | None = None,  # noqa: ARG001\\n    session_id: str | UUID | None = None,  # noqa: ARG001\\n    context_id: str | UUID | None = None,  # noqa: ARG001\\n    order_by: str | None = \\\"timestamp\\\",  # noqa: ARG001\\n    order: str | None = \\\"DESC\\\",  # noqa: ARG001\\n    flow_id: UUID | None = None,  # noqa: ARG001\\n    limit: int | None = None,  # noqa: ARG001\\n    user_id: str | UUID | None = None,  # noqa: ARG001\\n) -> list[Message]:\\n    \\\"\\\"\\\"Retrieve messages based on the provided filters.\\n\\n    Args:\\n        sender (Optional[str]): The sender of the messages (e.g., \\\"Machine\\\" or \\\"User\\\")\\n        sender_name (Optional[str]): The name of the sender.\\n        session_id (Optional[str]): The session ID associated with the messages.\\n        context_id (Optional[str]): The context ID associated with the messages.\\n        order_by (Optional[str]): The field to order the messages by. Defaults to \\\"timestamp\\\".\\n        order (Optional[str]): The order in which to retrieve the messages. Defaults to \\\"DESC\\\".\\n        flow_id (Optional[UUID]): The flow ID associated with the messages.\\n        limit (Optional[int]): The maximum number of messages to retrieve.\\n        user_id (Optional[str | UUID]): When provided, scope retrieval to this owning user.\\n\\n    Returns:\\n        List[Message]: A list of Message objects representing the retrieved messages.\\n    \\\"\\\"\\\"\\n    async with session_scope() as session:\\n        try:\\n            # In a real implementation, this would query the database\\n            # For now, return empty list since we're using NoopSession\\n            result = await session.query()  # This returns [] from NoopSession\\n            logger.debug(f\\\"Retrieved {len(result)} messages\\\")\\n        except Exception as e:  # noqa: BLE001\\n            logger.exception(f\\\"Error retrieving messages: {e}\\\")\\n            return []\\n        return result\\n\\n\\ndef get_messages(\\n    sender: str | None = None,\\n    sender_name: str | None = None,\\n    session_id: str | UUID | None = None,\\n    context_id: str | UUID | None = None,\\n    order_by: str | None = \\\"timestamp\\\",\\n    order: str | None = \\\"DESC\\\",\\n    flow_id: UUID | None = None,\\n    limit: int | None = None,\\n    user_id: str | UUID | None = None,  # noqa: ARG001\\n) -> list[Message]:\\n    \\\"\\\"\\\"DEPRECATED - Retrieve messages based on the provided filters.\\n\\n    DEPRECATED: Use `aget_messages` instead.\\n    \\\"\\\"\\\"\\n    return run_until_complete(\\n        aget_messages(\\n            sender,\\n            sender_name,\\n            session_id,\\n            context_id,\\n            order_by,\\n            order,\\n            flow_id,\\n            limit,\\n        )\\n    )\\n\\n\\nasync def adelete_messages(session_id: str | None = None, context_id: str | None = None) -> None:\\n    \\\"\\\"\\\"Delete messages from the memory based on the provided session or context ID.\\n\\n    Args:\\n        session_id (str): The session ID associated with the messages to delete.\\n        context_id (str): The context ID associated with the messages to delete.\\n    \\\"\\\"\\\"\\n    if not session_id and not context_id:\\n        msg = \\\"Either session_id or context_id must be provided to delete messages.\\\"\\n        raise ValueError(msg)\\n\\n    async with session_scope() as session:\\n        try:\\n            # In a real implementation, this would delete from database\\n            # For now, this is a no-op since we're using NoopSession\\n            await session.delete(session_id or context_id)  # type: ignore  # noqa: PGH003\\n            await session.commit()\\n            logger.debug(f\\\"Messages deleted for session: {session_id or context_id}\\\")\\n        except Exception as e:\\n            logger.exception(f\\\"Error deleting messages: {e}\\\")\\n            raise\\n\\n\\ndef delete_messages(session_id: str | None = None, context_id: str | None = None) -> None:\\n    \\\"\\\"\\\"DEPRECATED - Delete messages based on the provided session ID.\\n\\n    DEPRECATED: Use `adelete_messages` instead.\\n    \\\"\\\"\\\"\\n    return run_until_complete(adelete_messages(session_id, context_id))\\n\\n\\nasync def aadd_messages(\\n    messages: Message | list[Message],\\n    flow_id: str | UUID | None = None,  # noqa: ARG001\\n    run_id: str | UUID | None = None,  # noqa: ARG001\\n    user_id: str | UUID | None = None,  # noqa: ARG001\\n) -> list[Message]:\\n    \\\"\\\"\\\"Add messages to the memory.\\n\\n    Args:\\n        messages: Message or list of messages to add.\\n        flow_id (Optional[str | UUID]): The flow ID associated with the messages.\\n        run_id (Optional[str | UUID]): The graph/native run ID associated with the messages.\\n        user_id (Optional[str | UUID]): The executing user's ID, stamped on the stored messages.\\n\\n    Returns:\\n        List[Message]: Added messages.\\n    \\\"\\\"\\\"\\n    if not isinstance(messages, list):\\n        messages = [messages]\\n\\n    result = []\\n    for message in messages:\\n        stored = await astore_message(message)\\n        result.extend(stored)\\n    return result\\n\\n\\ndef add_messages(messages: Message | list[Message]) -> list[Message]:\\n    \\\"\\\"\\\"Add messages to the memory (synchronous version).\\n\\n    Args:\\n        messages: Message or list of messages to add.\\n\\n    Returns:\\n        List[Message]: Added messages.\\n    \\\"\\\"\\\"\\n    return run_until_complete(aadd_messages(messages))\\n\\n\\nasync def aadd_messagetables(messages: Message | list[Message]) -> list[Message]:\\n    \\\"\\\"\\\"Add message tables to the memory.\\n\\n    This is an alias for aadd_messages for backwards compatibility.\\n\\n    Args:\\n        messages: Message or list of messages to add.\\n\\n    Returns:\\n        List[Message]: Added messages.\\n    \\\"\\\"\\\"\\n    return await aadd_messages(messages)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/observability.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"50402e5b5ecc43b19def7d7be79d76420831a867cd74b58a0d5458adebdb2b15\",\"content\":\"\\\"\\\"\\\"Application observability: install OTLP providers for the three signals from OTel env vars.\\n\\nApplication observability answers whether the service is healthy: request rates, latency,\\nerrors, and the units of work the service performed. It is a separate concern from the LLM\\ntracer integrations, which describe what a flow did and carry prompt and completion text.\\n\\nThe boundary between them is drawn per signal, all three deny by default on the way out. Spans go\\nthrough ``ApplicationOnlySpanProcessor`` and metrics through ``ApplicationOnlyMetricExporter``,\\nboth below, each allowlisting an instrumentation scope. Logs are filtered in ``lfx.log.logger``,\\nwhere a record is assembled, and on a declared opt-in rather than a scope name, because a log\\nrecord's scope is derived from the calling module and so is not something a call site can be\\ntrusted to have chosen.\\n\\nWorth knowing when reading the claim we make about this: the filter covers what this process\\nexports over OTLP, and nothing else. The console and the rotating log file still contain every\\nmessage in full, so shipping those to the same backend goes around it.\\n\\nThis lives in lfx, not langflow, because lfx is the runtime that actually serves flows in\\nproduction (``lfx serve`` / ``lfx run``). The graph emits the application span, ``lfx serve``\\nis the HTTP surface, and both need the providers installed to export anything. langflow's\\ntelemetry service is a thin caller of :func:`bootstrap_application_telemetry`; ``lfx serve``\\ncalls the same function, so the two runtimes report identically to any OTLP backend.\\n\\nOpenTelemetry is an optional dependency of lfx (``pip install \\\"lfx[otel]\\\"``). Everything here\\ndegrades to a no-op when it is absent, so bare lfx imports this module without cost.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport asyncio\\nimport builtins\\nimport contextlib\\nimport contextvars\\nimport importlib\\nimport os\\nimport time\\nfrom dataclasses import dataclass\\nfrom typing import TYPE_CHECKING, Any\\nfrom urllib.parse import urlsplit, urlunsplit\\n\\nfrom lfx.log.logger import logger, operator_logger, otel_log_bodies_exported\\n\\n# Opt into the stable HTTP semantic conventions here, at import, rather than beside the call\\n# that needs them.\\n#\\n# OpenTelemetry reads this once, when its instrumentation package first initialises, and\\n# caches it for the life of the process. Setting it inside instrument_fastapi_app looked\\n# early enough and is not: bootstrap_application_telemetry runs first on both runtimes, and\\n# its SystemMetricsInstrumentor loads that package, freezing the decision while the variable\\n# is still unset. The FastAPI metrics then arrive under the pre-stable names, which is a\\n# silent defect -- ingest is healthy, and an APM keying its HTTP dashboards off the stable\\n# names shows nothing.\\n#\\n# setdefault, so \\\"http/dup\\\" stays available to an operator mid-migration.\\nos.environ.setdefault(\\\"OTEL_SEMCONV_STABILITY_OPT_IN\\\", \\\"http\\\")\\nfrom lfx.observability_fastapi import patch_otel_fastapi_route_details\\n\\n_BASE_EXCEPTION_GROUP_TYPE = getattr(builtins, \\\"BaseExceptionGroup\\\", None)\\nif _BASE_EXCEPTION_GROUP_TYPE is None:\\n    # The backport is present with the supported Python 3.10 dependency set, but\\n    # observability must remain importable in a deliberately minimal bare-lfx install.\\n    with contextlib.suppress(ImportError):\\n        _BASE_EXCEPTION_GROUP_TYPE = importlib.import_module(\\\"exceptiongroup\\\").BaseExceptionGroup\\n\\nif TYPE_CHECKING:\\n    from collections.abc import Iterator\\n\\n    from fastapi import FastAPI\\n    from opentelemetry.sdk._logs import LoggerProvider\\n    from opentelemetry.sdk.metrics import MeterProvider\\n    from opentelemetry.sdk.trace import TracerProvider\\n    from opentelemetry.trace import Link, Span, SpanContext\\n\\n# The tracer name Langflow's own application spans are emitted under. Deliberately not\\n# \\\"langflow\\\": the LLM tracer integrations already take a tracer under that name, and their\\n# spans carry flow inputs and outputs. The export filter allowlists this exact string, so a\\n# span emitted under any other name never reaches the operator's APM.\\nAPPLICATION_TRACER_NAME = \\\"langflow.observability\\\"\\n\\n# The meter name the application records its own counters and histograms on. Kept as\\n# \\\"langflow\\\" because that is the scope langflow's custom metrics already use, and the metric\\n# filter must allowlist it. Under bare ``lfx serve`` the only thing recording here is the\\n# event-loop lag sampler below; langflow's own counters and gauges are additional.\\nAPPLICATION_METER_NAME = \\\"langflow\\\"\\n\\nDEFAULT_SERVICE_NAME = \\\"langflow\\\"\\n\\n# The surface a flow run arrived through, recorded as the flow span's ``protocol`` attribute so\\n# an operator can tell a playground click from a webhook delivery from an MCP tool call.\\n#\\n# Ambient rather than a parameter because the graph is several layers below the surface that\\n# knows the answer, and two of those layers hand the run to a fresh asyncio task. Task creation\\n# copies the context, so setting this at the entry point carries it into the run without\\n# threading an argument through every intermediate signature. It also means a path nobody wired\\n# reports no protocol at all rather than inheriting a wrong one from its caller.\\n_current_protocol: contextvars.ContextVar[str | None] = contextvars.ContextVar(\\n    \\\"lfx_execution_protocol\\\",\\n    default=None,\\n)\\n\\n\\n# The client a run says it came from, recorded as the span's ``client`` attribute. Distinct from\\n# ``protocol`` on purpose: protocol is how the request arrived and is derived server-side from the\\n# route, while this is who the caller claims to be. Conflating them is a mistake worth naming,\\n# because the playground calls the same public API any user would, so the route cannot identify it.\\n#\\n# Self-reported and therefore spoofable. That is fine for telemetry and must never become an\\n# authorization signal. The vocabulary is closed so a caller cannot mint attribute values at will;\\n# anything unrecognised is dropped rather than recorded, on the same principle as protocol, where a\\n# missing attribute is an honest \\\"nobody said\\\" and a guessed one is a lie.\\nKNOWN_EXECUTION_CLIENTS = frozenset({\\\"playground\\\", \\\"sdk\\\", \\\"cli\\\"})\\n\\n# Follows the X-LANGFLOW-* convention already used for request-scoped global variables.\\nEXECUTION_CLIENT_HEADER = \\\"x-langflow-client\\\"\\n\\n_current_client: contextvars.ContextVar[str | None] = contextvars.ContextVar(\\n    \\\"lfx_execution_client\\\",\\n    default=None,\\n)\\n\\n\\ndef get_execution_client() -> str | None:\\n    \\\"\\\"\\\"Return the client the current run says it came from, or None if it did not say.\\\"\\\"\\\"\\n    return _current_client.get()\\n\\n\\n@contextlib.contextmanager\\ndef execution_client(client: str | None) -> Iterator[None]:\\n    \\\"\\\"\\\"Bind *client* for the current context, ignoring anything outside the known vocabulary.\\\"\\\"\\\"\\n    if client not in KNOWN_EXECUTION_CLIENTS:\\n        yield\\n        return\\n    token = _current_client.set(client)\\n    try:\\n        yield\\n    finally:\\n        _current_client.reset(token)\\n\\n\\ndef get_execution_protocol() -> str | None:\\n    \\\"\\\"\\\"Return the surface the current flow run arrived through, or None outside a served run.\\\"\\\"\\\"\\n    return _current_protocol.get()\\n\\n\\n@contextlib.contextmanager\\ndef execution_protocol(protocol: str) -> Iterator[None]:\\n    \\\"\\\"\\\"Bind *protocol* as the surface for flow runs started in this context, outermost wins.\\n\\n    An already-bound protocol is left alone, because several surfaces share one driver\\n    underneath: voice and the playground both reach the graph through the same build path, and\\n    a flow-as-tool child run reaches it through whichever surface called the parent. In every\\n    such pair the outer binding is the one that names how the request actually arrived, so the\\n    inner generic driver must not overwrite it.\\n\\n    Reset on exit so a worker that serves many requests on one task cannot leak one request's\\n    protocol into the next. A run handed to ``asyncio.create_task`` inside the block keeps the\\n    value regardless, because the task copies the context at creation.\\n\\n    Entry points bind with this. The one exception is a callee that is itself an async\\n    generator: an async generator body runs in the context of whoever calls ``__anext__``, so a\\n    scope wrapped around it from outside would set and reset across its suspension points. Those\\n    take a plain ``protocol`` argument and bind it inside, on the coroutine that does the work\\n    (see ``_stream_event_frames``).\\n    \\\"\\\"\\\"\\n    if _current_protocol.get() is not None:\\n        yield\\n        return\\n    token = _current_protocol.set(protocol)\\n    try:\\n        yield\\n    finally:\\n        _current_protocol.reset(token)\\n\\n\\n# Event-loop scheduling delay. Sampled rather than instrumented: there is no hook that\\n# reports \\\"the loop was blocked\\\", so the only way to see it is to ask for a known sleep and\\n# measure how late the answer comes back.\\nEVENT_LOOP_LAG_METRIC = \\\"langflow_event_loop_lag_seconds\\\"\\nEVENT_LOOP_LAG_INTERVAL_SECONDS = 0.25\\n\\n# Explicit buckets, because the SDK default boundaries start (0, 5, 10, 25, ...) and are\\n# shaped for milliseconds. Recording seconds against them puts a healthy 0.2ms loop and a\\n# catastrophic 4s stall in the same bucket, which makes the histogram unable to answer the\\n# one question it exists for. These span \\\"healthy\\\" (sub-millisecond) to \\\"the loop is gone\\\".\\nEVENT_LOOP_LAG_BUCKETS_SECONDS = (0.001, 0.005, 0.01, 0.025, 0.05, 0.1, 0.25, 0.5, 1.0, 2.5, 5.0, 10.0)\\nSUPPORTED_OTLP_PROTOCOLS = (\\\"grpc\\\", \\\"http/protobuf\\\")\\n\\n# The endpoint vars that mean \\\"an operator wants to export\\\". Any one of these being set is the\\n# signal that observability was intended, used to turn an otel-not-installed situation from a\\n# silent no-op into a loud \\\"you meant to export, install the extra\\\" warning.\\n_OTLP_ENDPOINT_VARS = (\\n    \\\"OTEL_EXPORTER_OTLP_ENDPOINT\\\",\\n    \\\"OTEL_EXPORTER_OTLP_TRACES_ENDPOINT\\\",\\n    \\\"OTEL_EXPORTER_OTLP_METRICS_ENDPOINT\\\",\\n    \\\"OTEL_EXPORTER_OTLP_LOGS_ENDPOINT\\\",\\n)\\n\\n# Instrumentation scopes whose spans describe the service itself. This is an allowlist, not\\n# a denylist, because the LLM instrumentors ship inside the very same\\n# opentelemetry.instrumentation.* namespace as the application ones (openai, anthropic,\\n# langchain, bedrock, ... are all installed alongside fastapi and sqlalchemy). Their spans\\n# carry prompt and completion text, which must never reach the operator's APM, so anything\\n# not named here is dropped.\\n#\\n# The rule for adding to this list: only scopes the runtime instruments *right now*, against\\n# its own provider. A scope is NOT safe merely because it sounds like infrastructure, and it is\\n# NOT safe to list speculatively \\\"for when we instrument it\\\". The LLM vendor SDKs call bare\\n# Instrumentor().instrument() with no tracer_provider, which binds them to whatever global\\n# provider exists, i.e. ours. requests and urllib3 were on this list and had to be removed for\\n# exactly that reason: traceloop-sdk instruments both, so every outbound LLM API call produced\\n# a span here, carrying the request URL, and provider keys passed as query parameters travelled\\n# with it. httpx is the same trap and is the transport the openai and anthropic SDKs ride on,\\n# so it is deliberately absent until the runtime instruments it with an explicit\\n# tracer_provider=. sqlalchemy and redis are absent for the same reason: nothing here\\n# instruments them today, so listing them would only open a hole for a global instrumentor.\\n# Only asgi and fastapi (installed by instrument_fastapi_app) and APPLICATION_TRACER_NAME (the\\n# flow span) are emitted against our provider, so only they are listed. Re-add a scope the same\\n# commit that wires its instrumentor with tracer_provider=, never before.\\n# Named rather than inlined because two places need the same string: the allowlist below and\\n# the instrumentation call that produces the spans. An operator turning them off should get\\n# neither, and a literal repeated in both is one edit away from disagreeing.\\nDB_INSTRUMENTATION_SCOPE = \\\"opentelemetry.instrumentation.sqlalchemy\\\"\\n\\n# Values that turn a boolean env var off. Anything else leaves the default in place.\\n_FALSE_VALUES = frozenset({\\\"0\\\", \\\"f\\\", \\\"false\\\", \\\"n\\\", \\\"no\\\", \\\"off\\\"})\\n\\nAPPLICATION_INSTRUMENTATION_SCOPES = frozenset(\\n    {\\n        \\\"opentelemetry.instrumentation.asgi\\\",\\n        \\\"opentelemetry.instrumentation.fastapi\\\",\\n        # DB spans. Admitted after checking what they actually carry: db.statement keeps bound\\n        # parameters as placeholders (\\\"INSERT INTO messagetable (text) VALUES (?)\\\"), so chat\\n        # message text stays in the database and out of the APM. Verified by probe, because\\n        # \\\"it probably does not log values\\\" is how the httpx hole got opened the first time.\\n        #\\n        # The outbound HTTP scopes (httpx, requests, urllib3) remain deliberately absent. The\\n        # LLM vendor SDKs instrument them globally against whatever provider is global (ours),\\n        # so admitting them would put one span per outbound LLM call in the operator's APM.\\n        # Outbound provider health is delivered as leak-safe metrics instead.\\n        DB_INSTRUMENTATION_SCOPE,\\n        APPLICATION_TRACER_NAME,\\n    }\\n)\\n\\n\\ndef db_spans_enabled() -> bool:\\n    \\\"\\\"\\\"Whether database spans are exported. On by default.\\n\\n    They are the bulk of the span volume -- measured against a live run, roughly 80% of\\n    exported spans and about 50 spans per flow run, against one ``flow.execute`` -- and a\\n    commercial APM bills per span ingested. An operator who only wants flow and request\\n    health should not have to pay for the rest.\\n\\n    On by default anyway, because the volume buys something. In that same run 17% of pool\\n    checkouts took over 50ms and 4% took over 200ms, which is the difference between \\\"the\\n    flow was slow\\\" and \\\"the flow was slow waiting for the database\\\". Defaulting this off\\n    would hide the most common cause of a slow run behind a setting nobody knows to look for.\\n\\n    Anything other than a recognised false value keeps them on, so a typo cannot silently\\n    turn off telemetry the operator believes is running.\\n    \\\"\\\"\\\"\\n    return os.getenv(\\\"LANGFLOW_OTEL_DB_SPANS\\\", \\\"true\\\").strip().lower() not in _FALSE_VALUES\\n\\n\\ndef exported_span_scopes() -> frozenset[str]:\\n    \\\"\\\"\\\"The scopes this process actually exports, after operator configuration.\\n\\n    Only ever *subtracts* from ``APPLICATION_INSTRUMENTATION_SCOPES``. That direction is the\\n    whole safety property: the allowlist is what keeps prompt-carrying scopes out of the APM,\\n    so configuration must not be able to widen it. A setting that could add a scope would be\\n    an env var that reopens the leak the allowlist exists to close.\\n    \\\"\\\"\\\"\\n    if db_spans_enabled():\\n        return APPLICATION_INSTRUMENTATION_SCOPES\\n    return APPLICATION_INSTRUMENTATION_SCOPES - {DB_INSTRUMENTATION_SCOPE}\\n\\n\\n# The same boundary for metrics. Separate from the span set because the meter the runtime\\n# records its own counters and histograms on is named \\\"langflow\\\", while its application spans\\n# use APPLICATION_TRACER_NAME, and because the runtime metrics below have no span equivalent.\\nAPPLICATION_METRIC_SCOPES = APPLICATION_INSTRUMENTATION_SCOPES | {\\n    APPLICATION_METER_NAME,\\n    \\\"opentelemetry.instrumentation.system_metrics\\\",\\n}\\n\\n# Runtime health for this process, deliberately not for the host.\\n#\\n# The instrumentation's default set also covers system-wide CPU, memory, disk and network.\\n# Those describe the machine, not the service: under Kubernetes they report the node, which\\n# is misleading next to a per-pod request rate, and the disk and network families multiply\\n# by device. An operator already has node metrics from their infrastructure agent. What they\\n# cannot get anywhere else is what *this* interpreter is doing, so that is what is sent.\\n#\\n# GC is included because it is the Python-specific failure mode: a service that is slow while\\n# CPU looks fine is usually collecting, and without this the trace shows latency with no cause.\\nPROCESS_METRICS_CONFIG = {\\n    \\\"process.cpu.time\\\": [\\\"user\\\", \\\"system\\\"],\\n    \\\"process.cpu.utilization\\\": [\\\"user\\\", \\\"system\\\"],\\n    \\\"process.memory.usage\\\": None,\\n    \\\"process.memory.virtual\\\": None,\\n    \\\"process.thread.count\\\": None,\\n    \\\"process.open_file_descriptor.count\\\": None,\\n    \\\"process.context_switches\\\": [\\\"involuntary\\\", \\\"voluntary\\\"],\\n    \\\"cpython.gc.collections\\\": None,\\n    \\\"cpython.gc.collected_objects\\\": None,\\n    \\\"cpython.gc.uncollectable_objects\\\": None,\\n}\\n\\n\\n# Environment resolution shared with the doctor (``lfx observability doctor``). These are plain\\n# os.getenv and deliberately sit outside the otel-guarded block below, so the self-test can\\n# import them at module scope and resolve endpoints exactly the way the bootstrap does. Keeping\\n# one definition is the point: a doctor that resolved endpoints its own way could report a\\n# healthy pipeline the runtime never exports to.\\n\\n\\ndef otlp_endpoint(signal: str) -> str | None:\\n    \\\"\\\"\\\"Resolve a signal's endpoint: the per-signal variable first, then the generic one.\\\"\\\"\\\"\\n    return os.getenv(f\\\"OTEL_EXPORTER_OTLP_{signal.upper()}_ENDPOINT\\\") or os.getenv(\\\"OTEL_EXPORTER_OTLP_ENDPOINT\\\")\\n\\n\\ndef otlp_exporter_disabled(signal: str) -> bool:\\n    \\\"\\\"\\\"Whether the operator turned this signal off while leaving a shared endpoint set.\\\"\\\"\\\"\\n    return os.getenv(f\\\"OTEL_{signal.upper()}_EXPORTER\\\", \\\"otlp\\\").strip().lower() == \\\"none\\\"\\n\\n\\n# C0 controls plus DEL. None can appear in a URL, and urlsplit strips a subset of them silently.\\n_CONTROL_CHARACTERS = frozenset(chr(code) for code in [*range(0x20), 0x7F])\\n\\n\\ndef safe_endpoint(endpoint: str) -> str:\\n    \\\"\\\"\\\"An OTLP endpoint with its credentials removed, for printing.\\n\\n    The endpoint is operator-supplied and routinely carries a token, either as userinfo in the\\n    authority or as a query parameter; both are how vendors document their collectors. The\\n    startup line that reports the endpoint is now on the one log scope whose bodies are exported\\n    verbatim, so without this, closing the log body boundary would open a credential leak through\\n    the line announcing it.\\n\\n    Userinfo and query string go; scheme, host, port and path stay, because a wrong port is the\\n    thing this line exists to make visible. Unparseable input degrades to a fixed marker rather\\n    than raising, since this only ever runs to build a log message.\\n\\n    Control characters are rejected outright rather than parsed. ``urlsplit`` silently strips\\n    tab, carriage return and newline per WHATWG, which quietly rejoins whatever followed one of\\n    them into the path, so an endpoint with an embedded newline comes back as a single line with\\n    the injected text appended to the path, and that line is written verbatim to the one log\\n    scope that is exported. A URL cannot legally contain them, so their presence means this is\\n    not a URL.\\n    \\\"\\\"\\\"\\n    if _CONTROL_CHARACTERS.intersection(endpoint):\\n        return \\\"<unparseable endpoint>\\\"\\n    try:\\n        parts = urlsplit(endpoint)\\n        _ = parts.port  # Validates the authority; a bad port raises here rather than later.\\n    except ValueError:\\n        return \\\"<unparseable endpoint>\\\"\\n    # An endpoint with no authority is not an endpoint, and the failure mode is the one this\\n    # function exists to prevent: ``urlsplit`` treats ``https:sekrit`` as an opaque value and\\n    # parks the whole of it in ``path``, so a typo that drops the slashes would have printed the\\n    # secret verbatim on the one log scope that is exported. Same for a bare word with no scheme.\\n    if not parts.netloc:\\n        return \\\"<unparseable endpoint>\\\"\\n    netloc = parts.netloc.rsplit(\\\"@\\\", maxsplit=1)[-1]\\n    return urlunsplit((parts.scheme, netloc, parts.path, \\\"\\\", \\\"\\\"))\\n\\n\\ndef otlp_exporter_class(signal: str, protocol: str):\\n    \\\"\\\"\\\"The OTLP exporter class for a signal and protocol.\\n\\n    Returns the class rather than an instance because the callers differ: the bootstrap wants a\\n    default-constructed exporter reading the environment, while the doctor passes an explicit\\n    timeout. Spelled out once here so a signal/protocol pairing cannot be wrong in one place and\\n    right in another.\\n    \\\"\\\"\\\"\\n    if signal == \\\"traces\\\":\\n        if protocol == \\\"grpc\\\":\\n            from opentelemetry.exporter.otlp.proto.grpc.trace_exporter import OTLPSpanExporter as ExporterClass\\n        else:\\n            from opentelemetry.exporter.otlp.proto.http.trace_exporter import OTLPSpanExporter as ExporterClass\\n    elif signal == \\\"metrics\\\":\\n        if protocol == \\\"grpc\\\":\\n            from opentelemetry.exporter.otlp.proto.grpc.metric_exporter import OTLPMetricExporter as ExporterClass\\n        else:\\n            from opentelemetry.exporter.otlp.proto.http.metric_exporter import OTLPMetricExporter as ExporterClass\\n    elif protocol == \\\"grpc\\\":\\n        from opentelemetry.exporter.otlp.proto.grpc._log_exporter import OTLPLogExporter as ExporterClass\\n    else:\\n        from opentelemetry.exporter.otlp.proto.http._log_exporter import OTLPLogExporter as ExporterClass\\n    return ExporterClass\\n\\n\\n# OpenTelemetry is optional. Resolve the SDK surface once, so the bootstrap functions can be a\\n# simple availability check rather than a repeated import attempt. When it is absent, every\\n# public entry point below returns without doing anything.\\ntry:\\n    from opentelemetry import _logs, metrics, trace\\n    from opentelemetry.sdk._logs import LoggerProvider\\n    from opentelemetry.sdk._logs.export import BatchLogRecordProcessor\\n    from opentelemetry.sdk.metrics import MeterProvider\\n    from opentelemetry.sdk.metrics.export import (\\n        MetricExporter,\\n        MetricExportResult,\\n        MetricsData,\\n        PeriodicExportingMetricReader,\\n        ResourceMetrics,\\n    )\\n    from opentelemetry.sdk.resources import SERVICE_NAME, OTELResourceDetector, Resource\\n    from opentelemetry.sdk.trace import TracerProvider\\n    from opentelemetry.sdk.trace.export import BatchSpanProcessor\\n\\n    _OTEL_AVAILABLE = True\\nexcept ImportError:\\n    _OTEL_AVAILABLE = False\\n\\n\\nif _OTEL_AVAILABLE:\\n    # Distinct from None, which means \\\"no exported ancestor, promote to root\\\". This one means\\n    # the chain left what this process saw, so the honest answer is to change nothing.\\n    _UNKNOWN_ANCESTOR = object()\\n\\n    class ApplicationOnlySpanProcessor(BatchSpanProcessor):\\n        \\\"\\\"\\\"Exports only spans that describe the application, dropping everything else.\\n\\n        The runtime installs a global tracer provider, so any library that takes a tracer\\n        from it ends up exporting through this processor. That includes the LLM tracing\\n        integrations, whose spans carry prompts and completions. Filtering on the way out\\n        keeps the boundary in one place and costs the vendor integrations nothing.\\n\\n        Drops are logged once per scope at debug level; they are the expected case for LLM\\n        instrumentation, and logging every one would be noise.\\n\\n        A span whose parent is dropped is re-parented to its nearest exported ancestor, or\\n        promoted to a root when it has none, so the trace still renders as a tree.\\n\\n        This is knowable at the child's on_end even though the child ends before its parent,\\n        because the drop depends only on the instrumentation scope, which is fixed when the\\n        span starts. ``on_start`` fires for every span, dropped ones included, so recording\\n        scope and parentage there answers at the child's on_end what will happen to a parent\\n        that has not ended yet.\\n\\n        Only rewrites when the parent is known to be dropped. A parent that is absent from the\\n        map is left alone: that is a remote parent from another process, or one evicted by the\\n        cap below, and neither is an orphan this can fix. Rewriting on a guess would invent a\\n        relationship, which is worse than the gap.\\n\\n        Scrubbing attributes instead of dropping would also keep the tree intact, but the\\n        requirement is no component spans, not merely no content.\\n        \\\"\\\"\\\"\\n\\n        # Bounds the lineage map against spans that start and never end. Entries are removed\\n        # as spans end, so a healthy process sits far below this; hitting it means something\\n        # is leaking, and the cost of that is losing re-parenting, not memory.\\n        _MAX_TRACKED_SPANS = 10_000\\n\\n        def __init__(self, *args, **kwargs) -> None:\\n            super().__init__(*args, **kwargs)\\n            self._dropped_scopes: set[str] = set()\\n            # Resolved once, at construction, so the set cannot change under a running\\n            # process and leave two spans of the same scope treated differently.\\n            self._scopes = exported_span_scopes()\\n            # span_id -> (will be exported, parent span context, own span context). Written in\\n            # on_start, read when a child ends, removed when the span itself ends. Children\\n            # end before their parents, so a parent is still present when its child looks it\\n            # up. No lock: dict get and set are atomic here, and a lost race costs one\\n            # re-parenting, leaving the span exactly as it was exported before this existed.\\n            self._lineage: dict[int, tuple[bool, SpanContext | None, SpanContext]] = {}\\n            self._lineage_capped = False\\n            self._reparent_failed = False\\n\\n        def _reparent_safely(self, span) -> None:\\n            \\\"\\\"\\\"Re-parent, but never at the cost of the run.\\n\\n            ``span._parent`` reaches into the SDK's internals, and the SDK does not catch\\n            exceptions raised by a span processor: it lets them out of ``Span.end()`` and into\\n            whatever application code ended the span. So a future OpenTelemetry release that\\n            renames that attribute would not merely stop the trace rendering nicely, it would\\n            raise inside a flow run. Telemetry is not allowed to do that.\\n\\n            Logged once rather than per span, since the cause is process-wide when it happens\\n            at all, and the span is exported either way with the parent it already had.\\n            \\\"\\\"\\\"\\n            try:\\n                self._reparent_over_dropped_ancestors(span)\\n            except Exception:  # noqa: BLE001\\n                if not self._reparent_failed:\\n                    self._reparent_failed = True\\n                    logger.debug(\\n                        \\\"Could not re-parent a span over its dropped ancestors; \\\"\\n                        \\\"exporting it unchanged. This is a no-op for the run itself.\\\",\\n                        exc_info=True,\\n                    )\\n\\n        def on_start(self, span, parent_context=None) -> None:\\n            super().on_start(span, parent_context)\\n            if len(self._lineage) >= self._MAX_TRACKED_SPANS:\\n                if not self._lineage_capped:\\n                    self._lineage_capped = True\\n                    logger.debug(\\n                        f\\\"Tracking more than {self._MAX_TRACKED_SPANS} in-flight spans; \\\"\\n                        \\\"not re-parenting children of dropped spans beyond this point.\\\"\\n                    )\\n                return\\n            scope = span.instrumentation_scope.name if span.instrumentation_scope else \\\"\\\"\\n            context = span.get_span_context()\\n            self._lineage[context.span_id] = (scope in self._scopes, span.parent, context)\\n\\n        def _exported_ancestor(self, parent_id):\\n            \\\"\\\"\\\"The nearest ancestor that will be exported.\\n\\n            Returns its span context, or None when the chain reaches a root through dropped\\n            spans only, or ``_UNKNOWN_ANCESTOR`` when the chain leaves what this process\\n            recorded and the answer is genuinely not known.\\n            \\\"\\\"\\\"\\n            seen: set[int] = set()\\n            current = parent_id\\n            while current is not None:\\n                if current in seen:  # pragma: no cover - defensive, ids are unique\\n                    return _UNKNOWN_ANCESTOR\\n                seen.add(current)\\n                entry = self._lineage.get(current)\\n                if entry is None:\\n                    return _UNKNOWN_ANCESTOR\\n                exported, next_parent, context = entry\\n                if exported:\\n                    return context\\n                if next_parent is not None and next_parent.is_remote:\\n                    return next_parent\\n                current = next_parent.span_id if next_parent is not None else None\\n            return None\\n\\n        def _reparent_over_dropped_ancestors(self, span) -> None:\\n            parent = span.parent\\n            if parent is None:\\n                return\\n            entry = self._lineage.get(parent.span_id)\\n            if entry is None or entry[0]:\\n                # Unknown parent, or one that is being exported. Either way, leave it.\\n                return\\n            ancestor = self._exported_ancestor(parent.span_id)\\n            if ancestor is _UNKNOWN_ANCESTOR:\\n                return\\n            # Same trace either way, so this moves the span within its tree rather than\\n            # relocating it. None promotes it to a root, which is what it effectively is once\\n            # everything above it is dropped.\\n            span._parent = ancestor  # noqa: SLF001\\n\\n        def on_end(self, span) -> None:\\n            scope = span.instrumentation_scope.name if span.instrumentation_scope else \\\"\\\"\\n            try:\\n                if scope in self._scopes:\\n                    self._reparent_safely(span)\\n                    _redact_url_attributes(span)\\n                    _redact_db_path_attributes(span)\\n                    super().on_end(span)\\n                    return\\n                if scope not in self._dropped_scopes:\\n                    self._dropped_scopes.add(scope)\\n                    logger.debug(f\\\"Not exporting spans from {scope!r}; only application telemetry is sent to the APM.\\\")\\n            finally:\\n                # After the export, and after any child has had the chance to read it.\\n                self._lineage.pop(span.get_span_context().span_id, None)\\n\\n    class ApplicationOnlyMetricExporter(MetricExporter):\\n        \\\"\\\"\\\"Pushes only the service's own metrics, dropping every other instrumentation scope.\\n\\n        The metrics counterpart of ApplicationOnlySpanProcessor, and it exists for the same\\n        reason: the runtime installs a global meter provider, and the LLM instrumentors take\\n        their meters from it with a bare get_meter, so their gen_ai token and duration metrics\\n        would otherwise be pushed to the operator's APM alongside the service's own. Those\\n        belong to the LLM tracing integrations and their separate backends.\\n\\n        Only the push exporter is wrapped. The local Prometheus endpoint is the flow author's\\n        own process and keeps seeing everything.\\n        \\\"\\\"\\\"\\n\\n        def __init__(self, exporter: MetricExporter) -> None:\\n            # Read off the wrapped exporter rather than defaulted: the temporality preference\\n            # is how OTEL_EXPORTER_OTLP_METRICS_TEMPORALITY_PREFERENCE=delta reaches the\\n            # reader, and New Relic rejects cumulative. These are the same private attributes\\n            # PeriodicExportingMetricReader itself reads from an exporter.\\n            super().__init__(\\n                preferred_temporality=exporter._preferred_temporality,  # noqa: SLF001\\n                preferred_aggregation=exporter._preferred_aggregation,  # noqa: SLF001\\n            )\\n            self._exporter = exporter\\n            self._dropped_scopes: set[str] = set()\\n\\n        def _allowed(self, scope_name: str) -> bool:\\n            if scope_name in APPLICATION_METRIC_SCOPES:\\n                return True\\n            if scope_name not in self._dropped_scopes:\\n                self._dropped_scopes.add(scope_name)\\n                logger.debug(\\n                    f\\\"Not exporting metrics from {scope_name!r}; only application telemetry is sent to the APM.\\\"\\n                )\\n            return False\\n\\n        def export(self, metrics_data: MetricsData, timeout_millis: float = 10_000, **kwargs) -> MetricExportResult:\\n            resource_metrics = []\\n            for rm in metrics_data.resource_metrics:\\n                scope_metrics = [sm for sm in rm.scope_metrics if self._allowed(sm.scope.name if sm.scope else \\\"\\\")]\\n                if scope_metrics:\\n                    resource_metrics.append(\\n                        ResourceMetrics(resource=rm.resource, scope_metrics=scope_metrics, schema_url=rm.schema_url)\\n                    )\\n            # Nothing survived the filter; an empty export is a wasted round trip, not a failure.\\n            if not resource_metrics:\\n                return MetricExportResult.SUCCESS\\n            return self._exporter.export(MetricsData(resource_metrics=resource_metrics), timeout_millis, **kwargs)\\n\\n        def force_flush(self, timeout_millis: float = 10_000) -> bool:\\n            return self._exporter.force_flush(timeout_millis)\\n\\n        def shutdown(self, timeout_millis: float = 30_000, **kwargs) -> None:\\n            self._exporter.shutdown(timeout_millis, **kwargs)\\n\\n    def _resource() -> Resource:\\n        \\\"\\\"\\\"Build the resource, letting OTEL_SERVICE_NAME and OTEL_RESOURCE_ATTRIBUTES win.\\n\\n        Resource.create() gives explicit attributes precedence over both env vars, so passing\\n        service.name unconditionally would make them unsettable. Ask the SDK's own detector\\n        whether the environment supplied one, and only fall back to our default when it did\\n        not. Parsing the env ourselves gets keys that merely end in service.name\\n        (k8s.service.name=...) and values with spaces around the = wrong.\\n        \\\"\\\"\\\"\\n        if OTELResourceDetector().detect().attributes.get(SERVICE_NAME):\\n            return Resource.create()\\n        return Resource.create({SERVICE_NAME: DEFAULT_SERVICE_NAME})\\n\\n    def _otlp_protocol(signal: str) -> str:\\n        \\\"\\\"\\\"Resolve the OTLP protocol, per-signal variable first, then the generic one.\\n\\n        The SDK's own auto-configuration strips whitespace and rejects unknown values; match\\n        that leniency so a stray space does not silently route gRPC traffic at an HTTP exporter.\\n        \\\"\\\"\\\"\\n        protocol = (\\n            os.getenv(f\\\"OTEL_EXPORTER_OTLP_{signal.upper()}_PROTOCOL\\\")\\n            or os.getenv(\\\"OTEL_EXPORTER_OTLP_PROTOCOL\\\")\\n            or \\\"http/protobuf\\\"\\n        ).strip()\\n        if protocol not in SUPPORTED_OTLP_PROTOCOLS:\\n            logger.warning(\\n                f\\\"Unsupported OTLP protocol {protocol!r}; falling back to http/protobuf. \\\"\\n                f\\\"Supported values: {', '.join(SUPPORTED_OTLP_PROTOCOLS)}.\\\"\\n            )\\n            return \\\"http/protobuf\\\"\\n        return protocol\\n\\n    def _prometheus_reader():\\n        \\\"\\\"\\\"Build the local Prometheus pull reader, or None when the exporter is not installed.\\n\\n        Prometheus is optional even within ``lfx[otel]``: a standalone ``lfx serve`` may push\\n        over OTLP and never expose a scrape endpoint. langflow ships the exporter and enables\\n        it through its own setting.\\n        \\\"\\\"\\\"\\n        try:\\n            from opentelemetry.exporter.prometheus import PrometheusMetricReader\\n        except ImportError:\\n            logger.warning(\\\"Prometheus metrics requested but opentelemetry-exporter-prometheus is not installed.\\\")\\n            return None\\n        return PrometheusMetricReader()\\n\\n    def _otlp_metric_reader() -> PeriodicExportingMetricReader | None:\\n        \\\"\\\"\\\"Build the OTLP push reader when the standard OTel env vars opt in.\\n\\n        The exporter and the reader take no arguments on purpose: endpoint, headers, timeout,\\n        compression, export interval and OTEL_EXPORTER_OTLP_METRICS_TEMPORALITY_PREFERENCE\\n        (New Relic requires delta) all come from the environment, and passing any of them here\\n        would make the corresponding variable unsettable.\\n\\n        The final flush on exit needs no wiring: MeterProvider registers its own atexit handler\\n        (shutdown_on_exit defaults to True), which shuts the reader down and drains it.\\n        \\\"\\\"\\\"\\n        endpoint = otlp_endpoint(\\\"metrics\\\")\\n        if not endpoint:\\n            return None\\n\\n        # The operator's documented way to turn metrics off while leaving a shared endpoint set.\\n        if otlp_exporter_disabled(\\\"metrics\\\"):\\n            return None\\n\\n        protocol = _otlp_protocol(\\\"metrics\\\")\\n        try:\\n            exporter = otlp_exporter_class(\\\"metrics\\\", protocol)()\\n            reader = PeriodicExportingMetricReader(ApplicationOnlyMetricExporter(exporter))\\n        except Exception:  # noqa: BLE001\\n            logger.warning(\\\"Could not configure the OTLP metric exporter; metrics will not be pushed.\\\")\\n            return None\\n\\n        # Without this, a protocol/port mismatch is indistinguishable from never having booted.\\n        operator_logger().info(f\\\"OTLP metric export enabled (protocol={protocol}, endpoint={safe_endpoint(endpoint)}).\\\")\\n        return reader\\n\\n    def _install_meter_provider(*, prometheus_enabled: bool) -> tuple[MeterProvider | None, bool]:\\n        \\\"\\\"\\\"Install (or reuse) the meter provider carrying the Prometheus and OTLP readers.\\n\\n        Returns ``(provider, owned)``. ``owned`` is True only when this call constructed the\\n        provider, so the shutdown path never tears down a provider that belongs to someone else.\\n        \\\"\\\"\\\"\\n        existing_provider = metrics.get_meter_provider()\\n        # Reuse a concrete SDK provider installed by another integration. The default API proxy\\n        # also returns meters, but it has no readers and must be replaced so the readers below\\n        # can collect. Adopted, not owned: it is not ours to shut down.\\n        if isinstance(existing_provider, MeterProvider):\\n            return existing_provider, False\\n\\n        metric_readers = []\\n        if prometheus_enabled:\\n            reader = _prometheus_reader()\\n            if reader is not None:\\n                metric_readers.append(reader)\\n        # Prometheus is a pull endpoint, so it cannot cover a process that exits between\\n        # scrapes. Both readers sit on the one provider.\\n        otlp_reader = _otlp_metric_reader()\\n        if otlp_reader is not None:\\n            metric_readers.append(otlp_reader)\\n\\n        if not metric_readers:\\n            # Nothing to scrape or export. Installing a reader-less provider would still replace\\n            # the API proxy globally (set_meter_provider is first-write-wins), silently blocking a\\n            # provider a later integration or the embedding app installs, while never emitting\\n            # anything. The traces and logs paths decline the same way when nothing is configured.\\n            return None, False\\n\\n        provider = MeterProvider(resource=_resource(), metric_readers=metric_readers)\\n        metrics.set_meter_provider(provider)\\n        return provider, True\\n\\n    def _instrument_process_metrics(meter_provider: MeterProvider) -> None:\\n        \\\"\\\"\\\"Report this process's CPU, memory, threads, file descriptors and GC.\\n\\n        Bound to our meter provider explicitly rather than the global one, so these land on\\n        the same readers as everything else even if another integration installs a provider\\n        later. Failure is non-fatal: missing runtime metrics degrade the dashboard, they do\\n        not justify refusing to boot.\\n        \\\"\\\"\\\"\\n        try:\\n            from opentelemetry.instrumentation.system_metrics import SystemMetricsInstrumentor\\n\\n            instrumentor = SystemMetricsInstrumentor(config=PROCESS_METRICS_CONFIG)\\n            # The instrumentor is a singleton and raises if instrumented twice, which happens\\n            # in-process across app restarts and in tests.\\n            if not instrumentor.is_instrumented_by_opentelemetry:\\n                instrumentor.instrument(meter_provider=meter_provider)\\n        except Exception as exc:  # noqa: BLE001\\n            logger.warning(f\\\"Could not start process metrics; runtime health will be missing. {exc}\\\")\\n\\n    def _configure_tracer_provider_from_environment() -> TracerProvider | None:\\n        \\\"\\\"\\\"Install an OTLP tracer provider when the standard OTel env vars opt in.\\n\\n        Nothing sets a tracer provider otherwise, so spans go nowhere. If application code\\n        or opentelemetry-instrument already installed one, leave it alone.\\n        \\\"\\\"\\\"\\n        endpoint = otlp_endpoint(\\\"traces\\\")\\n        if not endpoint:\\n            return None\\n\\n        # The operator's documented way to turn traces off while leaving a shared endpoint set.\\n        if otlp_exporter_disabled(\\\"traces\\\"):\\n            return None\\n\\n        if trace.get_tracer_provider().__class__.__name__ != \\\"ProxyTracerProvider\\\":\\n            # Someone else owns tracing (opentelemetry-instrument, the OTel operator, or app\\n            # code). Installing over it would break them, but it also means our export filter\\n            # is not in the path, so nothing stops the LLM tracer integrations from sending\\n            # prompt content to that provider's exporter. Say so rather than implying a\\n            # boundary we are not enforcing.\\n            logger.warning(\\n                \\\"A tracer provider is already installed, so OTLP export is not being configured. \\\"\\n                \\\"LLM tracing integrations may export prompt and completion content through it.\\\"\\n            )\\n            return None\\n\\n        protocol = _otlp_protocol(\\\"traces\\\")\\n        try:\\n            tracer_provider = TracerProvider(resource=_resource())\\n            exporter = otlp_exporter_class(\\\"traces\\\", protocol)()\\n            tracer_provider.add_span_processor(ApplicationOnlySpanProcessor(exporter))\\n        except Exception:  # noqa: BLE001\\n            logger.warning(\\\"Could not configure the OTLP tracer provider; traces will not be exported.\\\")\\n            return None\\n\\n        trace.set_tracer_provider(tracer_provider)\\n        # Without this, a protocol/port mismatch is indistinguishable from never having booted.\\n        operator_logger().info(f\\\"OTLP trace export enabled (protocol={protocol}, endpoint={safe_endpoint(endpoint)}).\\\")\\n        return tracer_provider\\n\\n    def _configure_logger_provider_from_environment() -> LoggerProvider | None:\\n        \\\"\\\"\\\"Install an OTLP logger provider when the standard OTel env vars opt in.\\n\\n        This is the third signal, and the one that makes a trace actionable: the operator\\n        pivots from a failed request to the log lines emitted inside it. Correlation is\\n        automatic because the SDK stamps the active span's trace_id onto every record, and\\n        each flow execution already runs inside a span.\\n        \\\"\\\"\\\"\\n        endpoint = otlp_endpoint(\\\"logs\\\")\\n        if not endpoint:\\n            return None\\n        if otlp_exporter_disabled(\\\"logs\\\"):\\n            return None\\n        if isinstance(_logs.get_logger_provider(), LoggerProvider):\\n            logger.warning(\\\"A logger provider is already installed; not replacing it.\\\")\\n            return None\\n\\n        protocol = _otlp_protocol(\\\"logs\\\")\\n        try:\\n            provider = LoggerProvider(resource=_resource())\\n            exporter = otlp_exporter_class(\\\"logs\\\", protocol)()\\n            provider.add_log_record_processor(BatchLogRecordProcessor(exporter))\\n        except Exception as exc:  # noqa: BLE001\\n            logger.warning(f\\\"Could not configure the OTLP log exporter; logs will not be shipped. {exc}\\\")\\n            return None\\n\\n        _logs.set_logger_provider(provider)\\n        _announce_log_export(protocol, endpoint)\\n        return provider\\n\\n    def _announce_log_export(protocol: str, endpoint: str) -> None:\\n        \\\"\\\"\\\"State the log boundary in the operator's own log stream, at boot.\\n\\n        Documentation does not reach the person writing the Helm values, and this is the signal\\n        with the residual exposure worth knowing about: the body filter covers what Langflow\\n        exports over OTLP, and nothing else. Container stdout and the rotating log file still\\n        carry every message in full, so a sidecar log shipper reaches the same backend by a route\\n        this process never sees. That is a deployment choice, and it is only a deliberate one if\\n        the operator has been told.\\n\\n        WARNING rather than INFO when the logs endpoint was inherited from the shared\\n        ``OTEL_EXPORTER_OTLP_ENDPOINT``, because then shipping logs was a side effect of\\n        configuring traces rather than a decision. Setting the per-signal variable says the\\n        operator meant it, and earns the quieter level.\\n        \\\"\\\"\\\"\\n        inherited = not os.getenv(\\\"OTEL_EXPORTER_OTLP_LOGS_ENDPOINT\\\")\\n        bodies_exported = otel_log_bodies_exported()\\n        boundary = (\\n            \\\"Message bodies ARE exported (LANGFLOW_OTEL_LOG_BODIES=all); they carry model \\\"\\n            \\\"completions, chat history and provider error text.\\\"\\n            if bodies_exported\\n            else \\\"Message bodies are withheld unless a call site opts in; records keep severity, \\\"\\n            \\\"scope, callsite, error.type and trace correlation.\\\"\\n        )\\n        message = (\\n            f\\\"OTLP log export enabled (protocol={protocol}, endpoint={safe_endpoint(endpoint)}). \\\"\\n            f\\\"{boundary} This filter covers OTLP only: container stdout and the local log file \\\"\\n            f\\\"still contain full messages, so shipping those to the same backend bypasses it. \\\"\\n            f\\\"Set OTEL_LOGS_EXPORTER=none to export traces and metrics without logs.\\\"\\n        )\\n        if inherited:\\n            operator_logger().warning(\\n                f\\\"{message} Logs were enabled by the shared OTEL_EXPORTER_OTLP_ENDPOINT; set \\\"\\n                f\\\"OTEL_EXPORTER_OTLP_LOGS_ENDPOINT to make that explicit.\\\"\\n            )\\n        else:\\n            operator_logger().info(message)\\n\\n\\n@dataclass\\nclass ApplicationTelemetry:\\n    \\\"\\\"\\\"The providers a call to :func:`bootstrap_application_telemetry` installed.\\n\\n    Each is None when the corresponding signal was not configured (no endpoint, disabled, or\\n    OpenTelemetry not installed). Callers that own the process lifetime should keep the handles\\n    and call :meth:`shutdown` on exit: the atexit flush the SDK registers does not run under\\n    uvicorn or gunicorn (both die by signal), so without an explicit shutdown the last buffered\\n    batch of spans, metrics and logs is dropped on every restart and pod eviction.\\n    \\\"\\\"\\\"\\n\\n    meter_provider: MeterProvider | None = None\\n    tracer_provider: TracerProvider | None = None\\n    logger_provider: LoggerProvider | None = None\\n    # True only when the bootstrap constructed the meter provider. A provider adopted from\\n    # another integration is theirs to shut down. The tracer and logger providers need no such\\n    # flag: their paths decline to install over an existing provider and return None, so a\\n    # non-None handle here is always one we installed.\\n    owns_meter_provider: bool = False\\n\\n    def shutdown(self) -> None:\\n        \\\"\\\"\\\"Flush and shut down the providers this bootstrap installed. A no-op when none were.\\n\\n        Meter first: only ``MeterProvider.shutdown`` unregisters its atexit flush, and skipping\\n        it lets the interpreter shut the readers down a second time (Prometheus raises on the\\n        double unregister). The meter provider is shut down only when we own it, so an adopted\\n        provider's pipeline (which may outlive this process in an embedded host) is left intact.\\n        \\\"\\\"\\\"\\n        if self.meter_provider is not None and self.owns_meter_provider:\\n            self.meter_provider.shutdown()\\n        if self.tracer_provider is not None:\\n            self.tracer_provider.shutdown()\\n        if self.logger_provider is not None:\\n            self.logger_provider.shutdown()\\n\\n\\n# URL attributes an HTTP instrumentor may set. Every one of them can carry a full URL, and a\\n# full URL can carry a credential: providers put API keys in the query string (Gemini's\\n# ?key=, several others), and a URL may also carry userinfo before the host.\\n_URL_SPAN_ATTRIBUTES = (\\\"http.url\\\", \\\"url.full\\\", \\\"http.target\\\", \\\"url.query\\\")\\n\\n\\ndef _redact_url_attributes(span) -> None:\\n    \\\"\\\"\\\"Strip query strings and userinfo from a span's URL attributes, in place.\\n\\n    A live leak, not a hypothetical, and on a scope that is already allowlisted: the FastAPI\\n    server span records ``url.query`` verbatim, and ``lfx serve`` accepts its API key as a\\n    query parameter (``APIKeyQuery``). A probe against the real instrumented app exports\\n    ``url.query = \\\"x-api-key=<the key>\\\"``, so any deployment whose callers pass the key that\\n    way has been sending it to the operator's APM.\\n\\n    Done at the export boundary rather than through an instrumentor hook because this is the\\n    same place that already decides what leaves: one chokepoint, and it covers instrumentors\\n    the runtime does not install itself.\\n\\n    Scheme, host, port, path and every non-URL attribute survive, so \\\"POST api.openai.com\\n    /v1/chat/completions took 3s\\\" still reads exactly as an operator needs it to.\\n    \\\"\\\"\\\"\\n    attributes = span.attributes\\n    if not attributes or not any(key in attributes for key in _URL_SPAN_ATTRIBUTES):\\n        return\\n\\n    original_attributes = span._attributes  # noqa: SLF001\\n    redacted = dict(attributes)\\n\\n    for key in _URL_SPAN_ATTRIBUTES:\\n        if key not in attributes:\\n            continue\\n        if key == \\\"url.query\\\":\\n            # The whole point of this attribute is the query string, so there is nothing to keep.\\n            redacted[key] = \\\"\\\"\\n        else:\\n            value = attributes[key]\\n            if not isinstance(value, str) or (\\n                original_attributes.max_value_len is not None and len(value) >= original_attributes.max_value_len\\n            ):\\n                # A sequence is not a valid semantic URL value. A value at the SDK's length cap\\n                # may have lost its query or userinfo delimiter, so neither can be redacted safely.\\n                redacted[key] = \\\"\\\"\\n                continue\\n            try:\\n                parts = urlsplit(value)\\n                # Accessing port validates the authority. Keep using the raw netloc below so\\n                # bracketed IPv6 and port zero retain their exact valid representation.\\n                _ = parts.port\\n            except ValueError:\\n                # Telemetry must never break request handling. A malformed authority is not useful\\n                # operational data, so fail closed rather than exporting it or raising from Span.end().\\n                redacted[key] = \\\"\\\"\\n            else:\\n                # Strip userinfo from the raw authority instead of rebuilding it from hostname/port:\\n                # the raw form preserves IPv6 brackets and port zero.\\n                netloc = parts.netloc.rsplit(\\\"@\\\", maxsplit=1)[-1]\\n                missing_authority = not netloc and (\\n                    key in (\\\"http.url\\\", \\\"url.full\\\") or parts.scheme.lower() in (\\\"http\\\", \\\"https\\\", \\\"ws\\\", \\\"wss\\\")\\n                )\\n                if missing_authority:\\n                    # Absolute URL attributes and hierarchical HTTP-style values require an\\n                    # authority. Otherwise credential-looking bytes may be hiding in the path.\\n                    redacted[key] = \\\"\\\"\\n                else:\\n                    redacted[key] = urlunsplit((parts.scheme, netloc, parts.path, \\\"\\\", \\\"\\\"))\\n\\n    # Imported here, not at module scope: opentelemetry is an optional lfx extra and this\\n    # module must stay importable without it.\\n    from opentelemetry.attributes import BoundedAttributes\\n\\n    # Span.end() freezes the SDK's BoundedAttributes before processors run, and ReadableSpan\\n    # exposes no public setter. Rebuild the immutable mapping with its original limits and\\n    # carry the prior drop count forward so exporters receive the same span metadata.\\n    redacted_attributes = BoundedAttributes(\\n        maxlen=original_attributes.maxlen,\\n        attributes=redacted,\\n        max_value_len=original_attributes.max_value_len,\\n    )\\n    redacted_attributes.dropped = original_attributes.dropped\\n    span._attributes = redacted_attributes  # noqa: SLF001\\n\\n\\n# Attributes a database instrumentor derives from the database name. For SQLite the \\\"name\\\" is\\n# the file path, so each of these carries it: db.operation is built as \\\"<operation> <db.name>\\\",\\n# and the span name is that same string.\\n_DB_NAME_DERIVED_ATTRIBUTES = (\\\"db.name\\\", \\\"db.operation\\\")\\n\\n\\ndef _shorten_db_path(value: str) -> str:\\n    \\\"\\\"\\\"Return the final path segment, or the value unchanged when it is not a path.\\n\\n    Split on both separators rather than using os.path, because the exporting host and the host\\n    that wrote the path are not necessarily the same platform: a Windows deployment's backslash\\n    path must still be shortened when this runs anywhere else.\\n    \\\"\\\"\\\"\\n    return value.replace(\\\"\\\\\\\\\\\", \\\"/\\\").rsplit(\\\"/\\\", maxsplit=1)[-1]\\n\\n\\ndef _redact_db_path_attributes(span) -> None:\\n    \\\"\\\"\\\"Replace a SQLite database file path with its file name, in place.\\n\\n    SQLAlchemy's instrumentation sets ``db.name`` from the database name, and for SQLite that\\n    name is the file path. It then builds ``db.operation`` and the span name as\\n    ``\\\"<operation> <db.name>\\\"``, so a span arrives at the APM named\\n    ``SELECT /home/alice/langflow/langflow.db``. Confirmed present in a commercial APM, not only\\n    locally, so it survives export to a third party.\\n\\n    SQLite is the default database, so this is the default configuration rather than an edge\\n    case. The path is not a credential, but it is host detail the operator did not choose to\\n    send: install directory, the account name on a typical unix path, and whatever their\\n    directory naming gives away.\\n\\n    It is also a cardinality problem. Every deployment path is a distinct span name, so\\n    dashboards written against one environment do not port to another.\\n\\n    The file name is kept rather than dropping the value, because an operator running more than\\n    one SQLite database still needs to tell them apart.\\n\\n    Only SQLite spans are touched, and the gate is ``db.system`` rather than \\\"does this value\\n    look like a path\\\". A separator is legal inside a Postgres or MySQL database name, so a\\n    shape-based test would silently rename a logical database in the operator's dashboards.\\n    \\\"\\\"\\\"\\n    attributes = span.attributes\\n    if not attributes or attributes.get(\\\"db.system\\\") != \\\"sqlite\\\":\\n        # Gated on the system rather than on \\\"does this look like a path\\\", because a\\n        # separator is legal inside a Postgres or MySQL database name. Shortening one of\\n        # those would silently rename a logical database in the operator's dashboards.\\n        return\\n\\n    db_name = attributes.get(\\\"db.name\\\")\\n    if not isinstance(db_name, str):\\n        return\\n    shortened = _shorten_db_path(db_name)\\n    if shortened == db_name:\\n        # An in-memory database, or a bare file name that is already its final segment.\\n        return\\n\\n    updated = dict(attributes)\\n    for key in _DB_NAME_DERIVED_ATTRIBUTES:\\n        value = attributes.get(key)\\n        if isinstance(value, str):\\n            updated[key] = value.replace(db_name, shortened)\\n\\n    from opentelemetry.attributes import BoundedAttributes\\n\\n    original_attributes = span._attributes  # noqa: SLF001\\n    shortened_attributes = BoundedAttributes(\\n        maxlen=original_attributes.maxlen,\\n        attributes=updated,\\n        max_value_len=original_attributes.max_value_len,\\n    )\\n    shortened_attributes.dropped = original_attributes.dropped\\n    span._attributes = shortened_attributes  # noqa: SLF001\\n\\n    # The span name is the other carrier, and the one an operator actually reads. ReadableSpan\\n    # exposes name as a read-only property over this attribute, the same shape as _attributes.\\n    if isinstance(span.name, str) and db_name in span.name:\\n        span._name = span.name.replace(db_name, shortened)  # noqa: SLF001\\n\\n\\ndef bootstrap_application_telemetry(*, prometheus_enabled: bool = False) -> ApplicationTelemetry:\\n    \\\"\\\"\\\"Install OTLP providers for traces, metrics and logs from the standard OTel env vars.\\n\\n    This is the single entry point both runtimes call: langflow's telemetry service and\\n    ``lfx serve``. It is a no-op returning empty handles when OpenTelemetry is not installed,\\n    and reuses an already-installed provider rather than replacing it, so calling it once per\\n    process is safe.\\n\\n    ``prometheus_enabled`` adds the local Prometheus pull reader alongside the OTLP push\\n    reader. It defaults off: a standalone ``lfx serve`` typically pushes over OTLP and exposes\\n    no scrape endpoint, while langflow passes its own setting through.\\n    \\\"\\\"\\\"\\n    if not _OTEL_AVAILABLE:\\n        # Silence here is a real DX trap: an operator sets the endpoint, restarts, sees nothing\\n        # in their APM, and has no way to know the reason is a missing dependency rather than a\\n        # wrong endpoint. Only warn when they clearly intended to export.\\n        if any(os.getenv(var) for var in _OTLP_ENDPOINT_VARS):\\n            logger.warning(\\n                \\\"An OTLP endpoint is configured but OpenTelemetry is not installed, so no \\\"\\n                \\\"telemetry will be exported. Install it with: pip install 'lfx[otel]' (the full \\\"\\n                \\\"langflow distribution already includes it).\\\"\\n            )\\n        return ApplicationTelemetry()\\n\\n    meter_provider, owns_meter_provider = _install_meter_provider(prometheus_enabled=prometheus_enabled)\\n    if meter_provider is not None:\\n        _instrument_process_metrics(meter_provider)\\n    tracer_provider = _configure_tracer_provider_from_environment()\\n    logger_provider = _configure_logger_provider_from_environment()\\n    return ApplicationTelemetry(\\n        meter_provider=meter_provider,\\n        owns_meter_provider=owns_meter_provider,\\n        tracer_provider=tracer_provider,\\n        logger_provider=logger_provider,\\n    )\\n\\n\\ndef instrument_database(engine: object) -> None:\\n    \\\"\\\"\\\"Instrument a SQLAlchemy engine, so a slow request can be attributed to its queries.\\n\\n    Takes the engine rather than instrumenting globally. Langflow's engine is an AsyncEngine and\\n    the instrumentor patches the sync engine underneath it; a global ``instrument()`` with no\\n    engine attaches to pool events only, which produces a connect span per checkout and no query\\n    spans at all. Verified against a live backend: 13 connect spans and zero db.statement for one\\n    API request. That is worse than nothing, because it looks like DB visibility.\\n\\n    Deliberately does not instrument httpx or requests. Those are the transports the LLM vendor\\n    SDKs ride on, and instrumenting them globally would put one span per outbound provider call\\n    into the operator's APM.\\n\\n    Optional and failure-tolerant: a missing package or a double-instrument call must not take\\n    the app down, because none of this is worth a failed boot.\\n    \\\"\\\"\\\"\\n    _instrument_sqlalchemy(engine)\\n\\n\\ndef _instrument_sqlalchemy(engine: object) -> None:\\n    if not db_spans_enabled():\\n        # Not instrumenting at all, rather than instrumenting and dropping on the way out.\\n        # The spans are never created, so the operator pays no span-creation cost for\\n        # telemetry they turned off. The processor subtracts the scope as well, which is what\\n        # covers the case of some other library instrumenting sqlalchemy against our provider.\\n        logger.debug(\\\"LANGFLOW_OTEL_DB_SPANS is off; not instrumenting sqlalchemy\\\")\\n        return\\n    try:\\n        from opentelemetry import trace\\n        from opentelemetry.instrumentation.sqlalchemy import SQLAlchemyInstrumentor\\n    except ImportError:\\n        return\\n    try:\\n        SQLAlchemyInstrumentor().instrument(\\n            # An AsyncEngine exposes the sync one the instrumentor actually patches.\\n            engine=getattr(engine, \\\"sync_engine\\\", engine),\\n            tracer_provider=trace.get_tracer_provider(),\\n        )\\n    except Exception:  # noqa: BLE001 - see above\\n        logger.debug(\\\"sqlalchemy instrumentation unavailable; DB spans will be missing\\\", exc_info=True)\\n\\n\\n# The key a queued job carries its originating trace context under, inside the job's own\\n# metadata dict. Prefixed because that dict is shared with application keys (``request``,\\n# ``pending_request_id``, ``pre_pause_outputs``) and this one is machine-owned.\\nJOB_TRACE_CARRIER_KEY = \\\"otel_traceparent\\\"\\n\\n\\ndef inject_trace_carrier(metadata: dict[str, Any] | None = None) -> dict[str, Any]:\\n    \\\"\\\"\\\"Return *metadata* with the current trace context added, if there is one.\\n\\n    A queued run happens after its request has returned, in a worker that may be a different\\n    process. ``contextvars`` do not survive that, so the context has to travel with the job\\n    row. This writes it in W3C ``traceparent`` form rather than as a bare trace id: the\\n    standard form carries the sampled flag, and a bare id would let a linked run be dropped by\\n    a sampler that kept the request it came from.\\n\\n    Writes nothing when no valid span is current. A missing carrier is an honest \\\"nobody was\\n    tracing\\\"; a synthesised one renders in the APM as a real relationship that never existed.\\n    Same rule the ``protocol`` attribute follows.\\n\\n    Call this once, at enqueue. Nothing rewrites it afterwards, which is deliberate: the job\\n    metadata blob is written back whole, and a second writer on the pause path would race the\\n    one that is already there.\\n    \\\"\\\"\\\"\\n    carrier: dict[str, Any] = dict(metadata or {})\\n    if not _OTEL_AVAILABLE:\\n        return carrier\\n    try:\\n        from opentelemetry import trace as _trace\\n        from opentelemetry.trace.propagation.tracecontext import TraceContextTextMapPropagator\\n\\n        if not _trace.get_current_span().get_span_context().is_valid:\\n            return carrier\\n        headers: dict[str, str] = {}\\n        TraceContextTextMapPropagator().inject(headers)\\n        traceparent = headers.get(\\\"traceparent\\\")\\n        if traceparent:\\n            carrier[JOB_TRACE_CARRIER_KEY] = traceparent\\n    except Exception:  # noqa: BLE001\\n        # Telemetry must never fail an enqueue. A job that runs untraced beats a job that\\n        # does not run.\\n        logger.debug(\\\"could not inject the trace carrier into job metadata\\\", exc_info=True)\\n    return carrier\\n\\n\\n# The link a queued run carries back to the request that enqueued it. Ambient for the same\\n# reason ``protocol`` is: the graph that opens the flow span sits several layers below the\\n# runner that reads the job row, and two of those layers hand the run to a fresh asyncio task,\\n# which copies the context.\\n_current_queued_trace_link: contextvars.ContextVar[Any] = contextvars.ContextVar(\\n    \\\"lfx_queued_trace_link\\\",\\n    default=None,\\n)\\n\\n\\ndef get_queued_trace_link() -> Link | None:\\n    \\\"\\\"\\\"Return the link to the request that queued this run, or None outside a queued run.\\\"\\\"\\\"\\n    return _current_queued_trace_link.get()\\n\\n\\n@contextlib.contextmanager\\ndef queued_trace_link(link: Any) -> Iterator[None]:\\n    \\\"\\\"\\\"Bind *link* for runs started in this context, and reset it on exit.\\n\\n    Reset matters: a worker serves many jobs on one task, so a link left bound would attach\\n    one job's originating request to the next job's run.\\n    \\\"\\\"\\\"\\n    if link is None:\\n        yield\\n        return\\n    token = _current_queued_trace_link.set(link)\\n    try:\\n        yield\\n    finally:\\n        _current_queued_trace_link.reset(token)\\n\\n\\ndef tracing_is_available() -> bool:\\n    \\\"\\\"\\\"Whether OpenTelemetry is importable at all.\\n\\n    Exposed so a caller can skip work that exists only to feed telemetry, such as reading a\\n    job row purely for its trace carrier, on a deployment that ships without the extra.\\n    \\\"\\\"\\\"\\n    return _OTEL_AVAILABLE\\n\\n\\ndef extract_trace_link(metadata: dict[str, Any] | None) -> Link | None:\\n    \\\"\\\"\\\"Return a ``Link`` to the request that queued this job, or None.\\n\\n    None covers every honest case: OpenTelemetry absent, the job enqueued while nothing was\\n    tracing, or a carrier that will not parse. The caller starts an unlinked root span, which\\n    is what happens today.\\n    \\\"\\\"\\\"\\n    if not _OTEL_AVAILABLE or not metadata:\\n        return None\\n    traceparent = metadata.get(JOB_TRACE_CARRIER_KEY)\\n    if not isinstance(traceparent, str) or not traceparent:\\n        return None\\n    try:\\n        from opentelemetry import trace as _trace\\n        from opentelemetry.trace.propagation.tracecontext import TraceContextTextMapPropagator\\n\\n        context = TraceContextTextMapPropagator().extract({\\\"traceparent\\\": traceparent})\\n        span_context = _trace.get_current_span(context).get_span_context()\\n        if not span_context.is_valid:\\n            return None\\n        return _trace.Link(span_context)\\n    except Exception:  # noqa: BLE001\\n        logger.debug(\\\"could not extract the trace carrier from job metadata\\\", exc_info=True)\\n        return None\\n\\n\\nclass OutboundCallScope:\\n    \\\"\\\"\\\"Handle for a caller that learns the outcome after the call returns.\\n\\n    A protocol that reports failure in its return value rather than by raising leaves the span\\n    with nothing to see. MCP is one: a failed tool call comes back as a ``CallToolResult`` with\\n    ``isError`` set, so without this the span closes OK and the operator's error rate on\\n    outbound calls is zero no matter how many tools are failing.\\n\\n    Takes an error type, never a message or a result: the failure text a server returns embeds\\n    the arguments it was called with.\\n    \\\"\\\"\\\"\\n\\n    __slots__ = (\\\"error_type\\\", \\\"span\\\")\\n\\n    def __init__(self, span: Span | None = None) -> None:\\n        self.error_type: str | None = None\\n        self.span = span\\n\\n    def record_error(self, error_type: str) -> None:\\n        # First failure wins, so a later one cannot overwrite the one that caused the retry.\\n        if self.error_type is None:\\n            self.error_type = error_type\\n\\n    def set_attribute(self, key: str, value: str) -> None:\\n        \\\"\\\"\\\"Record an identifier the caller only learns mid-call.\\n\\n        A2A only learns which agent it reached after resolving the remote card, which is itself\\n        part of the call the span covers. Same boundary as the opening attributes: identifiers\\n        only, never a message, an argument or a result.\\n        \\\"\\\"\\\"\\n        if self.span is not None:\\n            self.span.set_attribute(key, value)\\n\\n\\ndef _root_error_type(exc: BaseException) -> str:\\n    \\\"\\\"\\\"Name the exception that actually failed, not the one the retry loop wrapped it in.\\n\\n    Both MCP retry loops re-raise as ``ValueError(f\\\"Failed to run tool ...\\\")`` with ``from e``,\\n    so without walking the chain every timeout, dropped connection and closed resource records\\n    as ``ValueError`` and the attribute tells an operator nothing. Transport task groups can\\n    also wrap one actionable failure in an exception group; a group is unwrapped only when it\\n    has one member, because a multi-error group has no single root type. Only the type is read;\\n    the message stays unrecorded either way.\\n    \\\"\\\"\\\"\\n    root = exc\\n    seen = {id(root)}\\n    while True:\\n        # asyncio implements wait_for timeouts by cancelling the inner task, so TimeoutError\\n        # explicitly chains a CancelledError. The timeout is the actionable failure; the inner\\n        # cancellation is an implementation detail. A real outer cancellation still arrives as\\n        # CancelledError directly and is reported as such.\\n        if isinstance(root, (asyncio.TimeoutError, TimeoutError)):\\n            break\\n        next_error = root.__cause__\\n        if (\\n            next_error is None\\n            and _BASE_EXCEPTION_GROUP_TYPE is not None\\n            and isinstance(root, _BASE_EXCEPTION_GROUP_TYPE)\\n        ):\\n            grouped = root.exceptions\\n            if isinstance(grouped, tuple) and len(grouped) == 1 and isinstance(grouped[0], BaseException):\\n                next_error = grouped[0]\\n        if next_error is None or id(next_error) in seen:\\n            break\\n        root = next_error\\n        seen.add(id(root))\\n    return type(root).__name__\\n\\n\\n@contextlib.contextmanager\\ndef outbound_call_span(name: str, attributes: dict[str, str]) -> Iterator[OutboundCallScope]:\\n    \\\"\\\"\\\"One span for an outbound call the runtime makes itself, for the operator's APM.\\n\\n    Emitted under APPLICATION_TRACER_NAME rather than by instrumenting the transport. The\\n    transport is shared with the LLM vendor SDKs, and the export filter allowlists by\\n    instrumentation scope name, so an httpx span from our MCP client and one from the OpenAI\\n    SDK are the same string and cannot be told apart. Emitting the span ourselves makes the\\n    scope name the discriminator by construction.\\n\\n    Identifiers only, never arguments or results, which carry flow data. Errors record the\\n    exception type, never its message, for the same reason.\\n\\n    Yields an :class:`OutboundCallScope`. A caller whose protocol reports failure in the return\\n    value rather than by raising must call ``record_error`` or its failures export as successes.\\n    \\\"\\\"\\\"\\n    if not _OTEL_AVAILABLE:\\n        yield OutboundCallScope()\\n        return\\n    tracer = trace.get_tracer(APPLICATION_TRACER_NAME)\\n    # Neither recording nor status-setting is delegated to the SDK: its versions write the\\n    # exception message onto the span, and that can carry flow data.\\n    with tracer.start_as_current_span(name, record_exception=False, set_status_on_exception=False) as span:\\n        scope = OutboundCallScope(span)\\n        for key, value in attributes.items():\\n            span.set_attribute(key, value)\\n        try:\\n            yield scope\\n        # BaseException, not Exception: CancelledError is a BaseException, and a tool call\\n        # cancelled by a client disconnect or an outer wait_for would otherwise export as a\\n        # success. Only the type is recorded, so this stays inside the same boundary.\\n        except BaseException as exc:\\n            error_type = _root_error_type(exc)\\n            span.set_status(trace.Status(trace.StatusCode.ERROR, error_type))\\n            span.set_attribute(\\\"error.type\\\", error_type)\\n            raise\\n        else:\\n            if scope.error_type is not None:\\n                span.set_status(trace.Status(trace.StatusCode.ERROR, scope.error_type))\\n                span.set_attribute(\\\"error.type\\\", scope.error_type)\\n\\n\\ndef instrument_fastapi_app(app: FastAPI) -> None:\\n    \\\"\\\"\\\"Instrument an ASGI app for HTTP server telemetry under the stable conventions.\\n\\n    Both runtimes serve over FastAPI, so both call this on their app: langflow on its main\\n    app, ``lfx serve`` on the multi-flow app. No-op when the FastAPI instrumentation is not\\n    installed.\\n\\n    The stable HTTP semantic conventions (http.route, http.request.method,\\n    http.response.status_code) are opted into at module import, not here. The opt-in is read\\n    once, when OpenTelemetry's instrumentation package first initialises, and by the time this\\n    runs that has already happened.\\n    \\\"\\\"\\\"\\n    try:\\n        from opentelemetry.instrumentation.fastapi import FastAPIInstrumentor\\n    except ImportError:\\n        return\\n\\n    # FastAPI >=0.137 lazy include_router puts _IncludedRouter wrappers (no .path) in\\n    # app.routes, which crashes OTel's span route extraction on partial matches (e.g. CORS\\n    # preflight). Patch the helper before instrumenting.\\n    patch_otel_fastapi_route_details()\\n    FastAPIInstrumentor.instrument_app(app)\\n\\n\\ndef start_event_loop_lag_monitor(\\n    meter_provider: MeterProvider | None,\\n    *,\\n    interval: float = EVENT_LOOP_LAG_INTERVAL_SECONDS,\\n) -> asyncio.Task | None:\\n    \\\"\\\"\\\"Record event-loop scheduling delay as a histogram on the running loop.\\n\\n    This is the async-specific failure that nothing else on a dashboard explains: one\\n    blocking call on the loop thread stalls every endpoint at once, while CPU, memory and GC\\n    stay flat, so the process metrics report a healthy service while it is on fire. Sleeping\\n    a known interval and measuring how late we actually wake is the cheapest signal that\\n    separates \\\"blocked\\\" from \\\"genuinely busy\\\".\\n\\n    Carries no attributes on purpose: the value describes this process, and unbounded labels\\n    are what make metrics expensive.\\n\\n    Returns the task so the caller can stop it on shutdown, or None when there is no meter\\n    provider to record on (nothing configured, or OpenTelemetry not installed).\\n    \\\"\\\"\\\"\\n    if not _OTEL_AVAILABLE or meter_provider is None:\\n        return None\\n\\n    histogram = meter_provider.get_meter(APPLICATION_METER_NAME).create_histogram(\\n        EVENT_LOOP_LAG_METRIC,\\n        unit=\\\"s\\\",\\n        description=\\\"How much later than requested the event loop resumed a sleeping task.\\\",\\n        explicit_bucket_boundaries_advisory=list(EVENT_LOOP_LAG_BUCKETS_SECONDS),\\n    )\\n\\n    async def _monitor() -> None:\\n        while True:\\n            started = time.perf_counter()\\n            await asyncio.sleep(interval)\\n            try:\\n                # perf_counter is monotonic, so drift cannot go negative from a clock change;\\n                # clamp anyway so a pathological scheduler cannot record a negative latency.\\n                histogram.record(max(time.perf_counter() - started - interval, 0.0))\\n            except Exception:  # noqa: BLE001 - a sampler must not take the app down\\n                # Without this the task dies silently (the metric simply stops) and the\\n                # exception waits on the task until shutdown awaits it, where it would\\n                # replace whatever was actually shutting the app down.\\n                logger.exception(\\\"Event loop lag sampler failed; continuing without this sample\\\")\\n\\n    return asyncio.create_task(_monitor(), name=\\\"langflow-event-loop-lag\\\")\\n\\n\\nasync def stop_event_loop_lag_monitor(task: asyncio.Task | None) -> None:\\n    \\\"\\\"\\\"Cancel the monitor started by :func:`start_event_loop_lag_monitor`. Safe with None.\\\"\\\"\\\"\\n    if task is None:\\n        return\\n\\n    async def _wait_for_monitor() -> None:\\n        with contextlib.suppress(asyncio.CancelledError):\\n            await task\\n\\n    task.cancel()\\n    # The waiter absorbs only the monitor's expected cancellation. Shielding it keeps\\n    # cancellation of the calling lifespan task from being forwarded into that waiter\\n    # and mistaken for the monitor's cancellation.\\n    await asyncio.shield(_wait_for_monitor())\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/observability_doctor.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a96375ccda770605cf6e18ef03e1c9dfe6a8cfc15d0fb11b160bad03a39ee93d\",\"content\":\"\\\"\\\"\\\"OTLP delivery self-test: build the real exporters and send one synthetic item per signal.\\n\\nOTLP exporters swallow delivery failures by design. They retry, then drop, and log at most.\\nAn operator who sets a wrong endpoint, wrong protocol, or missing auth header gets silence:\\nno error at startup, no data in the backend, no way to tell which end is wrong.\\n\\nThis module turns that silence into an answer. It resolves the same ``OTEL_*`` environment\\n:mod:`lfx.observability` bootstraps from, using that module's own resolution helpers so the two\\ncannot drift, constructs the same exporters, pushes one synthetic span, metric and log record\\nthrough each, and reports the export result along with whatever the exporter logged on the way.\\nNothing global is installed: the providers built here are local and thrown away, so running the\\ncheck against a live process cannot disturb it.\\n\\nThe synthetic payloads are produced by the SDK itself (a real tracer, meter and logger feeding\\nan in-memory sink) rather than hand-constructed, so what reaches the exporter is shaped exactly\\nlike production traffic.\\n\\nScope, deliberately: this verifies configuration and reachability from wherever it runs. It\\ncannot verify that a *separate* serving process installed its providers, because it runs in its\\nown process and builds its own. :func:`lfx.observability.bootstrap_application_telemetry`\\ndeclines to install traces or logs when another provider is already present, and a doctor run\\ncannot observe that. The CLI says so rather than letting a green result overclaim.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport logging\\nimport os\\nimport threading\\nfrom contextlib import contextmanager\\nfrom dataclasses import dataclass, field\\n\\nfrom lfx.log.logger import logger\\nfrom lfx.observability import (\\n    APPLICATION_METER_NAME,\\n    APPLICATION_TRACER_NAME,\\n    otlp_endpoint,\\n    otlp_exporter_class,\\n    otlp_exporter_disabled,\\n)\\n\\nSIGNALS = (\\\"traces\\\", \\\"metrics\\\", \\\"logs\\\")\\n\\n# The name every synthetic item carries, so an operator can find it in their backend and\\n# confirm the round trip end to end rather than trusting an exporter's return value alone.\\nPROBE_NAME = \\\"lfx.observability.doctor\\\"\\n\\nOK = \\\"ok\\\"\\nFAILED = \\\"failed\\\"\\nSKIPPED = \\\"skipped\\\"\\n\\n\\n@dataclass\\nclass SignalReport:\\n    \\\"\\\"\\\"The outcome of pushing one synthetic item for a single signal.\\\"\\\"\\\"\\n\\n    signal: str\\n    status: str = SKIPPED\\n    endpoint: str | None = None\\n    protocol: str | None = None\\n    detail: str = \\\"\\\"\\n    # Header names only, resolved per signal. The values are bearer tokens and API keys.\\n    header_keys: list[str] = field(default_factory=list)\\n    # Whatever the exporter logged while we held the line open. This is the whole point of the\\n    # command: these messages are normally emitted into a logger nobody is watching, and then\\n    # the failure is dropped.\\n    exporter_logs: list[str] = field(default_factory=list)\\n\\n\\n@dataclass\\nclass DoctorReport:\\n    \\\"\\\"\\\"The resolved configuration and the per-signal results.\\\"\\\"\\\"\\n\\n    signals: list[SignalReport] = field(default_factory=list)\\n    service_name: str = \\\"\\\"\\n    # Set when the check could not run at all, rather than running and failing.\\n    error: str = \\\"\\\"\\n\\n    @property\\n    def ok(self) -> bool:\\n        \\\"\\\"\\\"True when nothing failed. An all-skipped run is not a failure, it is 'not configured'.\\\"\\\"\\\"\\n        return not self.error and all(s.status != FAILED for s in self.signals)\\n\\n    @property\\n    def configured(self) -> bool:\\n        \\\"\\\"\\\"Whether any signal resolved an endpoint, regardless of whether it was then disabled.\\\"\\\"\\\"\\n        return any(s.endpoint for s in self.signals)\\n\\n\\nclass _ExporterLogCapture(logging.Handler):\\n    \\\"\\\"\\\"Collects what the OTLP exporters log, which is where swallowed failures go.\\n\\n    Bound to the thread that opened the window. The ``opentelemetry`` logger is process-global, so\\n    beside a live server a BatchSpanProcessor failing on its own background thread would otherwise\\n    be collected here and printed underneath one of the doctor's own signals, blaming this run for\\n    an unrelated outage.\\n    \\\"\\\"\\\"\\n\\n    def __init__(self, thread_id: int) -> None:\\n        super().__init__(level=logging.WARNING)\\n        self.messages: list[str] = []\\n        self._thread_id = thread_id\\n\\n    def emit(self, record: logging.LogRecord) -> None:\\n        if record.thread != self._thread_id:\\n            return\\n        self.messages.append(f\\\"{record.levelname}: {record.getMessage()}\\\")\\n\\n\\n# Serializes the temporary mutation of the process-global ``opentelemetry`` logger below.\\n# Without it, two overlapping capture windows snapshot each other's temporary level and restore\\n# out of order, leaving the logger permanently at the wrong level: a host that had quieted otel\\n# to ERROR is left at WARNING for the rest of the process. That would break the guarantee this\\n# module rests on, that a doctor run cannot disturb a live process.\\n#\\n# ponytail: one global lock, because the thing being guarded is itself one global logger. The\\n# windows are short and never nested, so there is nothing to contend over and no upgrade path\\n# worth building.\\n_LOGGER_STATE_LOCK = threading.Lock()\\n\\n\\n@contextmanager\\ndef _capture_exporter_logs():\\n    \\\"\\\"\\\"Listen on the ``opentelemetry`` logger for the duration of one export.\\n\\n    The logger is normally NOTSET, taking its effective level from the root, so a host that\\n    quieted otel would hide the very messages we exist to surface. The level is therefore lowered\\n    to WARNING when it sits above that, and only lowered: raising it would suppress DEBUG and INFO\\n    records a host had deliberately asked for. Level and handler are both restored afterwards,\\n    under a lock so concurrent callers cannot interleave their snapshot and restore.\\n\\n    Lowering it does mean a host that quieted otel to ERROR sees warnings through its own handlers\\n    for the length of one export. That is accepted deliberately: capturing the message the\\n    exporter would otherwise swallow is the entire purpose of this command, and it cannot be read\\n    without letting the record past the logger.\\n    \\\"\\\"\\\"\\n    handler = _ExporterLogCapture(threading.get_ident())\\n    otel_logger = logging.getLogger(\\\"opentelemetry\\\")\\n    with _LOGGER_STATE_LOCK:\\n        previous_level = otel_logger.level\\n        if otel_logger.getEffectiveLevel() > logging.WARNING:\\n            otel_logger.setLevel(logging.WARNING)\\n        otel_logger.addHandler(handler)\\n        try:\\n            yield handler\\n        finally:\\n            otel_logger.removeHandler(handler)\\n            otel_logger.setLevel(previous_level)\\n\\n\\n# What the OTLP response carries per signal when the backend accepted the request but threw\\n# some of the payload away. The field names differ per signal, so they are mapped once here.\\n_PARTIAL_SUCCESS_FIELD = {\\n    \\\"traces\\\": \\\"rejected_spans\\\",\\n    \\\"metrics\\\": \\\"rejected_data_points\\\",\\n    \\\"logs\\\": \\\"rejected_log_records\\\",\\n}\\n\\n\\ndef _response_class(signal: str):\\n    \\\"\\\"\\\"The protobuf response type a collector returns for *signal*.\\\"\\\"\\\"\\n    if signal == \\\"traces\\\":\\n        from opentelemetry.proto.collector.trace.v1.trace_service_pb2 import ExportTraceServiceResponse as Response\\n    elif signal == \\\"metrics\\\":\\n        from opentelemetry.proto.collector.metrics.v1.metrics_service_pb2 import (\\n            ExportMetricsServiceResponse as Response,\\n        )\\n    else:\\n        from opentelemetry.proto.collector.logs.v1.logs_service_pb2 import ExportLogsServiceResponse as Response\\n    return Response\\n\\n\\ndef _recording_session():\\n    \\\"\\\"\\\"A requests session that keeps the last response, so we can inspect what the exporter ignored.\\n\\n    The HTTP exporter decides success on ``resp.ok`` alone: it never looks at redirects and never\\n    parses the body. That makes several \\\"delivered nothing\\\" situations indistinguishable from a\\n    real success, which is exactly what this command exists to tell apart. Keeping the response\\n    lets :func:`_delivery_problem` apply the checks the exporter skips.\\n    \\\"\\\"\\\"\\n    import requests\\n\\n    class RecordingSession(requests.Session):\\n        def __init__(self) -> None:\\n            super().__init__()\\n            self.last_response = None\\n\\n        def post(self, *args, **kwargs):\\n            response = super().post(*args, **kwargs)\\n            self.last_response = response\\n            return response\\n\\n    return RecordingSession()\\n\\n\\ndef _delivery_problem(session, signal: str) -> str | None:\\n    \\\"\\\"\\\"Why a 2xx did not actually mean delivery, or None when it did.\\n\\n    Three cases the exporter reports as success:\\n\\n    - A redirect. ``requests`` follows a 302 by downgrading POST to GET and dropping the body, so\\n      an auth proxy or an ingress with a trailing-slash rule swallows the payload and answers 200\\n      from a login page.\\n    - A partial success. The collector accepted the request and then rejected some or all of the\\n      items, for quota, cardinality or an unknown tenant. The count is in the response body, which\\n      the exporter never reads.\\n    - A non-OTLP 200. An ingress answering HTML on an unmatched path looks identical to a\\n      collector otherwise. An empty body stays acceptable: real collectors send one.\\n    \\\"\\\"\\\"\\n    response = getattr(session, \\\"last_response\\\", None)\\n    if response is None:\\n        return None\\n\\n    if response.history:\\n        chain = \\\" -> \\\".join(str(r.status_code) for r in response.history)\\n        return (\\n            f\\\"the request was redirected ({chain}) to {response.url} and the payload was dropped; \\\"\\n            f\\\"redirects turn the POST into a GET, so nothing was delivered\\\"\\n        )\\n\\n    body = response.content\\n    if not body:\\n        return None\\n\\n    try:\\n        parsed = _response_class(signal).FromString(body)\\n    except Exception:  # noqa: BLE001\\n        content_type = response.headers.get(\\\"Content-Type\\\", \\\"unknown\\\")\\n        return (\\n            f\\\"the endpoint answered {response.status_code} with a {content_type} body that is not an \\\"\\n            f\\\"OTLP response, so it is not a collector\\\"\\n        )\\n\\n    rejected = getattr(parsed.partial_success, _PARTIAL_SUCCESS_FIELD[signal], 0)\\n    if rejected:\\n        reason = parsed.partial_success.error_message or \\\"no reason given\\\"\\n        return f\\\"the collector rejected {rejected} item(s) from it: {reason}\\\"\\n    return None\\n\\n\\ndef _header_keys(signal: str) -> list[str]:\\n    \\\"\\\"\\\"Header names for one signal, never the values.\\n\\n    Mirrors the SDK's resolution, which is a fallback and not a merge: a per-signal variable\\n    replaces the generic one outright for that signal. Reporting the union instead would tell an\\n    operator debugging \\\"traces authenticate, metrics 401\\\" that both carry the same headers when\\n    neither does.\\n    \\\"\\\"\\\"\\n    from opentelemetry.util.re import parse_env_headers\\n\\n    raw = os.getenv(f\\\"OTEL_EXPORTER_OTLP_{signal.upper()}_HEADERS\\\")\\n    if raw is None:\\n        raw = os.getenv(\\\"OTEL_EXPORTER_OTLP_HEADERS\\\")\\n    if not raw:\\n        return []\\n    return list(parse_env_headers(raw, liberal=True))\\n\\n\\ndef _probe_spans(resource):\\n    \\\"\\\"\\\"One real span, produced by a throwaway tracer provider and caught in memory.\\n\\n    The probe is forced to record, rather than inheriting ``OTEL_TRACES_SAMPLER``. The probe is a\\n    single root span with a fresh trace id, so under any probabilistic sampler it is dropped at\\n    the configured ratio and the traces verdict becomes a coin flip on a perfectly healthy\\n    pipeline: at ratio 0.1 the command fails roughly nine runs in ten and its exit code changes\\n    with no configuration change, which makes it useless as a healthcheck. Sampling governs which\\n    production traffic is worth keeping; it says nothing about whether the transport works, and\\n    the transport is what this command tests.\\n\\n    ``always_off`` is the exception and stays inherited. There the operator has turned tracing off\\n    outright, so reporting that nothing was sent is the honest answer rather than a coin flip.\\n    \\\"\\\"\\\"\\n    from opentelemetry.sdk.trace import TracerProvider\\n    from opentelemetry.sdk.trace.export import SimpleSpanProcessor\\n    from opentelemetry.sdk.trace.export.in_memory_span_exporter import InMemorySpanExporter\\n    from opentelemetry.sdk.trace.sampling import ALWAYS_ON\\n\\n    sink = InMemorySpanExporter()\\n    configured_sampler = os.getenv(\\\"OTEL_TRACES_SAMPLER\\\", \\\"\\\").strip().lower()\\n    sampler = None if \\\"always_off\\\" in configured_sampler else ALWAYS_ON\\n    # shutdown_on_exit=False: this provider is thrown away here, and registering an atexit\\n    # handler for it would outlive the check and accumulate across repeated calls.\\n    provider = TracerProvider(resource=resource, shutdown_on_exit=False, sampler=sampler)\\n    provider.add_span_processor(SimpleSpanProcessor(sink))\\n    with provider.get_tracer(APPLICATION_TRACER_NAME).start_as_current_span(PROBE_NAME):\\n        pass\\n    spans = sink.get_finished_spans()\\n    provider.shutdown()\\n    return spans\\n\\n\\ndef _probe_metrics(resource, exporter):\\n    \\\"\\\"\\\"One real counter data point, collected through an in-memory reader.\\n\\n    The reader takes its temporality and aggregation from the exporter that is about to send the\\n    point, which is what ``PeriodicExportingMetricReader`` does in the real pipeline. Left at the\\n    reader's cumulative default, ``OTEL_EXPORTER_OTLP_METRICS_TEMPORALITY_PREFERENCE=delta`` would\\n    be ignored here and the doctor would test a data point shaped unlike production's, against\\n    backends that accept one and reject the other.\\n    \\\"\\\"\\\"\\n    from opentelemetry.sdk.metrics import MeterProvider\\n    from opentelemetry.sdk.metrics.export import InMemoryMetricReader\\n\\n    reader = InMemoryMetricReader(\\n        preferred_temporality=exporter._preferred_temporality,  # noqa: SLF001\\n        preferred_aggregation=exporter._preferred_aggregation,  # noqa: SLF001\\n    )\\n    provider = MeterProvider(resource=resource, metric_readers=[reader], shutdown_on_exit=False)\\n    provider.get_meter(APPLICATION_METER_NAME).create_counter(PROBE_NAME).add(1)\\n    data = reader.get_metrics_data()\\n    provider.shutdown()\\n    return data\\n\\n\\ndef _probe_logs(resource):\\n    \\\"\\\"\\\"One real log record, emitted through a throwaway logger provider.\\\"\\\"\\\"\\n    from opentelemetry._logs import SeverityNumber\\n    from opentelemetry.sdk._logs import LoggerProvider\\n    from opentelemetry.sdk._logs.export import InMemoryLogExporter, SimpleLogRecordProcessor\\n\\n    sink = InMemoryLogExporter()\\n    provider = LoggerProvider(resource=resource, shutdown_on_exit=False)\\n    provider.add_log_record_processor(SimpleLogRecordProcessor(sink))\\n    provider.get_logger(PROBE_NAME).emit(\\n        body=\\\"lfx observability doctor probe\\\",\\n        severity_number=SeverityNumber.INFO,\\n        severity_text=\\\"INFO\\\",\\n    )\\n    records = sink.get_finished_logs()\\n    provider.shutdown()\\n    return records\\n\\n\\ndef _is_empty(payload) -> bool:\\n    \\\"\\\"\\\"Whether the probe produced nothing to send.\\n\\n    Metrics arrive as a ``MetricsData`` rather than a sequence, so a plain truth test will not\\n    do. This matters because an empty payload still exports as SUCCESS, which would report\\n    delivery for a request that carried no data.\\n    \\\"\\\"\\\"\\n    resource_metrics = getattr(payload, \\\"resource_metrics\\\", None)\\n    if resource_metrics is not None:\\n        return not resource_metrics\\n    return not payload\\n\\n\\ndef _sdk_disabled() -> bool:\\n    \\\"\\\"\\\"Whether OTEL_SDK_DISABLED turned the whole SDK into no-ops.\\\"\\\"\\\"\\n    return os.getenv(\\\"OTEL_SDK_DISABLED\\\", \\\"\\\").strip().lower() == \\\"true\\\"\\n\\n\\ndef _empty_payload_detail(signal: str) -> str:\\n    \\\"\\\"\\\"Explain an empty probe, naming the sampler only when one is actually configured.\\\"\\\"\\\"\\n    sampler = os.getenv(\\\"OTEL_TRACES_SAMPLER\\\", \\\"\\\").strip()\\n    if signal == \\\"traces\\\" and sampler:\\n        return (\\n            \\\"The probe span was not recorded, so nothing could be sent and delivery was not \\\"\\n            f\\\"tested. OTEL_TRACES_SAMPLER={sampler} is dropping it.\\\"\\n        )\\n    return f\\\"The {signal} probe produced no data to send, so delivery was not tested.\\\"\\n\\n\\ndef _check_signal(signal: str, resource, timeout: float | None) -> SignalReport:\\n    \\\"\\\"\\\"Push one synthetic item for *signal* and report what the transport actually did.\\\"\\\"\\\"\\n    from lfx.observability import _otlp_protocol\\n\\n    report = SignalReport(signal=signal, endpoint=otlp_endpoint(signal))\\n    if not report.endpoint:\\n        report.detail = (\\n            f\\\"No endpoint configured. Set OTEL_EXPORTER_OTLP_{signal.upper()}_ENDPOINT or OTEL_EXPORTER_OTLP_ENDPOINT.\\\"\\n        )\\n        return report\\n    if otlp_exporter_disabled(signal):\\n        report.detail = f\\\"Disabled by OTEL_{signal.upper()}_EXPORTER=none.\\\"\\n        return report\\n    if _sdk_disabled():\\n        # The SDK hands back NoOp providers, so every probe comes back empty. Without this the\\n        # run reports three failures and blames the sampler, which is not set and drops nothing.\\n        report.detail = \\\"Disabled by OTEL_SDK_DISABLED=true.\\\"\\n        return report\\n\\n    report.protocol = _otlp_protocol(signal)\\n    report.header_keys = _header_keys(signal)\\n    route = f\\\"{report.endpoint} over {report.protocol}\\\"\\n\\n    # Only the HTTP exporters take a session. gRPC gives no equivalent hook, so the extra\\n    # delivery checks below are HTTP-only and a gRPC run keeps the plain result-code verdict.\\n    session = None if report.protocol == \\\"grpc\\\" else _recording_session()\\n    try:\\n        exporter_class = otlp_exporter_class(signal, report.protocol)\\n        exporter = (\\n            exporter_class(timeout=timeout) if session is None else exporter_class(timeout=timeout, session=session)\\n        )\\n    except Exception as exc:  # noqa: BLE001\\n        # Endpoint and protocol belong on every failure line, not only the ones that reached the\\n        # wire: a malformed OTEL_EXPORTER_OTLP_TIMEOUT raises here, before any request exists, and\\n        # \\\"which end is wrong\\\" is still the question. (A bad certificate path does not: both\\n        # transports construct fine and fail later, which the export branch below covers.)\\n        report.status = FAILED\\n        report.detail = f\\\"Could not build the exporter for {route}. {type(exc).__name__}: {exc}\\\"\\n        return report\\n\\n    # Report the URL the exporter resolved, not the raw variable. Only the generic endpoint gets\\n    # /v1/<signal> appended; a per-signal one is used verbatim. Without this a per-signal endpoint\\n    # aimed at the wrong path prints the same string on a failing and a passing line, so the\\n    # operator sees opposite verdicts against what looks like one URL.\\n    resolved = getattr(exporter, \\\"_endpoint\\\", None)\\n    if resolved:\\n        report.endpoint = str(resolved)\\n        route = f\\\"{report.endpoint} over {report.protocol}\\\"\\n\\n    try:\\n        if signal == \\\"traces\\\":\\n            payload = _probe_spans(resource)\\n        elif signal == \\\"metrics\\\":\\n            payload = _probe_metrics(resource, exporter)\\n        else:\\n            payload = _probe_logs(resource)\\n    except Exception as exc:  # noqa: BLE001\\n        # The probe builds SDK objects from environment the operator controls, so a bad value can\\n        # raise here. One failed signal is a better answer than an aborted run that reports none.\\n        #\\n        # Note this cannot catch the OTEL_*_LIMIT family: the SDK parses those into module-level\\n        # constants at import, so a malformed one raises while lfx.observability is being imported,\\n        # long before this runs. Nothing here can report that, and it is not worth chasing because\\n        # the same variable stops bootstrap_application_telemetry too, so the server would not\\n        # have started either.\\n        report.status = FAILED\\n        report.detail = f\\\"Could not build the {signal} probe. {type(exc).__name__}: {exc}\\\"\\n        return report\\n\\n    if _is_empty(payload):\\n        report.status = FAILED\\n        report.detail = _empty_payload_detail(signal)\\n        return report\\n\\n    with _capture_exporter_logs() as capture:\\n        try:\\n            result = exporter.export(payload)\\n        except Exception as exc:  # noqa: BLE001\\n            # The exporters normally catch their own transport errors, but a misconfiguration\\n            # that trips before the request can still raise. Surfacing it is the whole job here.\\n            report.status = FAILED\\n            report.detail = f\\\"Export to {route} failed. {type(exc).__name__}: {exc}\\\"\\n            report.exporter_logs = capture.messages\\n            return report\\n        finally:\\n            try:\\n                exporter.shutdown()\\n            except Exception as exc:  # noqa: BLE001\\n                logger.debug(f\\\"Ignoring error while shutting down the {signal} probe exporter: {exc}\\\")\\n\\n    report.exporter_logs = capture.messages\\n    # Every signal's export result enum spells success as a member named SUCCESS.\\n    if getattr(result, \\\"name\\\", \\\"\\\") == \\\"SUCCESS\\\":\\n        # SUCCESS only means the exporter saw a status under 400. It never checks whether it was\\n        # redirected away from the collector, and never reads the response body, so several\\n        # \\\"delivered nothing\\\" cases reach here looking identical to a real success.\\n        problem = _delivery_problem(session, signal) if session is not None else None\\n        if problem:\\n            report.status = FAILED\\n            report.detail = f\\\"Export to {route} reported success but {problem}.\\\"\\n            return report\\n        report.status = OK\\n        report.detail = f\\\"Accepted by {route}.\\\"\\n    else:\\n        report.status = FAILED\\n        # Deliberately not \\\"rejected\\\": a refused connection, a DNS failure and a 4xx all land\\n        # here, and claiming the backend answered would point the operator at the wrong end. The\\n        # captured exporter log printed below carries which one it actually was.\\n        report.detail = f\\\"Export to {route} failed.\\\"\\n    return report\\n\\n\\ndef run_doctor(*, timeout: float | None = None) -> DoctorReport:\\n    \\\"\\\"\\\"Send a synthetic span, metric and log through the configured OTLP exporters.\\n\\n    Returns a :class:`DoctorReport` describing the resolved configuration and what each signal's\\n    transport actually did. Installs nothing globally, so it is safe to run beside a live\\n    process.\\n\\n    ``timeout`` overrides the per-export timeout in seconds. Left unset, the exporters use\\n    ``OTEL_EXPORTER_OTLP_TIMEOUT`` or their own default. Note that the exporters retry with\\n    backoff inside that budget, so an unreachable endpoint takes the full timeout per signal.\\n    \\\"\\\"\\\"\\n    from lfx.observability import _OTEL_AVAILABLE\\n\\n    if not _OTEL_AVAILABLE:\\n        return DoctorReport(\\n            error=(\\n                \\\"OpenTelemetry is not installed, so nothing can be exported. \\\"\\n                \\\"Install it with: pip install 'lfx[otel]' (the full langflow distribution already includes it).\\\"\\n            )\\n        )\\n\\n    from opentelemetry.sdk.resources import SERVICE_NAME\\n\\n    from lfx.observability import _resource\\n\\n    resource = _resource()\\n    return DoctorReport(\\n        signals=[_check_signal(signal, resource, timeout) for signal in SIGNALS],\\n        service_name=str(resource.attributes.get(SERVICE_NAME, \\\"\\\")),\\n    )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/observability_fastapi.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f321fa0a785126a4ad53ccf856ddd97f2705b8c9fdfe92e0f55edaee816d5f76\",\"content\":\"\\\"\\\"\\\"Compatibility shim for OpenTelemetry FastAPI instrumentation under FastAPI >=0.137.\\n\\nFastAPI 0.137 changed ``include_router`` to *lazy* inclusion: instead of eagerly flattening a\\nsub-router's routes onto the parent, the top-level ``app.routes`` now contains\\n``_IncludedRouter`` wrappers. Those wrappers are matchable ``BaseRoute`` objects but\\nintentionally carry no ``.path`` attribute.\\n\\n``opentelemetry-instrumentation-fastapi`` names every request span by walking ``app.routes``\\nand reading ``route.path``. Its ``Match.FULL`` branch already guards the missing-``path`` case,\\nbut the ``Match.PARTIAL`` branch does not, so a request that only partially matches a lazily\\nincluded route (an OPTIONS/CORS preflight against a GET-only route) raises ``AttributeError``\\nmid-request and turns into a 500.\\n\\nRecovering the template is not cosmetic: under the stable HTTP semantic conventions this value\\nbecomes ``http.route``, which is a *metric label*, so returning the raw request path would put\\nevery flow id, file id and session id into the metric store as its own series. Everything\\nmounts under ``/api``, so on FastAPI >=0.137 that is every API request, not an edge case.\\n\\nLives beside :mod:`lfx.observability` (which calls it from ``instrument_fastapi_app``) rather\\nthan inside it, so the provider-bootstrap surface stays small.\\n\\\"\\\"\\\"\\n\\nfrom starlette.routing import Match, Route\\n\\nfrom lfx.log.logger import logger\\n\\n_PATCH_FLAG = \\\"_langflow_route_details_patched\\\"\\n# Include nesting is two deep (/api -> /v1 -> router). The bound is only here so a cycle in\\n# FastAPI internals cannot hang a request.\\n_MAX_INCLUDE_DEPTH = 10\\n\\n\\ndef _resolve_included_route(included_router, scope, depth=0):\\n    \\\"\\\"\\\"Find the templated path of the route inside a lazily-included router.\\n\\n    ``_IncludedRouter.effective_candidates()`` returns the router's children with their\\n    prefixes already applied: leaves carry ``.path`` (``/api/v1/flows/{flow_id}``) and nested\\n    includes are more ``_IncludedRouter`` wrappers, so this recurses. Returns None when\\n    nothing matches, which leaves the caller on its existing fallback.\\n    \\\"\\\"\\\"\\n    if depth > _MAX_INCLUDE_DEPTH:\\n        return None\\n    try:\\n        candidates = included_router.effective_candidates()\\n    except Exception:  # noqa: BLE001 - private FastAPI internals; never fail a request over a span name\\n        return None\\n\\n    partial = None\\n    for candidate in candidates:\\n        try:\\n            match, _ = candidate.matches(scope)\\n        except Exception:  # noqa: BLE001, S112 - one odd candidate must not fail the request\\n            continue\\n        if match == Match.NONE:\\n            continue\\n        path = getattr(candidate, \\\"path\\\", None)\\n        if path is None:\\n            path = _resolve_included_route(candidate, scope, depth + 1)\\n        if path is None:\\n            continue\\n        if match == Match.FULL:\\n            return path\\n        # A method mismatch (CORS preflight, 405) still identifies the endpoint. Keep it,\\n        # but let a later full match win.\\n        partial = partial or path\\n    return partial\\n\\n\\ndef _safe_get_route_details(scope):\\n    \\\"\\\"\\\"Drop-in replacement for OTel's ``_get_route_details`` that tolerates lazy includes.\\n\\n    Mirrors the upstream loop but guards the ``Match.PARTIAL`` ``route.path`` access the same\\n    way upstream already guards the ``Match.FULL`` access. When the matched route is a FastAPI\\n    ``_IncludedRouter`` (no ``.path``), it descends into the router to recover the templated\\n    path. The raw request path remains the last resort, since a wrong-but-bounded span name\\n    beats failing the request.\\n    \\\"\\\"\\\"\\n    app = scope[\\\"app\\\"]\\n    route = None\\n\\n    for starlette_route in app.routes:\\n        match, _ = (\\n            Route.matches(starlette_route, scope)\\n            if isinstance(starlette_route, Route)\\n            else starlette_route.matches(scope)\\n        )\\n        if match == Match.FULL:\\n            try:\\n                route = starlette_route.path\\n            except AttributeError:\\n                route = _resolve_included_route(starlette_route, scope) or scope.get(\\\"path\\\")\\n            break\\n        if match == Match.PARTIAL:\\n            try:\\n                route = starlette_route.path\\n            except AttributeError:\\n                # FastAPI >=0.137 lazy include: the matched route is an\\n                # `_IncludedRouter` wrapper with no `.path`.\\n                include_context = getattr(starlette_route, \\\"include_context\\\", None)\\n                route = (\\n                    _resolve_included_route(starlette_route, scope)\\n                    or getattr(include_context, \\\"prefix\\\", None)\\n                    or scope.get(\\\"path\\\")\\n                )\\n    return route\\n\\n\\ndef patch_otel_fastapi_route_details() -> None:\\n    \\\"\\\"\\\"Install the guarded ``_get_route_details`` on the OTel FastAPI instrumentation.\\n\\n    Idempotent. No-op when ``opentelemetry-instrumentation-fastapi`` is absent or when its\\n    internals no longer expose ``_get_route_details``.\\n    \\\"\\\"\\\"\\n    try:\\n        from opentelemetry.instrumentation import fastapi as otel_fastapi\\n    except ImportError:\\n        return\\n\\n    if getattr(otel_fastapi, _PATCH_FLAG, False):\\n        return\\n    if not hasattr(otel_fastapi, \\\"_get_route_details\\\"):\\n        # OTel internals changed; nothing to patch. Leave a breadcrumb so this is noticed if\\n        # FastAPI route spans start failing again.\\n        logger.debug(\\\"opentelemetry-instrumentation-fastapi has no _get_route_details; skipping compat patch\\\")\\n        return\\n\\n    otel_fastapi._get_route_details = _safe_get_route_details  # noqa: SLF001\\n    setattr(otel_fastapi, _PATCH_FLAG, True)\\n    logger.debug(\\\"Patched opentelemetry-instrumentation-fastapi._get_route_details for FastAPI >=0.137 lazy includes\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/observability_llm_metrics.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f64f8ca0866c0870b30600e36fe5e77583d5252e427cb4c43b994534f81c023e\",\"content\":\"\\\"\\\"\\\"Leak-safe LLM-provider latency and error metrics (\\\"is it us or them\\\").\\n\\nRecords outbound LLM-provider health as METRICS, never spans, keyed only on provider, model and\\nerror type. No URLs, no prompts, no completions, no error message strings ever reach a label, so\\nprovider API keys that ride in request URLs cannot leak the way they did through the httpx span\\npath (removed from the export allowlist in :mod:`lfx.observability`).\\n\\nThe instruments are created from the allowlisted \\\"langflow\\\" meter, so they export through the\\nsame application-only filter as the rest of the runtime's own metrics. When no provider is\\ninstalled yet ``metrics.get_meter`` hands back a proxy meter that records nowhere until the\\nbootstrap installs the real one, so creating the handler early is safe under ``lfx serve``.\\n\\nOpenTelemetry is an optional lfx extra (``lfx[otel]``). When it is absent there is no meter to\\nrecord on, so :func:`get_llm_provider_metrics_handler` returns None and the callback is simply\\nnot attached, keeping bare lfx importable.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport threading\\nimport time\\nfrom functools import lru_cache\\nfrom typing import TYPE_CHECKING, Any\\n\\nfrom langchain_core.callbacks import BaseCallbackHandler\\n\\nfrom lfx.base.models.llm_callback_utils import detect_provider_from_model, extract_llm_model_name\\nfrom lfx.observability import APPLICATION_METER_NAME\\n\\ntry:\\n    from opentelemetry import metrics\\n\\n    _OTEL_AVAILABLE = True\\nexcept ImportError:\\n    _OTEL_AVAILABLE = False\\n\\nif TYPE_CHECKING:\\n    from uuid import UUID\\n\\n    from langchain_core.outputs import LLMResult\\n\\n\\nclass LLMProviderMetricsCallbackHandler(BaseCallbackHandler):\\n    \\\"\\\"\\\"Records outbound LLM provider call duration and errors as leak-safe metrics.\\n\\n    Thread-safe and keyed by LangChain ``run_id``, so a single shared instance can serve every\\n    concurrent flow. Attributes are limited to provider, model and (on error) the exception\\n    class name; nothing derived from prompts, completions or URLs is ever recorded.\\n    \\\"\\\"\\\"\\n\\n    # Bounds _runs so a run cancelled mid-flight (client disconnect, user stop) never leaks\\n    # forever: those never reach on_llm_end/on_llm_error, so evict the oldest start when full.\\n    # ponytail: fixed cap, fine because entries are tiny and only in-flight+recently-orphaned runs sit here.\\n    _MAX_RUNS = 10_000\\n\\n    def __init__(self) -> None:\\n        super().__init__()\\n        meter = metrics.get_meter(APPLICATION_METER_NAME)\\n        # gen_ai.client.operation.duration is the OTel GenAI semconv metric; on failure it carries\\n        # error.type, recorded on both the success and error paths so failed-call latency is visible.\\n        self._duration = meter.create_histogram(\\n            \\\"gen_ai.client.operation.duration\\\",\\n            unit=\\\"s\\\",\\n            description=\\\"Duration of outbound LLM provider calls.\\\",\\n        )\\n        # A langflow-owned counter (not a semconv metric, so it stays out of the gen_ai.* namespace)\\n        # for direct alerting on provider error rate by type.\\n        self._errors = meter.create_counter(\\n            \\\"langflow.llm.provider.errors\\\",\\n            unit=\\\"{error}\\\",\\n            description=\\\"Outbound LLM provider call errors, keyed by provider, model and error type.\\\",\\n        )\\n        self._lock = threading.Lock()\\n        self._runs: dict[UUID, tuple[float, dict[str, str]]] = {}\\n\\n    def __deepcopy__(self, memo: dict[int, Any]) -> LLMProviderMetricsCallbackHandler:\\n        \\\"\\\"\\\"Share the instance rather than copying it.\\n\\n        Components are deep-copied on the way into a graph, and this handler is reachable from\\n        the callbacks attached to them. It holds a ``threading.Lock``, which cannot be copied\\n        (``TypeError: cannot pickle '_thread.lock' object``), so without this a flow carrying\\n        the handler fails to build.\\n\\n        Returning self is the intended semantics rather than a way around that error: the\\n        handler is a process-wide singleton by construction, its state is keyed by run_id and\\n        guarded by the lock, and its instruments belong to one meter. A copy would keep a\\n        private ``_runs`` and its own instruments, so starts and ends recorded through\\n        different copies would never pair up. Same reasoning as the handler in langfuse.py.\\n        \\\"\\\"\\\"\\n        memo[id(self)] = self\\n        return self\\n\\n    def _start(self, run_id: UUID, **kwargs: Any) -> None:\\n        model = extract_llm_model_name(kwargs)\\n        provider = detect_provider_from_model(model)\\n        attrs = {\\n            \\\"gen_ai.provider.name\\\": provider or \\\"unknown\\\",\\n            \\\"gen_ai.request.model\\\": model or \\\"unknown\\\",\\n        }\\n        with self._lock:\\n            if len(self._runs) >= self._MAX_RUNS:\\n                self._runs.pop(next(iter(self._runs)), None)\\n            self._runs[run_id] = (time.monotonic(), attrs)\\n\\n    def on_llm_start(self, serialized: dict[str, Any], prompts: list[str], *, run_id: UUID, **kwargs: Any) -> None:  # noqa: ARG002\\n        self._start(run_id, **kwargs)\\n\\n    def on_chat_model_start(\\n        self,\\n        serialized: dict[str, Any],  # noqa: ARG002\\n        messages: list[list[Any]],  # noqa: ARG002\\n        *,\\n        run_id: UUID,\\n        **kwargs: Any,\\n    ) -> None:\\n        self._start(run_id, **kwargs)\\n\\n    def on_llm_end(self, response: LLMResult, *, run_id: UUID, **kwargs: Any) -> None:  # noqa: ARG002\\n        self._finish(run_id)\\n\\n    def on_llm_error(self, error: BaseException, *, run_id: UUID, **kwargs: Any) -> None:  # noqa: ARG002\\n        self._finish(run_id, error=error)\\n\\n    def _finish(self, run_id: UUID, error: BaseException | None = None) -> None:\\n        with self._lock:\\n            run = self._runs.pop(run_id, None)\\n        start, attrs = (\\n            run if run is not None else (None, {\\\"gen_ai.provider.name\\\": \\\"unknown\\\", \\\"gen_ai.request.model\\\": \\\"unknown\\\"})\\n        )\\n        if error is not None:\\n            attrs = {**attrs, \\\"error.type\\\": type(error).__name__}\\n            self._errors.add(1, attrs)\\n        # No start time means the matching start was evicted or never seen; skip the duration point.\\n        if start is not None:\\n            self._duration.record(time.monotonic() - start, attrs)\\n\\n\\n@lru_cache(maxsize=1)\\ndef get_llm_provider_metrics_handler() -> LLMProviderMetricsCallbackHandler | None:\\n    \\\"\\\"\\\"Return the shared handler, or None when OpenTelemetry is not installed.\\n\\n    run_ids are unique UUIDs, so one lazily-created shared instance safely serves every flow.\\n    lru_cache gives the thread-safe lazy singleton in one line.\\n    \\\"\\\"\\\"\\n    if not _OTEL_AVAILABLE:\\n        return None\\n    return LLMProviderMetricsCallbackHandler()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/preload.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e587223e33c244066189829062c2ca70d3bea614bdbc1768ed5178ebf9217e6b\",\"content\":\"\\\"\\\"\\\"Warm up core component imports and execution paths for snapshot capture.\\n\\nlfx loads components lazily, so a fresh interpreter pays a large one-time cost on the\\nfirst flow build *and* the first run. Pre-warming triggers that cost up front in a\\nlong-lived process \u2014 e.g. a Firecracker \\\"golden snapshot\\\" captured before any tenant\\nflow runs \u2014 so the first build/run after restore is cheap, with no loss of isolation.\\n\\nTwo halves, neither performing observable execution:\\n\\n* **Imports** \u2014 importing the core component *classes* (not just their packages) pulls\\n  in their heavy submodules and dependencies, warming the build path. The model and\\n  agent components are imported but **never invoked**, so no network call happens.\\n* **Warm-up run** \u2014 running one model-free hermetic flow (ChatInput -> Prompt ->\\n  ChatOutput) once warms the graph execution machinery. It does in-memory string work\\n  only: no network, no external side effects.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport gc\\nimport importlib\\nimport time\\nfrom contextlib import contextmanager\\nfrom dataclasses import dataclass, field\\nfrom typing import TYPE_CHECKING\\n\\nif TYPE_CHECKING:\\n    from collections.abc import Sequence\\n\\n# Core (module, class) pairs to warm. Importing the class (not just the package) is what\\n# pulls in the heavy submodule + deps. Evolve this list as the warm set changes.\\nDEFAULT_CORE_COMPONENTS: tuple[tuple[str, str], ...] = (\\n    (\\\"lfx.components.input_output\\\", \\\"ChatInput\\\"),\\n    (\\\"lfx.components.input_output\\\", \\\"ChatOutput\\\"),\\n    (\\\"lfx.components.models_and_agents\\\", \\\"PromptComponent\\\"),\\n    (\\\"lfx.components.models_and_agents\\\", \\\"LanguageModelComponent\\\"),\\n    (\\\"lfx.components.models_and_agents\\\", \\\"AgentComponent\\\"),\\n)\\n\\n\\nclass PrewarmError(RuntimeError):\\n    \\\"\\\"\\\"Raised when a required core component fails to import, or fork-safety teardown fails.\\\"\\\"\\\"\\n\\n\\n@dataclass\\nclass PrewarmResult:\\n    \\\"\\\"\\\"Outcome of a :func:`prewarm_core_imports` call.\\\"\\\"\\\"\\n\\n    imported: list[str] = field(default_factory=list)\\n    failed: dict[str, str] = field(default_factory=dict)\\n    warmup_ran: bool = False\\n    froze: bool = False\\n    services_torn_down: bool = False\\n    elapsed_s: float = 0.0\\n\\n\\n@dataclass\\nclass FlowPrewarmResult:\\n    \\\"\\\"\\\"Outcome of a :func:`prewarm_flow` call.\\\"\\\"\\\"\\n\\n    built: bool = False\\n    ran: bool = False\\n    froze: bool = False\\n    services_torn_down: bool = False\\n    elapsed_s: float = 0.0\\n    error: str | None = None\\n    # Fork-hostile state left behind by a `run` (empty unless `run=True`). Non-empty here\\n    # means the warm-up is NOT safe to fork/snapshot as-is.\\n    ghost_threads: list[str] = field(default_factory=list)\\n    ghost_connections: list[str] = field(default_factory=list)\\n\\n\\ndef freeze_heap() -> None:\\n    \\\"\\\"\\\"Collect, then freeze the heap so GC stops scanning it (preserves CoW sharing).\\\"\\\"\\\"\\n    gc.collect()\\n    gc.freeze()\\n\\n\\ndef teardown_warm_services() -> None:\\n    \\\"\\\"\\\"Dispose every service instantiated during warming, before a fork/snapshot.\\n\\n    Bundled lfx services are fork-safe no-ops, but a real ``lfx.services`` plugin may open a\\n    DB pool / cache socket / telemetry thread in ``__init__`` that every forked process would\\n    then inherit live. Disposing here mirrors Langflow's ``engine.dispose()`` before its fork.\\n\\n    A teardown failure raises :class:`PrewarmError` rather than capture a half-disposed\\n    process into a fork. Don't call this on the ``--unsafe-run`` path, where live connections\\n    across snapshot/restore are intentional.\\n\\n    Teardown runs in a fresh ``asyncio.run`` loop, so a plugin resource bound to the warm-up\\n    loop (e.g. an asyncpg pool) may fail cross-loop \u2014 that too surfaces as a fatal\\n    :class:`PrewarmError`, never silent corruption.\\n    \\\"\\\"\\\"\\n    import asyncio\\n\\n    from lfx.services.manager import get_service_manager\\n\\n    try:\\n        asyncio.run(get_service_manager().teardown(raise_on_error=True))\\n    except Exception as exc:\\n        msg = f\\\"service teardown before fork/snapshot failed: {exc}\\\"\\n        raise PrewarmError(msg) from exc\\n\\n\\ndef _component_key(module: str, attr: str) -> str:\\n    return f\\\"{module}:{attr}\\\"\\n\\n\\ndef _run_flow_once(graph, input_value: str) -> None:\\n    \\\"\\\"\\\"Execute a built graph once. Must be called without a running event loop.\\\"\\\"\\\"\\n    import asyncio\\n\\n    from lfx.schema.schema import InputValueRequest\\n\\n    # async_start -> astep only reads inputs via .model_dump(), so a raw dict is silently\\n    # dropped; the input must be an InputValueRequest (same as lfx.cli.common.execute_graph).\\n    inputs = InputValueRequest(input_value=input_value) if input_value else None\\n\\n    async def _run() -> None:\\n        # A coroutine, so the span can be made current and the run nests under it.\\n        with graph.flow_execution_span():\\n            async for _ in graph.async_start(inputs=inputs, open_flow_span=False):\\n                pass\\n\\n    asyncio.run(_run())\\n\\n\\n@contextmanager\\ndef _tracing_disabled():\\n    \\\"\\\"\\\"Force ``get_tracing_service()`` to return None for the duration.\\n\\n    The graph and each component resolve the tracing service independently via the shared\\n    lfx/Langflow service manager, so blanking it at the manager is the only reliable way to\\n    keep the warm-up run from tracing. Restores the prior value (or lazy-uncreated state).\\n    \\\"\\\"\\\"\\n    from lfx.services.manager import get_service_manager\\n    from lfx.services.schema import ServiceType\\n\\n    manager = get_service_manager()\\n    sentinel = object()\\n    previous = manager.services.get(ServiceType.TRACING_SERVICE, sentinel)\\n    manager.services[ServiceType.TRACING_SERVICE] = None\\n    try:\\n        yield\\n    finally:\\n        if previous is sentinel:\\n            manager.services.pop(ServiceType.TRACING_SERVICE, None)\\n        else:\\n            manager.services[ServiceType.TRACING_SERVICE] = previous\\n\\n\\ndef _run_hermetic_warmup() -> None:\\n    \\\"\\\"\\\"Build and run one model-free flow to warm the execution machinery.\\n\\n    Uses only in-memory components (ChatInput -> Prompt -> ChatOutput). No model, no\\n    network, no external side effects. Must be called without a running event loop.\\n    \\\"\\\"\\\"\\n    from lfx.components.input_output import ChatInput, ChatOutput\\n    from lfx.components.models_and_agents import PromptComponent\\n    from lfx.graph.graph.base import Graph\\n\\n    chat_input = ChatInput(_id=\\\"prewarm_chat_input\\\")\\n    prompt = PromptComponent(_id=\\\"prewarm_prompt\\\")\\n    prompt.set(template=\\\"{warmup}\\\", warmup=chat_input.message_response)\\n    chat_output = ChatOutput(_id=\\\"prewarm_chat_output\\\")\\n    chat_output.set(input_value=prompt.build_prompt)\\n\\n    graph = Graph(chat_input, chat_output)\\n    graph.prepare()\\n\\n    # Run with tracing disabled. lfx and Langflow share one service manager, so in a Langflow\\n    # process the graph AND each component would otherwise resolve the real tracer and ship a\\n    # junk \\\"prewarm\\\" trace to a configured provider (LangSmith/Langfuse/...) \u2014 and open a\\n    # socket, breaking fork-safety. Blanking the service at the source makes every\\n    # get_tracing_service() return None, so the run takes the no-tracing path. (No DB writes\\n    # either: message store needs a session_id and vertex-build logging a flow_id, and this\\n    # hermetic graph has neither.)\\n    with _tracing_disabled():\\n        _run_flow_once(graph, \\\"prewarm\\\")\\n\\n\\ndef prewarm_core_imports(\\n    components: Sequence[tuple[str, str]] | None = None,\\n    *,\\n    required: Sequence[tuple[str, str]] | None = None,\\n    warmup_run: bool = True,\\n    freeze: bool = False,\\n    teardown_services: bool = True,\\n) -> PrewarmResult:\\n    \\\"\\\"\\\"Warm core component imports (and optionally the execution machinery).\\n\\n    Args:\\n        components: ``(module, class)`` pairs to import. Defaults to\\n            :data:`DEFAULT_CORE_COMPONENTS`.\\n        required: Components whose import failure is fatal (raises :class:`PrewarmError`).\\n            Defaults to whichever requested components are part of the default core set;\\n            anything else that fails is reported in ``result.failed`` instead.\\n        warmup_run: When true (default), run one model-free hermetic flow to warm the\\n            graph execution machinery. In-memory only \u2014 no network, no side effects.\\n        freeze: When true, run ``gc.collect()`` then ``gc.freeze()`` after warming, taking\\n            the warmed objects out of GC's scan set to preserve copy-on-write sharing\\n            across VMs restored from the same snapshot.\\n        teardown_services: When true (default), dispose any services instantiated during\\n            warming (see :func:`teardown_warm_services`) so the process is fork-safe. A\\n            teardown failure raises :class:`PrewarmError`. Set false to keep warmed live\\n            service instances (Firecracker snapshot, which tolerates live state).\\n\\n    Returns:\\n        A :class:`PrewarmResult` describing what imported, what failed, whether the\\n        warm-up run executed, and the elapsed time.\\n    \\\"\\\"\\\"\\n    requested = tuple(components) if components is not None else DEFAULT_CORE_COMPONENTS\\n    required_set = set(required) if required is not None else (set(DEFAULT_CORE_COMPONENTS) & set(requested))\\n\\n    result = PrewarmResult()\\n    start = time.perf_counter()\\n    for module, attr in requested:\\n        try:\\n            getattr(importlib.import_module(module), attr)\\n        except Exception as exc:  # report optional failures, re-raise required ones\\n            if (module, attr) in required_set:\\n                msg = f\\\"required core component {_component_key(module, attr)!r} failed to import: {exc}\\\"\\n                raise PrewarmError(msg) from exc\\n            result.failed[_component_key(module, attr)] = f\\\"{type(exc).__name__}: {exc}\\\"\\n        else:\\n            result.imported.append(_component_key(module, attr))\\n\\n    if warmup_run:\\n        _run_hermetic_warmup()\\n        result.warmup_ran = True\\n\\n    # Dispose warmed service instances BEFORE freezing, so a fork-hostile plugin service\\n    # is not captured into a preload fork (and gc.collect during freeze can reclaim them).\\n    if teardown_services:\\n        teardown_warm_services()\\n        result.services_torn_down = True\\n\\n    if freeze:\\n        freeze_heap()\\n        result.froze = True\\n\\n    result.elapsed_s = time.perf_counter() - start\\n    return result\\n\\n\\ndef prewarm_flow(\\n    flow,\\n    *,\\n    run: bool = False,\\n    input_value: str = \\\"prewarm\\\",\\n    freeze: bool = False,\\n    teardown_services: bool = True,\\n) -> FlowPrewarmResult:\\n    \\\"\\\"\\\"Warm a specific flow by building it, and optionally running it end-to-end.\\n\\n    Because the flow is static, this warms exactly the components it uses \u2014 no\\n    component allow-list, no importing the world.\\n\\n    Args:\\n        flow: Flow JSON as a path, string, or dict (anything ``load_flow_from_json`` accepts).\\n        run: When true, **fully executes** the flow (``async_start``) for maximum warmth.\\n            This fires the flow's **real side effects** (model calls, writes, etc.), so the\\n            caller must supply any required credentials and ensure the flow is idempotent.\\n            When false, only the build path is warmed (no execution, no side effects).\\n        input_value: Input passed to the flow when ``run`` is true.\\n        freeze: When true, freeze the heap after warming (see :func:`freeze_heap`).\\n        teardown_services: When true (default), dispose services instantiated while building\\n            so the process stays fork-safe (raises :class:`PrewarmError` on teardown failure).\\n            Ignored when ``run`` is true \u2014 that path intentionally leaks live connections for\\n            Firecracker snapshot/restore, so tearing services down would defeat it.\\n\\n    Returns:\\n        A :class:`FlowPrewarmResult`. Load/build/run failures are captured in ``error``\\n        rather than raised, so callers warming many flows are not aborted by one bad flow.\\n    \\\"\\\"\\\"\\n    from lfx.load import load_flow_from_json\\n\\n    result = FlowPrewarmResult()\\n    start = time.perf_counter()\\n    graph = None\\n    try:\\n        graph = load_flow_from_json(flow, disable_logs=True)\\n        graph.prepare()\\n        result.built = True\\n        if run:\\n            _run_flow_once(graph, input_value)\\n            result.ran = True\\n    except Exception as exc:  # noqa: BLE001 - capture so multi-flow warming isn't aborted by one failure\\n        result.error = f\\\"{type(exc).__name__}: {exc}\\\"\\n    finally:\\n        # Drop component instances and run finalizers now, closing any per-instance\\n        # connections opened during `run` before a freeze/fork. Module-level import/JIT\\n        # warmth is unaffected.\\n        graph = None  # explicit drop of the only ref before gc\\n        gc.collect()\\n        if run:\\n            # A run can open connections/threads; report what (if anything) survived so the\\n            # caller can refuse to fork/snapshot a dirty process.\\n            from lfx.fork import fork_safety_report\\n\\n            report = fork_safety_report()\\n            result.ghost_threads = report.ghost_threads\\n            result.ghost_connections = report.ghost_connections\\n\\n    # Build-only is the fork-safe path: dispose services before freezing, even if the build\\n    # failed \u2014 a partial build can leave services live and the process fork-unsafe. A `run`\\n    # keeps live state for Firecracker, so never tear down there. Funnel teardown failures\\n    # into .error (not raise) so one bad flow doesn't abort a multi-flow loop.\\n    if teardown_services and not run:\\n        try:\\n            teardown_warm_services()\\n            result.services_torn_down = True\\n        except PrewarmError as exc:\\n            result.error = f\\\"{result.error}; teardown failed: {exc}\\\" if result.error else str(exc)\\n\\n    if freeze:\\n        freeze_heap()\\n        result.froze = True\\n\\n    result.elapsed_s = time.perf_counter() - start\\n    return result\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/processing/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8c445983a8adf6684eceb6d302df58b5a9123573d28d45c587931f281378f300\",\"content\":\"\\\"\\\"\\\"Processing module for lfx package.\\\"\\\"\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/processing/process.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"4858653ab5a3168a15b6d955808cca5c5c796cae2c33c1031890dc32b8257cc3\",\"content\":\"from __future__ import annotations\\n\\nimport json\\nfrom typing import TYPE_CHECKING, Any, cast\\n\\nfrom json_repair import repair_json\\nfrom pydantic import BaseModel\\n\\nfrom lfx.graph.vertex.base import Vertex\\nfrom lfx.graph.vertex.param_handler import ParameterHandler\\nfrom lfx.log.logger import logger\\nfrom lfx.schema.graph import InputValue, Tweaks\\nfrom lfx.schema.schema import INPUT_FIELD_NAME, InputValueRequest\\nfrom lfx.services.deps import get_settings_service\\n\\nif TYPE_CHECKING:\\n    from lfx.events.event_manager import EventManager\\n    from lfx.graph.graph.base import Graph\\n    from lfx.graph.schema import RunOutputs\\n\\n\\ndef validate_and_repair_json(json_str: str | dict) -> dict[str, Any] | str:\\n    \\\"\\\"\\\"Validates a JSON string and attempts to repair it if invalid.\\n\\n    Args:\\n        json_str (str): The JSON string to validate/repair\\n\\n    Returns:\\n        Union[Dict[str, Any], str]: The parsed JSON dict if valid/repairable,\\n        otherwise returns the original string\\n    \\\"\\\"\\\"\\n    if not isinstance(json_str, str):\\n        return json_str\\n    try:\\n        # If invalid, attempt repair\\n        repaired = repair_json(json_str)\\n        return json.loads(repaired)\\n    except (json.JSONDecodeError, ImportError):\\n        # Return original if repair fails or module not found\\n        return json_str\\n\\n\\nclass Result(BaseModel):\\n    result: Any\\n    session_id: str\\n\\n\\ndef validate_targeted_inputs(inputs: list[InputValueRequest] | None) -> None:\\n    \\\"\\\"\\\"Refuse caller-selected input components when the tweak policy is off.\\\"\\\"\\\"\\n    from lfx.utils.flow_validation import TWEAK_POLICY_OFF\\n\\n    if _resolve_tweak_policy() != TWEAK_POLICY_OFF:\\n        return\\n\\n    targeted = sorted({component for request in inputs or [] for component in (request.components or [])})\\n    if targeted:\\n        from lfx.exceptions.tweaks import TweakRefusedError\\n\\n        raise TweakRefusedError(targeted, reason=\\\"This deployment does not accept component-targeted inputs.\\\")\\n\\n\\nasync def run_graph_internal(\\n    graph: Graph,\\n    flow_id: str,\\n    *,\\n    stream: bool = False,\\n    session_id: str | None = None,\\n    inputs: list[InputValueRequest] | None = None,\\n    outputs: list[str] | None = None,\\n    event_manager: EventManager | None = None,\\n) -> tuple[list[RunOutputs], str]:\\n    \\\"\\\"\\\"Run the graph and generate the result.\\\"\\\"\\\"\\n    inputs = inputs or []\\n    effective_session_id = session_id or flow_id\\n\\n    # ``off`` refuses component-targeted inputs as well as tweaks. Both aim a\\n    # value at a named node, so refusing only tweaks would make the setting\\n    # tell a half-truth. ``input_value`` and ``session_id`` keep working.\\n    validate_targeted_inputs(inputs)\\n\\n    components = []\\n    inputs_list = []\\n    types = []\\n    for input_value_request in inputs:\\n        if input_value_request.input_value is None:\\n            await logger.awarning(\\\"InputValueRequest input_value cannot be None, defaulting to an empty string.\\\")\\n            input_value_request.input_value = \\\"\\\"\\n        components.append(input_value_request.components or [])\\n        inputs_list.append({INPUT_FIELD_NAME: input_value_request.input_value})\\n        types.append(input_value_request.type)\\n\\n    try:\\n        fallback_to_env_vars = get_settings_service().settings.fallback_to_env_var\\n    except (AttributeError, TypeError):\\n        fallback_to_env_vars = False\\n\\n    graph.session_id = effective_session_id\\n    run_outputs = await graph.arun(\\n        inputs=inputs_list,\\n        inputs_components=components,\\n        types=types,\\n        outputs=outputs or [],\\n        stream=stream,\\n        session_id=effective_session_id or \\\"\\\",\\n        fallback_to_env_vars=fallback_to_env_vars,\\n        event_manager=event_manager,\\n    )\\n    return run_outputs, effective_session_id\\n\\n\\nasync def run_graph(\\n    graph: Graph,\\n    input_value: str,\\n    input_type: str,\\n    output_type: str,\\n    *,\\n    session_id: str | None = None,\\n    fallback_to_env_vars: bool = False,\\n    output_component: str | None = None,\\n    stream: bool = False,\\n) -> list[RunOutputs]:\\n    \\\"\\\"\\\"Runs the given Langflow Graph with the specified input and returns the outputs.\\n\\n    Args:\\n        graph (Graph): The graph to be executed.\\n        input_value (str): The input value to be passed to the graph.\\n        input_type (str): The type of the input value.\\n        output_type (str): The type of the desired output.\\n        session_id (str | None, optional): The session ID to be used for the flow. Defaults to None.\\n        fallback_to_env_vars (bool, optional): Whether to fallback to environment variables.\\n            Defaults to False.\\n        output_component (Optional[str], optional): The specific output component to retrieve. Defaults to None.\\n        stream (bool, optional): Whether to stream the results or not. Defaults to False.\\n\\n    Returns:\\n        List[RunOutputs]: A list of RunOutputs objects representing the outputs of the graph.\\n\\n    \\\"\\\"\\\"\\n    inputs = [InputValue(components=[], input_value=input_value, type=input_type)]\\n    if output_component:\\n        outputs = [output_component]\\n    else:\\n        outputs = [\\n            vertex.id\\n            for vertex in graph.vertices\\n            if output_type == \\\"debug\\\"\\n            or (vertex.is_output and (output_type == \\\"any\\\" or output_type in vertex.id.lower()))\\n        ]\\n    components = []\\n    inputs_list = []\\n    types = []\\n    for input_value_request in inputs:\\n        if input_value_request.input_value is None:\\n            logger.warning(\\\"InputValueRequest input_value cannot be None, defaulting to an empty string.\\\")\\n            input_value_request.input_value = \\\"\\\"\\n        components.append(input_value_request.components or [])\\n        inputs_list.append({INPUT_FIELD_NAME: input_value_request.input_value})\\n        types.append(input_value_request.type)\\n    return await graph.arun(\\n        inputs_list,\\n        inputs_components=components,\\n        types=types,\\n        outputs=outputs or [],\\n        stream=stream,\\n        session_id=session_id,\\n        fallback_to_env_vars=fallback_to_env_vars,\\n    )\\n\\n\\ndef validate_input(\\n    graph_data: dict[str, Any], tweaks: Tweaks | dict[str, str | dict[str, Any]]\\n) -> list[dict[str, Any]]:\\n    if not isinstance(graph_data, dict) or not isinstance(tweaks, dict):\\n        msg = \\\"graph_data and tweaks should be dictionaries\\\"\\n        raise TypeError(msg)\\n\\n    nodes = graph_data.get(\\\"data\\\", {}).get(\\\"nodes\\\") or graph_data.get(\\\"nodes\\\")\\n\\n    if not isinstance(nodes, list):\\n        msg = \\\"graph_data should contain a list of nodes under 'data' key or directly under 'nodes' key\\\"\\n        raise TypeError(msg)\\n\\n    return nodes\\n\\n\\ndef apply_tweaks(\\n    node: dict[str, Any],\\n    node_tweaks: dict[str, Any],\\n    *,\\n    policy: str = \\\"permissive\\\",\\n    flow_declares_allowlist: bool = False,\\n    exempt_keys: frozenset[str] | None = None,\\n) -> list[str]:\\n    \\\"\\\"\\\"Apply tweaks to one node's template. Return the names this node refused.\\n\\n    The caller aggregates refusals across every node and raises once, so a\\n    single 422 can name every offending key.\\n\\n    ``exempt_keys`` skips the *policy* layer for keys the runtime injected\\n    rather than the caller supplying them. ``stream`` is injected by\\n    ``process_tweaks`` on every request, so without the exemption a strict\\n    policy would refuse every call. The protected-field floor still applies to\\n    exempt keys.\\n    \\\"\\\"\\\"\\n    exempt_keys = exempt_keys or frozenset()\\n    template_data = node.get(\\\"data\\\", {}).get(\\\"node\\\", {}).get(\\\"template\\\")\\n\\n    if not isinstance(template_data, dict):\\n        logger.warning(f\\\"Template data for node {node.get('id')} should be a dictionary\\\")\\n        return []\\n\\n    # One function decides refusals, this one only applies them. Re-deriving the\\n    # floor and the policy here is exactly the shape that produced the original\\n    # bypass: two copies of a security predicate that drifted apart. In the\\n    # two-pass callers this list is already empty by the time we get here, so the\\n    # skip below only matters to direct callers of this function.\\n    refused = _refused_tweak_reasons(\\n        template_data,\\n        node.get(\\\"data\\\", {}).get(\\\"type\\\"),\\n        node_tweaks,\\n        policy=policy,\\n        flow_declares_allowlist=flow_declares_allowlist,\\n        exempt_keys=exempt_keys,\\n    )\\n\\n    for tweak_name, tweak_value in node_tweaks.items():\\n        field = template_data.get(tweak_name)\\n        if not isinstance(field, dict):\\n            continue\\n        if tweak_name in refused:\\n            continue\\n        field_type = field.get(\\\"type\\\", \\\"\\\")\\n        if field_type == \\\"NestedDict\\\":\\n            value = validate_and_repair_json(tweak_value)\\n            template_data[tweak_name][\\\"value\\\"] = value\\n        elif field_type == \\\"mcp\\\":\\n            # MCP fields expect dict values to be set directly\\n            template_data[tweak_name][\\\"value\\\"] = tweak_value\\n        elif field_type == \\\"dict\\\" and isinstance(tweak_value, dict):\\n            # Dict fields: set the dict directly as the value.\\n            # If the tweak is wrapped in {\\\"value\\\": <actual>}, unwrap it\\n            # to support the template-format style (e.g. from UI exports).\\n            # Caveat: a legitimate single-key dict {\\\"value\\\": x} will be unwrapped.\\n            if len(tweak_value) == 1 and \\\"value\\\" in tweak_value:\\n                template_data[tweak_name][\\\"value\\\"] = tweak_value[\\\"value\\\"]\\n            else:\\n                template_data[tweak_name][\\\"value\\\"] = tweak_value\\n        elif isinstance(tweak_value, dict):\\n            for k, v in tweak_value.items():\\n                k_ = \\\"file_path\\\" if field_type == \\\"file\\\" else k\\n                template_data[tweak_name][k_] = v\\n            # If the user didn't explicitly set load_from_db in the dict,\\n            # we default to False for the override.\\n            if \\\"load_from_db\\\" not in tweak_value and \\\"load_from_db\\\" in template_data[tweak_name]:\\n                template_data[tweak_name][\\\"load_from_db\\\"] = False\\n        else:\\n            key = \\\"file_path\\\" if field_type == \\\"file\\\" else \\\"value\\\"\\n            template_data[tweak_name][key] = tweak_value\\n            if \\\"load_from_db\\\" in template_data[tweak_name]:\\n                template_data[tweak_name][\\\"load_from_db\\\"] = False\\n\\n    return list(refused)\\n\\n\\ndef _refused_tweak_reasons(\\n    template_data: dict[str, Any],\\n    component_type: str | None,\\n    node_tweaks: dict[str, Any],\\n    *,\\n    policy: str,\\n    flow_declares_allowlist: bool,\\n    exempt_keys: frozenset[str] = frozenset(),\\n) -> dict[str, str]:\\n    \\\"\\\"\\\"Return each refused field with its caller-facing reason. Mutates nothing.\\n\\n    Refusal has to be decided for the whole request before anything is applied.\\n    Applying as we go and raising at the end leaves the accepted half written,\\n    and the graph the run paths hand us is cached and reused, so that half\\n    survives into later runs that send no tweaks at all.\\n    \\\"\\\"\\\"\\n    refused: dict[str, str] = {}\\n    for tweak_name in node_tweaks:\\n        field = template_data.get(tweak_name)\\n        if not isinstance(field, dict):\\n            continue\\n        reason = _tweak_refusal_reason(\\n            component_type,\\n            tweak_name,\\n            field.get(\\\"type\\\", \\\"\\\"),\\n            policy,\\n            flow_declares_allowlist=flow_declares_allowlist,\\n            field_is_api_editable=field.get(\\\"api_editable\\\") is True,\\n            policy_exempt=tweak_name in exempt_keys,\\n        )\\n        if reason is not None:\\n            if reason == _PROTECTED_TWEAK_REASON:\\n                logger.warning(f\\\"Security: refusing to override protected field {tweak_name!r} via tweaks.\\\")\\n            else:\\n                logger.warning(f\\\"Policy {policy!r}: refusing to override field {tweak_name!r} via tweaks.\\\")\\n            refused[tweak_name] = reason\\n    return refused\\n\\n\\ndef _resolve_tweak_policy() -> str:\\n    \\\"\\\"\\\"Return the deployment tweak policy, defaulting to permissive.\\n\\n    Settings are unavailable in some library contexts, so a missing settings\\n    service falls back to the default rather than failing the run.\\n    \\\"\\\"\\\"\\n    from lfx.utils.flow_validation import TWEAK_POLICIES, TWEAK_POLICY_PERMISSIVE\\n\\n    try:\\n        policy = get_settings_service().settings.tweaks_policy\\n    except (AttributeError, TypeError):\\n        return TWEAK_POLICY_PERMISSIVE\\n    if policy not in TWEAK_POLICIES:\\n        logger.warning(f\\\"Unknown tweaks policy {policy!r}; falling back to {TWEAK_POLICY_PERMISSIVE!r}.\\\")\\n        return TWEAK_POLICY_PERMISSIVE\\n    return policy\\n\\n\\ndef _effective_policy(*, caller_supplied: bool) -> str:\\n    \\\"\\\"\\\"Return the policy to enforce for this application of tweaks.\\n\\n    The deployment policy answers \\\"what may a caller override\\\". Tweaks the\\n    runtime generated for itself are not a caller overriding anything, so they\\n    are judged as ``permissive``: the protected-field floor still refuses, and\\n    the policy layer stays out of it. This is the same reasoning that exempts\\n    the injected ``stream`` key.\\n    \\\"\\\"\\\"\\n    from lfx.utils.flow_validation import TWEAK_POLICY_PERMISSIVE\\n\\n    if not caller_supplied:\\n        return TWEAK_POLICY_PERMISSIVE\\n    return _resolve_tweak_policy()\\n\\n\\n_PROTECTED_TWEAK_REASON = \\\"The field is protected and keeps the value set by the flow author.\\\"\\n_DECLARED_TWEAK_REASON = (\\n    \\\"This flow declares which fields the API may set. Only fields marked editable via API accept a tweak.\\\"\\n)\\n_OFF_TWEAK_REASON = \\\"This deployment does not accept tweaks.\\\"\\n_REFUSAL_REASON_ORDER = (_PROTECTED_TWEAK_REASON, _DECLARED_TWEAK_REASON, _OFF_TWEAK_REASON)\\n\\n\\ndef _tweak_refusal_reason(\\n    component_type: str | None,\\n    field_name: str,\\n    field_type: str,\\n    policy: str,\\n    *,\\n    flow_declares_allowlist: bool,\\n    field_is_api_editable: bool,\\n    policy_exempt: bool,\\n) -> str | None:\\n    \\\"\\\"\\\"Return the single caller-facing reason for refusing a field, if any.\\n\\n    Under ``off``, the policy alone refuses every caller-supplied field. Keep\\n    that response uniform so probing one field at a time cannot reveal which\\n    fields are also protected by the deployment floor. In the other modes the\\n    floor takes precedence, which is the distinction LE-2387 needs under\\n    ``declared``.\\n    \\\"\\\"\\\"\\n    from lfx.utils.flow_validation import (\\n        TWEAK_POLICY_OFF,\\n        is_protected_tweak_field,\\n        is_tweak_refused_by_policy,\\n    )\\n\\n    refused_by_policy = not policy_exempt and is_tweak_refused_by_policy(\\n        policy,\\n        flow_declares_allowlist=flow_declares_allowlist,\\n        field_is_api_editable=field_is_api_editable,\\n    )\\n    if refused_by_policy and policy == TWEAK_POLICY_OFF:\\n        return _OFF_TWEAK_REASON\\n    if is_protected_tweak_field(component_type, field_name, field_type):\\n        return _PROTECTED_TWEAK_REASON\\n    if refused_by_policy:\\n        return _DECLARED_TWEAK_REASON\\n    return None\\n\\n\\ndef _combined_refusal_reason(refused: list[tuple[str, str]]) -> str:\\n    \\\"\\\"\\\"Combine the generic reasons present in a request in stable priority order.\\\"\\\"\\\"\\n    present_reasons = {reason for _, reason in refused}\\n    return \\\" \\\".join(reason for reason in _REFUSAL_REASON_ORDER if reason in present_reasons)\\n\\n\\ndef apply_tweaks_on_vertex(\\n    vertex: Vertex,\\n    node_tweaks: dict[str, Any],\\n    *,\\n    policy: str = \\\"permissive\\\",\\n    flow_declares_allowlist: bool = False,\\n) -> list[str]:\\n    \\\"\\\"\\\"Apply tweaks to a built vertex. Return the names this vertex refused.\\n\\n    The graph-level path runs after ``Graph`` construction, so it enforces the\\n    same protected-field floor and deployment policy as the pre-construction\\n    ``apply_tweaks``. Before this, the floor was applied inconsistently here and\\n    the policy not at all, so the streaming and background run modes accepted\\n    tweaks the sync mode refused.\\n\\n    The override is written through ``update_raw_params`` as well as\\n    ``vertex.params``. Setting ``params`` alone does not reach the built\\n    component at runtime, which is the bug the two former private copies of this\\n    function existed to work around.\\n    \\\"\\\"\\\"\\n    template_data = vertex.data.get(\\\"node\\\", {}).get(\\\"template\\\", {})\\n    if not isinstance(template_data, dict):\\n        # No usable template means nothing can be validated, so nothing is\\n        # applied. Refusing here instead would turn a malformed node into a\\n        # caller-facing error the caller cannot act on.\\n        return []\\n\\n    # Same single-predicate rule as ``apply_tweaks``: this function applies, it\\n    # does not re-decide. Two copies of the floor are what let the graph path\\n    # accept tweaks the sync path refused in the first place.\\n    refused = _refused_tweak_reasons(\\n        template_data,\\n        vertex.data.get(\\\"type\\\"),\\n        node_tweaks,\\n        policy=policy,\\n        flow_declares_allowlist=flow_declares_allowlist,\\n    )\\n\\n    accepted: dict[str, Any] = {}\\n    for tweak_name, tweak_value in node_tweaks.items():\\n        field = template_data.get(tweak_name)\\n        # A key the template does not declare is skipped, not refused. This\\n        # matches ``apply_tweaks`` on the pre-construction path: an unknown key\\n        # has never been an error, and treating it as one here would 422 every\\n        # caller who sends a tweak for a component the flow no longer has.\\n        if not isinstance(field, dict):\\n            continue\\n        if tweak_name in refused:\\n            continue\\n\\n        accepted[tweak_name] = tweak_value\\n\\n        if tweak_name and tweak_value and tweak_name in vertex.params:\\n            vertex.params[tweak_name] = tweak_value\\n\\n            # Determine if we should load from DB\\n            tweak_load_from_db = False\\n            if isinstance(tweak_value, dict):\\n                tweak_load_from_db = tweak_value.get(\\\"load_from_db\\\", False)\\n\\n            if tweak_load_from_db:\\n                if tweak_name not in vertex.load_from_db_fields:\\n                    vertex.load_from_db_fields.append(tweak_name)\\n            elif tweak_name in vertex.load_from_db_fields:\\n                vertex.load_from_db_fields.remove(tweak_name)\\n\\n    if accepted:\\n        vertex.update_raw_params(accepted, overwrite=True)\\n\\n    return list(refused)\\n\\n\\ndef process_tweaks(\\n    graph_data: dict[str, Any],\\n    tweaks: Tweaks | dict[str, dict[str, Any]],\\n    *,\\n    stream: bool = False,\\n    caller_supplied: bool = True,\\n) -> dict[str, Any]:\\n    \\\"\\\"\\\"This function is used to tweak the graph data using the node id and the tweaks dict.\\n\\n    :param graph_data: The dictionary containing the graph data. It must contain a 'data' key with\\n                       'nodes' as its child or directly contain 'nodes' key. Each node should have an 'id' and 'data'.\\n    :param tweaks: The dictionary containing the tweaks. The keys can be the node id or the name of the tweak.\\n                   The values can be a dictionary containing the tweaks for the node or the value of the tweak.\\n    :param stream: A boolean flag indicating whether streaming should be deactivated across all components or not.\\n                   Default is False.\\n    :param caller_supplied: Whether these tweaks came from a run request. Pass False when the runtime\\n                   generated them itself, e.g. resolved variable values. Runtime-generated tweaks skip\\n                   the deployment policy for the same reason ``stream`` does: the policy governs what a\\n                   caller may override, and refusing a value the runtime produced would disable internal\\n                   machinery rather than restrict an API. The protected-field floor still applies.\\n    :return: The modified graph_data dictionary.\\n    :raises ValueError: If the input is not in the expected format.\\n    \\\"\\\"\\\"\\n    from lfx.exceptions.tweaks import TweakRefusedError\\n    from lfx.utils.flow_validation import flow_declares_api_editable\\n\\n    # Copied, not aliased: ``stream`` is injected below, and writing that into\\n    # the caller's own dict makes the key look caller-supplied on a second run\\n    # with the same dict. The exemption would not apply and a strict policy\\n    # would refuse ``stream``, a key the caller never sent.\\n    tweaks_dict = cast(\\\"dict[str, Any]\\\", tweaks.model_dump()) if not isinstance(tweaks, dict) else dict(tweaks)\\n    # ``stream`` is injected here rather than supplied by the caller, so the\\n    # policy layer must not refuse it. Without this the strict policies would\\n    # reject every request that omits ``stream``.\\n    exempt_keys: frozenset[str] = frozenset()\\n    if \\\"stream\\\" not in tweaks_dict:\\n        tweaks_dict |= {\\\"stream\\\": stream}\\n        exempt_keys = frozenset({\\\"stream\\\"})\\n    nodes = validate_input(graph_data, cast(\\\"dict[str, str | dict[str, Any]]\\\", tweaks_dict))\\n    nodes_map = {node.get(\\\"id\\\"): node for node in nodes}\\n    nodes_display_name_map = {node.get(\\\"data\\\", {}).get(\\\"node\\\", {}).get(\\\"display_name\\\"): node for node in nodes}\\n\\n    policy = _effective_policy(caller_supplied=caller_supplied)\\n    flow_declares_allowlist = flow_declares_api_editable(nodes)\\n    refused: list[tuple[str, str]] = []\\n\\n    all_nodes_tweaks = {}\\n    pending: list[tuple[dict[str, Any], dict[str, Any]]] = []\\n    for key, value in tweaks_dict.items():\\n        if isinstance(value, dict):\\n            if (node := nodes_map.get(key)) or (node := nodes_display_name_map.get(key)):\\n                pending.append((node, value))\\n        else:\\n            all_nodes_tweaks[key] = value\\n    if all_nodes_tweaks:\\n        pending.extend((node, all_nodes_tweaks) for node in nodes)\\n\\n    # Decide first, mutate second. A refusal must leave the payload untouched.\\n    for node, node_tweaks in pending:\\n        template_data = node.get(\\\"data\\\", {}).get(\\\"node\\\", {}).get(\\\"template\\\")\\n        if not isinstance(template_data, dict):\\n            continue\\n        refused.extend(\\n            _refused_tweak_reasons(\\n                template_data,\\n                node.get(\\\"data\\\", {}).get(\\\"type\\\"),\\n                node_tweaks,\\n                policy=policy,\\n                flow_declares_allowlist=flow_declares_allowlist,\\n                exempt_keys=exempt_keys,\\n            ).items()\\n        )\\n\\n    if refused:\\n        refused_fields = sorted({field_name for field_name, _ in refused})\\n        raise TweakRefusedError(refused_fields, reason=_combined_refusal_reason(refused))\\n\\n    for node, node_tweaks in pending:\\n        apply_tweaks(\\n            node,\\n            node_tweaks,\\n            policy=policy,\\n            flow_declares_allowlist=flow_declares_allowlist,\\n            exempt_keys=exempt_keys,\\n        )\\n\\n    return graph_data\\n\\n\\ndef process_tweaks_on_graph(graph: Graph, tweaks: dict[str, dict[str, Any]], *, caller_supplied: bool = True):\\n    \\\"\\\"\\\"Apply tweaks to a built graph, enforcing the floor and the policy.\\n\\n    This is the post-construction counterpart to ``process_tweaks``. The\\n    streaming and background run modes build the graph first, so they land here\\n    rather than there. Both paths must refuse the same tweaks, or the deployment\\n    policy would only govern the sync mode.\\n\\n    ``caller_supplied=False`` marks tweaks the runtime built rather than a caller\\n    sending them. The Run Flow component passes its own declared inputs through\\n    here to reach a sub-flow, so judging those against the deployment policy\\n    would make ``off`` disable flow-as-tool orchestration instead of closing an\\n    API surface. The floor still applies.\\n    \\\"\\\"\\\"\\n    from lfx.exceptions.tweaks import TweakRefusedError\\n    from lfx.utils.flow_validation import flow_declares_api_editable\\n\\n    policy = _effective_policy(caller_supplied=caller_supplied)\\n    # ``flow_declares_api_editable`` reads node dicts shaped ``{\\\"data\\\": {...}}``.\\n    # ``vertex.data`` is already that inner mapping, so wrap it back up.\\n    flow_declares_allowlist = flow_declares_api_editable(\\n        [{\\\"data\\\": v.data} for v in graph.vertices if isinstance(v, Vertex) and isinstance(v.data, dict)]\\n    )\\n    refused: list[tuple[str, str]] = []\\n\\n    pending: list[tuple[Vertex, dict[str, Any]]] = []\\n    for vertex in graph.vertices:\\n        if isinstance(vertex, Vertex) and isinstance(vertex.id, str):\\n            if node_tweaks := tweaks.get(vertex.id):\\n                pending.append((vertex, node_tweaks))\\n        else:\\n            logger.warning(\\\"Each node should be a Vertex with an 'id' attribute of type str\\\")\\n\\n    # Decide first, mutate second. The graph reaching this function is cached and\\n    # reused by the Run Flow component, so a half-applied payload would survive\\n    # into later runs of the same sub-flow.\\n    for vertex, node_tweaks in pending:\\n        template_data = vertex.data.get(\\\"node\\\", {}).get(\\\"template\\\", {})\\n        if not isinstance(template_data, dict):\\n            continue\\n        refused.extend(\\n            _refused_tweak_reasons(\\n                template_data,\\n                vertex.data.get(\\\"type\\\"),\\n                node_tweaks,\\n                policy=policy,\\n                flow_declares_allowlist=flow_declares_allowlist,\\n            ).items()\\n        )\\n\\n    if refused:\\n        refused_fields = sorted({field_name for field_name, _ in refused})\\n        raise TweakRefusedError(refused_fields, reason=_combined_refusal_reason(refused))\\n\\n    # FileInput validation can still reject an otherwise policy-allowed tweak. Validate every\\n    # target before applying any of them so a later invalid vertex cannot leave an earlier cached\\n    # vertex mutated. Keep the original values for application: unrestricted local paths are a\\n    # compatibility contract, and this pass exists only to validate them atomically.\\n    for vertex, node_tweaks in pending:\\n        template_data = vertex.data.get(\\\"node\\\", {}).get(\\\"template\\\", {})\\n    ";
